/* =========================================================
  브랜드 관리 메시지 표시
========================================================= */

function showBrandManagementMessage(
  message,
  type = "info"
) {
  const {
    message: messageElement
  } =
    getBrandManagementElements();


  if (
    !messageElement
  ) {
    return;
  }


  messageElement.textContent =
    String(
      message ||
      ""
    );


  messageElement.dataset.type =
    type;


  messageElement.hidden =
    !message;
}


/* =========================================================
  브랜드 관리 메시지 숨기기
========================================================= */

function hideBrandManagementMessage() {
  showBrandManagementMessage(
    ""
  );
}


/* =========================================================
  관리자 화면 탭 전환

  employees:
  - 직원 관리

  brand:
  - 브랜드 관리
========================================================= */

function switchSystemAdminView(
  requestedView
) {
  const {
    employeeTabButton,
    brandTabButton,
    employeeView,
    brandView,
    footerHelp,
    saveBrandButton
  } =
    getBrandManagementElements();


  const normalizedView =
    requestedView ===
      "brand"
      ? "brand"
      : "employees";


  const isEmployeeView =
    normalizedView ===
      "employees";


  employeeTabButton
    ?.classList
    .toggle(
      "is-active",
      isEmployeeView
    );


  brandTabButton
    ?.classList
    .toggle(
      "is-active",
      !isEmployeeView
    );


  employeeTabButton
    ?.setAttribute(
      "aria-selected",
      String(
        isEmployeeView
      )
    );


  brandTabButton
    ?.setAttribute(
      "aria-selected",
      String(
        !isEmployeeView
      )
    );


  if (
    employeeView
  ) {
    employeeView.hidden =
      !isEmployeeView;


    employeeView.classList.toggle(
      "is-active",
      isEmployeeView
    );
  }


  if (
    brandView
  ) {
    brandView.hidden =
      isEmployeeView;


    brandView.classList.toggle(
      "is-active",
      !isEmployeeView
    );
  }


  if (
    saveBrandButton
  ) {
    saveBrandButton.hidden =
      isEmployeeView;
  }


  if (
    footerHelp
  ) {
    footerHelp.textContent =
      isEmployeeView
        ? "계정을 중지하면 해당 직원은 로그인할 수 없습니다."
        : "저장 전 미리보기에서 로그인 화면과 상단 로고를 확인해 주세요.";
  }


  if (
    !isEmployeeView
  ) {
    updateBrandManagementPreview();
  }
}


/* =========================================================
  이미지 파일 검사

  지원:
  - PNG
  - JPEG
  - WEBP

  최대:
  - 15MB
========================================================= */

function validateBrandImageFile(
  file
) {
  if (
    !file
  ) {
    return {
      valid:
        false,

      message:
        "이미지 파일을 선택해 주세요."
    };
  }


  const allowedTypes = [
    "image/png",
    "image/jpeg",
    "image/webp"
  ];


  if (
    !allowedTypes.includes(
      file.type
    )
  ) {
    return {
      valid:
        false,

      message:
        "PNG, JPG, WEBP 이미지만 사용할 수 있습니다."
    };
  }


  const maximumFileSize =
    15 *
    1024 *
    1024;


  if (
    file.size >
    maximumFileSize
  ) {
    return {
      valid:
        false,

      message:
        "이미지 파일은 15MB 이하로 선택해 주세요."
    };
  }


  return {
    valid:
      true,

    message:
      ""
  };
}


/* =========================================================
  기존 Object URL 해제
========================================================= */

function revokeBrandPreviewUrl(
  previewUrl
) {
  if (
    !previewUrl ||
    !String(
      previewUrl
    ).startsWith(
      "blob:"
    )
  ) {
    return;
  }


  URL.revokeObjectURL(
    previewUrl
  );
}

/* =========================================================
  회사 로고 파일 선택

  저장 전에는 Blob URL로만 미리보기하며,
  저장 버튼을 누르면 원본 File을 R2로 전송한다.
========================================================= */

function handleBrandLogoFileChange(
  event
) {
  const file =
    event.target.files?.[0] ||
    null;


  if (
    !file
  ) {
    return;
  }


  const validationResult =
    validateBrandImageFile(
      file
    );


  if (
    !validationResult.valid
  ) {
    event.target.value =
      "";


    showBrandManagementMessage(
      validationResult.message,
      "error"
    );


    return;
  }


  revokeBrandPreviewUrl(
    brandManagementState.logoPreviewUrl
  );


  brandManagementState.logoFile =
    file;


  brandManagementState.logoPreviewUrl =
    URL.createObjectURL(
      file
    );


  brandManagementState.logoRemoved =
    false;


  hideBrandManagementMessage();


  updateBrandManagementPreview();
}

/* =========================================================
  로그인 배경 파일 선택

  저장 전에는 Blob URL로만 미리보기하며,
  저장 버튼을 누르면 원본 File을 R2로 전송한다.
========================================================= */

function handleBrandBackgroundFileChange(
  event
) {
  const file =
    event.target.files?.[0] ||
    null;


  if (
    !file
  ) {
    return;
  }


  const validationResult =
    validateBrandImageFile(
      file
    );


  if (
    !validationResult.valid
  ) {
    event.target.value =
      "";


    showBrandManagementMessage(
      validationResult.message,
      "error"
    );


    return;
  }


  revokeBrandPreviewUrl(
    brandManagementState.backgroundPreviewUrl
  );


  brandManagementState.backgroundFile =
    file;


  brandManagementState.backgroundPreviewUrl =
    URL.createObjectURL(
      file
    );


  brandManagementState.backgroundRemoved =
    false;


  hideBrandManagementMessage();


  updateBrandManagementPreview();
}

/* =========================================================
  회사 로고 삭제 상태

  실제 R2 삭제는 저장 버튼 클릭 시 처리한다.
========================================================= */

function removeBrandLogoPreview() {
  const {
    logoFileInput
  } =
    getBrandManagementElements();


  revokeBrandPreviewUrl(
    brandManagementState.logoPreviewUrl
  );


  brandManagementState.logoFile =
    null;


  brandManagementState.logoPreviewUrl =
    "";


  brandManagementState.logoRemoved =
    true;


  if (
    logoFileInput
  ) {
    logoFileInput.value =
      "";
  }


  updateBrandManagementPreview();


  showBrandManagementMessage(
    "회사 로고를 삭제 상태로 변경했습니다. 저장 버튼을 눌러 적용해 주세요.",
    "warning"
  );
}

/* =========================================================
  로그인 배경 삭제 상태

  실제 R2 삭제는 저장 버튼 클릭 시 처리한다.
========================================================= */

function removeBrandBackgroundPreview() {
  const {
    backgroundFileInput
  } =
    getBrandManagementElements();


  revokeBrandPreviewUrl(
    brandManagementState.backgroundPreviewUrl
  );


  brandManagementState.backgroundFile =
    null;


  brandManagementState.backgroundPreviewUrl =
    "";


  brandManagementState.backgroundRemoved =
    true;


  if (
    backgroundFileInput
  ) {
    backgroundFileInput.value =
      "";
  }


  updateBrandManagementPreview();


  showBrandManagementMessage(
    "로그인 배경을 삭제 상태로 변경했습니다. 저장 버튼을 눌러 적용해 주세요.",
    "warning"
  );
}

/* =========================================================
  이미지 미리보기 HTML 생성
========================================================= */

function renderBrandImagePreview(
  container,
  imageUrl,
  options = {}
) {
  if (
    !container
  ) {
    return;
  }


  const {
    emptyTitle =
      "이미지 미리보기",

    emptyDescription =
      "이미지를 선택해 주세요.",

    alt =
      "브랜드 이미지"
  } = options;


  if (
    !imageUrl
  ) {
    container.innerHTML = `
      <div class="brand-preview__empty">

        <strong>
          ${escapeEmployeeManagementHtml(
            emptyTitle
          )}
        </strong>

        <span>
          ${escapeEmployeeManagementHtml(
            emptyDescription
          )}
        </span>

      </div>
    `;


    return;
  }


  container.innerHTML = `
    <img
      src="${escapeEmployeeManagementHtml(
        imageUrl
      )}"
      alt="${escapeEmployeeManagementHtml(
        alt
      )}"
    />
  `;
}


/* =========================================================
  최종 미리보기 로고 적용

  이미지가 없으면 GS 기본 마크 표시
========================================================= */

function applyBrandLogoPreview(
  container,
  logoUrl
) {
  if (
    !container
  ) {
    return;
  }


  if (
    logoUrl
  ) {
    container.classList.add(
      "has-image"
    );


    container.innerHTML = `
      <img
        src="${escapeEmployeeManagementHtml(
          logoUrl
        )}"
        alt="회사 로고"
      />
    `;


    return;
  }


  container.classList.remove(
    "has-image"
  );


  container.textContent =
    "GS";
}

/* =========================================================
  브랜드 설정 실시간 미리보기 갱신
========================================================= */

function updateBrandManagementPreview() {
  const {
    companyNameInput,
    programNameInput,
    programSubtitleInput,

    logoPreview,
    backgroundPreview,

    positionXInput,
    positionYInput,
    overlayInput,

    positionXValue,
    positionYValue,
    overlayValue,

    loginFinalPreview,
    loginFinalPreviewLogo,
    loginFinalPreviewCompany,
    loginFinalPreviewProgram,
    loginFinalPreviewSubtitle,

    headerFinalPreviewLogo,
    headerFinalPreviewProgram,
    headerFinalPreviewCompany
  } =
    getBrandManagementElements();


  const companyName =
    String(
      companyNameInput?.value ||
      brandManagementState
        .savedSettings
        .companyName ||
      DEFAULT_BRAND_SETTINGS
        .companyName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .companyName;


  const programName =
    String(
      programNameInput?.value ||
      brandManagementState
        .savedSettings
        .programName ||
      DEFAULT_BRAND_SETTINGS
        .programName
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .programName;


  const programSubtitle =
    String(
      programSubtitleInput?.value ||
      brandManagementState
        .savedSettings
        .programSubtitle ||
      DEFAULT_BRAND_SETTINGS
        .programSubtitle
    ).trim() ||
    DEFAULT_BRAND_SETTINGS
      .programSubtitle;


  const positionX =
    clampBrandNumber(
      positionXInput?.value,
      0,
      100,
      DEFAULT_BRAND_SETTINGS
        .backgroundPositionX
    );


  const positionY =
    clampBrandNumber(
      positionYInput?.value,
      0,
      100,
      DEFAULT_BRAND_SETTINGS
        .backgroundPositionY
    );


  const overlayPercent =
    clampBrandNumber(
      overlayInput?.value,
      0,
      80,
      DEFAULT_BRAND_SETTINGS
        .backgroundOverlay
    );


  const overlayOpacity =
    overlayPercent /
    100;


  const logoUrl =
    getCurrentBrandLogoUrl();


  const backgroundUrl =
    getCurrentBrandBackgroundUrl();


  /* =====================================================
    단독 이미지 미리보기
  ====================================================== */

  renderBrandImagePreview(
    logoPreview,
    logoUrl,
    {
      emptyTitle:
        "회사 로고 미리보기",

      emptyDescription:
        "PNG·JPG·WEBP 이미지",

      alt:
        "회사 로고 미리보기"
    }
  );


  renderBrandImagePreview(
    backgroundPreview,
    backgroundUrl,
    {
      emptyTitle:
        "로그인 배경 미리보기",

      emptyDescription:
        "가로형 고화질 이미지를 권장합니다.",

      alt:
        "로그인 배경 미리보기"
    }
  );


  /* =====================================================
    로그인 미리보기 텍스트
  ====================================================== */

  if (
    loginFinalPreviewCompany
  ) {
    loginFinalPreviewCompany.textContent =
      companyName;
  }


  if (
    loginFinalPreviewProgram
  ) {
    loginFinalPreviewProgram.textContent =
      programName;
  }


  if (
    loginFinalPreviewSubtitle
  ) {
    loginFinalPreviewSubtitle.textContent =
      programSubtitle;
  }


  /* =====================================================
    헤더 미리보기 텍스트
  ====================================================== */

  if (
    headerFinalPreviewProgram
  ) {
    headerFinalPreviewProgram.textContent =
      programName;
  }


  if (
    headerFinalPreviewCompany
  ) {
    headerFinalPreviewCompany.textContent =
      companyName;
  }


  /* =====================================================
    로그인·헤더 로고
  ====================================================== */

  applyBrandLogoPreview(
    loginFinalPreviewLogo,
    logoUrl
  );


  applyBrandLogoPreview(
    headerFinalPreviewLogo,
    logoUrl
  );


  /* =====================================================
    로그인 배경 미리보기
  ====================================================== */

  if (
    loginFinalPreview
  ) {
    loginFinalPreview.style
      .backgroundImage =
      backgroundUrl
        ? `linear-gradient(
            rgba(
              10,
              28,
              54,
              ${overlayOpacity}
            ),
            rgba(
              10,
              28,
              54,
              ${overlayOpacity}
            )
          ),
          url("${backgroundUrl}")`
        : `linear-gradient(
            135deg,
            #17385f,
            #2b69ad
          )`;


    loginFinalPreview.style
      .backgroundPosition =
      `${positionX}% ${positionY}%`;


    loginFinalPreview.style
      .backgroundSize =
      "cover";
  }


  /* =====================================================
    슬라이더 표시값
  ====================================================== */

  if (
    positionXValue
  ) {
    positionXValue.textContent =
      `${positionX}%`;
  }


  if (
    positionYValue
  ) {
    positionYValue.textContent =
      `${positionY}%`;
  }


  if (
    overlayValue
  ) {
    overlayValue.textContent =
      `${overlayPercent}%`;
  }


  /*
    실제 로그인 화면과 상단 헤더에도
    현재 설정을 즉시 반영한다.
  */
  applyBrandManagementToActualScreen();
}

/* =========================================================
  브랜드 설정 서버 저장

  POST /api/brand-settings

  저장:
  - 회사명·프로그램명·표시 설정 → D1
  - 회사 로고·로그인 배경 → R2
========================================================= */

async function handleBrandManagementSavePreview() {
  if (
    brandManagementState.isSaving
  ) {
    return;
  }


  const {
    companyNameInput,
    programNameInput,
    programSubtitleInput,

    positionXInput,
    positionYInput,
    overlayInput,

    logoFileInput,
    backgroundFileInput,

    saveBrandButton
  } =
    getBrandManagementElements();


  const companyName =
    String(
      companyNameInput?.value ||
      ""
    ).trim();


  const programName =
    String(
      programNameInput?.value ||
      ""
    ).trim();


  const programSubtitle =
    String(
      programSubtitleInput?.value ||
      ""
    ).trim();


  if (
    !companyName
  ) {
    showBrandManagementMessage(
      "회사명을 입력해 주세요.",
      "error"
    );


    companyNameInput?.focus();


    return;
  }


  if (
    !programName
  ) {
    showBrandManagementMessage(
      "프로그램명을 입력해 주세요.",
      "error"
    );


    programNameInput?.focus();


    return;
  }


  if (
    !programSubtitle
  ) {
    showBrandManagementMessage(
      "프로그램 설명을 입력해 주세요.",
      "error"
    );


    programSubtitleInput?.focus();


    return;
  }


  const sessionToken =
    getShiftLogSessionToken();


  if (
    !sessionToken
  ) {
    showBrandManagementMessage(
      "로그인 세션을 확인할 수 없습니다. 다시 로그인해 주세요.",
      "error"
    );


    return;
  }


  const formData =
    new FormData();


  formData.append(
    "companyName",
    companyName
  );


  formData.append(
    "programName",
    programName
  );


  formData.append(
    "programSubtitle",
    programSubtitle
  );


  formData.append(
    "backgroundPositionX",
    String(
      clampBrandNumber(
        positionXInput?.value,
        0,
        100,
        DEFAULT_BRAND_SETTINGS.backgroundPositionX
      )
    )
  );


  formData.append(
    "backgroundPositionY",
    String(
      clampBrandNumber(
        positionYInput?.value,
        0,
        100,
        DEFAULT_BRAND_SETTINGS.backgroundPositionY
      )
    )
  );


  formData.append(
    "backgroundOverlay",
    String(
      clampBrandNumber(
        overlayInput?.value,
        0,
        80,
        DEFAULT_BRAND_SETTINGS.backgroundOverlay
      )
    )
  );


  /*
    새로 선택한 파일이 있는 경우에만 업로드한다.
  */
  if (
    brandManagementState.logoFile instanceof
      File
  ) {
    formData.append(
      "logo",
      brandManagementState.logoFile,
      brandManagementState.logoFile.name
    );
  }


  if (
    brandManagementState.backgroundFile instanceof
      File
  ) {
    formData.append(
      "background",
      brandManagementState.backgroundFile,
      brandManagementState.backgroundFile.name
    );
  }


  /*
    삭제 버튼을 누른 상태는 별도 boolean으로 전달한다.
  */
  formData.append(
    "removeLogo",
    String(
      brandManagementState.logoRemoved
    )
  );


  formData.append(
    "removeBackground",
    String(
      brandManagementState.backgroundRemoved
    )
  );


  brandManagementState.isSaving =
    true;


  if (
    saveBrandButton
  ) {
    saveBrandButton.disabled =
      true;


    saveBrandButton.textContent =
      "저장 중...";
  }


  showBrandManagementMessage(
    "브랜드 설정과 이미지를 저장하고 있습니다.",
    "info"
  );


  try {
    const response =
      await fetch(
        BRAND_SETTINGS_API_URL,
        {
          method:
            "POST",

          headers: {
            Accept:
              "application/json",

            Authorization:
              `Bearer ${sessionToken}`
          },

          body:
            formData,

          cache:
            "no-store"
        }
      );


    const responseText =
      await response.text();


    let result = {};


    if (
      responseText.trim()
    ) {
      try {
        result =
          JSON.parse(
            responseText
          );

      } catch {
        throw new Error(
          "브랜드 설정 저장 서버 응답 형식이 올바르지 않습니다."
        );
      }
    }


    if (
      !response.ok ||
      result.ok === false
    ) {
      throw new Error(
        result.message ||
        result.error ||
        `브랜드 설정 저장 실패 (HTTP ${response.status})`
      );
    }


    const savedSettings =
      normalizeBrandSettings(
        result.brand ||
        result.data ||
        result
      );


    /*
      저장 전에 사용하던 Blob URL을 정리한다.
    */
    revokeBrandPreviewUrl(
      brandManagementState.logoPreviewUrl
    );


    revokeBrandPreviewUrl(
      brandManagementState.backgroundPreviewUrl
    );


    brandManagementState.savedSettings = {
      ...savedSettings
    };


    brandManagementState.logoFile =
      null;


    brandManagementState.logoPreviewUrl =
      "";


    brandManagementState.logoRemoved =
      false;


    brandManagementState.backgroundFile =
      null;


    brandManagementState.backgroundPreviewUrl =
      "";


    brandManagementState.backgroundRemoved =
      false;


    if (
      logoFileInput
    ) {
      logoFileInput.value =
        "";
    }


    if (
      backgroundFileInput
    ) {
      backgroundFileInput.value =
        "";
    }


    populateBrandManagementForm(
      savedSettings
    );


    updateBrandManagementPreview();


    showBrandManagementMessage(
      "브랜드 설정을 저장했습니다. 모든 사용자에게 동일하게 적용됩니다.",
      "success"
    );


    showToast(
      "브랜드 설정이 저장되었습니다."
    );


    console.log(
      "브랜드 설정 서버 저장 완료:",
      savedSettings
    );

  } catch (
    error
  ) {
    console.error(
      "브랜드 설정 서버 저장 오류:",
      error
    );


    showBrandManagementMessage(
      error.message ||
      "브랜드 설정을 저장하지 못했습니다.",
      "error"
    );


    showToast(
      error.message ||
      "브랜드 설정 저장에 실패했습니다."
    );

  } finally {
    brandManagementState.isSaving =
      false;


    if (
      saveBrandButton
    ) {
      saveBrandButton.disabled =
        false;


      saveBrandButton.textContent =
        "브랜드 설정 저장";
    }
  }
}

/* =========================================================
  브랜드 관리 이벤트 연결
========================================================= */

function bindBrandManagementEvents() {
  const {
    employeeTabButton,
    brandTabButton,

    companyNameInput,
    programNameInput,
    programSubtitleInput,

    logoFileInput,
    backgroundFileInput,

    removeLogoButton,
    removeBackgroundButton,

    positionXInput,
    positionYInput,
    overlayInput,

    saveBrandButton
  } =
    getBrandManagementElements();


  employeeTabButton
    ?.addEventListener(
      "click",
      () => {
        switchSystemAdminView(
          "employees"
        );
      }
    );


  brandTabButton
    ?.addEventListener(
      "click",
      () => {
        switchSystemAdminView(
          "brand"
        );
      }
    );


  [
    companyNameInput,
    programNameInput,
    programSubtitleInput,
    positionXInput,
    positionYInput,
    overlayInput
  ]
    .filter(Boolean)
    .forEach(
      input => {
        input.addEventListener(
          "input",
          updateBrandManagementPreview
        );
      }
    );


  logoFileInput
    ?.addEventListener(
      "change",
      handleBrandLogoFileChange
    );


  backgroundFileInput
    ?.addEventListener(
      "change",
      handleBrandBackgroundFileChange
    );


  removeLogoButton
    ?.addEventListener(
      "click",
      removeBrandLogoPreview
    );


  removeBackgroundButton
    ?.addEventListener(
      "click",
      removeBrandBackgroundPreview
    );


  saveBrandButton
    ?.addEventListener(
      "click",
      handleBrandManagementSavePreview
    );


  updateBrandManagementPreview();
}

/* =========================================================
  직원 직접 추가 기능 최종본

  기능:
  - 직원 추가 버튼 클릭
  - 직원 추가 패널 열기·닫기
  - 사번·이름·권한 입력
  - D1 employees 저장
  - users 로그인 계정 자동 생성
  - 초기 비밀번호는 사번과 동일
========================================================= */


/* =========================================================
  직원 추가 요소 가져오기
========================================================= */

function getShiftLogEmployeeAddElements() {
  return {
    panel:
      document.getElementById(
        "employeeAddPanel"
      ),

    openButton:
      document.getElementById(
        "openEmployeeAddButton"
      ),

    closeButton:
      document.getElementById(
        "closeEmployeeAddButton"
      ),

    employeeNoInput:
      document.getElementById(
        "employeeAddEmployeeNo"
      ),

    nameInput:
      document.getElementById(
        "employeeAddName"
      ),

    roleSelect:
      document.getElementById(
        "employeeAddRole"
      ),

    saveButton:
      document.getElementById(
        "saveEmployeeAddButton"
      ),

    message:
      document.getElementById(
        "employeeAddMessage"
      )
  };
}


/* =========================================================
  직원 추가 메시지 표시
========================================================= */

function showShiftLogEmployeeAddMessage(
  message,
  type = "info"
) {
  const {
    message: messageElement
  } =
    getShiftLogEmployeeAddElements();


  if (
    !messageElement
  ) {
    return;
  }


  messageElement.textContent =
    String(
      message ||
      ""
    );


  messageElement.hidden =
    !message;


  messageElement.classList.remove(
    "is-error",
    "is-success"
  );


  if (
    type ===
    "error"
  ) {
    messageElement.classList.add(
      "is-error"
    );
  }


  if (
    type ===
    "success"
  ) {
    messageElement.classList.add(
      "is-success"
    );
  }
}


/* =========================================================
  직원 추가 입력값 초기화
========================================================= */

function resetShiftLogEmployeeAddForm() {
  const {
    employeeNoInput,
    nameInput,
    roleSelect
  } =
    getShiftLogEmployeeAddElements();


  if (
    employeeNoInput
  ) {
    employeeNoInput.value =
      "";
  }


  if (
    nameInput
  ) {
    nameInput.value =
      "";
  }


  if (
    roleSelect
  ) {
    roleSelect.value =
      "user";
  }


  showShiftLogEmployeeAddMessage(
    ""
  );
}


/* =========================================================
  직원 추가 패널 열기
========================================================= */

function openShiftLogEmployeeAddPanel() {
  if (
    !isCurrentUserSuperAdmin()
  ) {
    showToast(
      "최고관리자만 직원을 추가할 수 있습니다."
    );


    return;
  }


  const {
    panel,
    employeeNoInput
  } =
    getShiftLogEmployeeAddElements();


  if (
    !panel
  ) {
    console.error(
      "직원 추가 패널을 찾을 수 없습니다."
    );


    showToast(
      "직원 추가 화면을 찾을 수 없습니다."
    );


    return;
  }


  /*
    직원 관리 탭으로 전환한다.
  */
  if (
    typeof switchSystemAdminView ===
      "function"
  ) {
    switchSystemAdminView(
      "employees"
    );
  }


  resetShiftLogEmployeeAddForm();


  panel.hidden =
    false;


  panel.removeAttribute(
    "hidden"
  );


  window.requestAnimationFrame(
    () => {
      panel.scrollIntoView({
        behavior:
          "smooth",

        block:
          "nearest"
      });


      employeeNoInput?.focus();
    }
  );
}


/* =========================================================
  직원 추가 패널 닫기
========================================================= */

function closeShiftLogEmployeeAddPanel() {
  const {
    panel
  } =
    getShiftLogEmployeeAddElements();


  if (
    !panel
  ) {
    return;
  }


  panel.hidden =
    true;


  showShiftLogEmployeeAddMessage(
    ""
  );
}


/* =========================================================
  직원 한 명 등록

  API:
  POST /api/employees

  신규 등록 시:
  - employees 명단 생성
  - users 로그인 계정 생성
  - 초기 비밀번호는 사번과 동일
========================================================= */

async function saveShiftLogEmployeeAdd() {
  const {
    employeeNoInput,
    nameInput,
    roleSelect,
    saveButton
  } =
    getShiftLogEmployeeAddElements();


  if (
    !isCurrentUserSuperAdmin()
  ) {
    showShiftLogEmployeeAddMessage(
      "최고관리자만 직원을 등록할 수 있습니다.",
      "error"
    );


    return;
  }


  const employeeNo =
    String(
      employeeNoInput?.value ||
      ""
    )
      .replace(
        /[^0-9]/g,
        ""
      )
      .trim();


  const name =
    String(
      nameInput?.value ||
      ""
    ).trim();


  const selectedRole =
    String(
      roleSelect?.value ||
      "user"
    )
      .trim()
      .toLowerCase();


  /* =====================================================
    입력값 검사
  ====================================================== */

  if (
    !/^\d{6,10}$/.test(
      employeeNo
    )
  ) {
    showShiftLogEmployeeAddMessage(
      "사번은 숫자 6~10자리로 입력해 주세요.",
      "error"
    );


    employeeNoInput?.focus();


    return;
  }


  if (
    !name
  ) {
    showShiftLogEmployeeAddMessage(
      "직원 이름을 입력해 주세요.",
      "error"
    );


    nameInput?.focus();


    return;
  }


  if (
    name.length < 2 ||
    name.length > 30
  ) {
    showShiftLogEmployeeAddMessage(
      "직원 이름은 2~30자로 입력해 주세요.",
      "error"
    );


    nameInput?.focus();


    return;
  }


  const defaultRole =
    selectedRole ===
      "super_admin"
      ? "super_admin"
      : "user";


  showShiftLogEmployeeAddMessage(
    "직원 계정을 등록하고 있습니다."
  );


  if (
    saveButton
  ) {
    saveButton.disabled =
      true;


    saveButton.textContent =
      "등록 중...";
  }


  try {
    const response =
      await fetch(
        "/api/employees",
        {
          method:
            "POST",

          headers:
            getShiftLogAuthHeaders({
              "Content-Type":
                "application/json"
            }),

          cache:
            "no-store",

          body:
            JSON.stringify({
              employeeNo,

              name,

              defaultRole,

              /*
                보직은 계정 등록 후
                직원 수정창에서 지정할 수 있다.
              */
              position:
                "",

              isAllowed:
                true
            })
        }
      );


    const responseText =
      await response.text();


    let result = {};


    if (
      responseText.trim()
    ) {
      try {
        result =
          JSON.parse(
            responseText
          );

      } catch {
        throw new Error(
          "직원 등록 서버 응답 형식이 올바르지 않습니다."
        );
      }
    }


    if (
      !response.ok ||
      result.ok === false ||
      result.success === false
    ) {
      const detailErrors =
        Array.isArray(
          result.errors
        )
          ? result.errors.join(
              "\n"
            )
          : "";


      throw new Error(
        detailErrors ||
        result.message ||
        result.error ||
        `직원 등록 실패 (HTTP ${response.status})`
      );
    }


    /*
      가입 완료 직원 목록을 다시 불러온다.
    */
    await loadEmployeeManagement();


    closeShiftLogEmployeeAddPanel();


    showToast(
      `${name} 직원이 등록되었습니다. 초기 비밀번호는 사번과 동일합니다.`
    );


    console.log(
      "직원 직접 등록 완료:",
      {
        employeeNo,
        name,
        defaultRole,
        result
      }
    );

  } catch (
    error
  ) {
    console.error(
      "직원 직접 등록 오류:",
      error
    );


    showShiftLogEmployeeAddMessage(
      error.message ||
      "직원을 등록하지 못했습니다.",
      "error"
    );


    showToast(
      error.message ||
      "직원 등록에 실패했습니다."
    );

  } finally {
    if (
      saveButton
    ) {
      saveButton.disabled =
        false;


      saveButton.textContent =
        "등록";
    }
  }
}


/* =========================================================
  직원 추가 이벤트 연결
========================================================= */

function initializeShiftLogEmployeeAdd() {
  const {
    openButton,
    closeButton,
    employeeNoInput,
    nameInput,
    roleSelect,
    saveButton
  } =
    getShiftLogEmployeeAddElements();


  if (
    !openButton
  ) {
    return;
  }


  /*
    이벤트 중복 연결 방지
  */
  if (
    openButton.dataset
      .employeeAddBound ===
      "true"
  ) {
    return;
  }


  openButton.addEventListener(
    "click",
    openShiftLogEmployeeAddPanel
  );


  closeButton?.addEventListener(
    "click",
    closeShiftLogEmployeeAddPanel
  );


  saveButton?.addEventListener(
    "click",
    saveShiftLogEmployeeAdd
  );


  /*
    사번에는 숫자만 입력한다.
  */
  employeeNoInput?.addEventListener(
    "input",
    () => {
      employeeNoInput.value =
        employeeNoInput.value.replace(
          /[^0-9]/g,
          ""
        );
    }
  );


  /*
    입력 중 Enter를 누르면 등록한다.
  */
  [
    employeeNoInput,
    nameInput,
    roleSelect
  ]
    .filter(
      Boolean
    )
    .forEach(
      input => {
        input.addEventListener(
          "keydown",
          event => {
            if (
              event.key !==
              "Enter"
            ) {
              return;
            }


            event.preventDefault();


            saveShiftLogEmployeeAdd();
          }
        );
      }
    );


  openButton.dataset
    .employeeAddBound =
    "true";
}


/* =========================================================
  직원 추가 기능 초기 실행
========================================================= */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeShiftLogEmployeeAdd
  );

} else {
  initializeShiftLogEmployeeAdd();
}

/* =========================================================
  로그인 및 시스템 관리자 기능 초기화
========================================================= */

async function initializeShiftLogLogin() {
  const {
    loginForm,
    logoutButton,
    adminButton,
    employeeManagementModal,
    closeEmployeeManagementButton,
    closeEmployeeManagementFooterButton
  } =
    getLoginElements();


  const refreshEmployeeManagementButton =
    document.getElementById(
      "refreshEmployeeManagementButton"
    );


  const employeeManagementSearch =
    document.getElementById(
      "employeeManagementSearch"
    );


  /* =====================================================
    로그인
  ====================================================== */

  loginForm
    ?.addEventListener(
      "submit",
      handleShiftLogLogin
    );


  /* =====================================================
    로그아웃
  ====================================================== */

  logoutButton
    ?.addEventListener(
      "click",
      handleShiftLogLogout
    );


  /* =====================================================
    시스템 관리자 열기
  ====================================================== */

  adminButton
    ?.addEventListener(
      "click",
      openEmployeeManagementModal
    );


  /* =====================================================
    시스템 관리자 닫기
  ====================================================== */

  closeEmployeeManagementButton
    ?.addEventListener(
      "click",
      closeEmployeeManagementModal
    );


  closeEmployeeManagementFooterButton
    ?.addEventListener(
      "click",
      closeEmployeeManagementModal
    );


  /* =====================================================
    직원 관리
  ====================================================== */

  refreshEmployeeManagementButton
    ?.addEventListener(
      "click",
      loadEmployeeManagement
    );


  employeeManagementSearch
    ?.addEventListener(
      "input",
      filterEmployeeManagementUsers
    );


  /* =====================================================
    브랜드 관리 이벤트
  ====================================================== */

  bindBrandManagementEvents();


  /*
    서버의 브랜드 설정을 먼저 불러온 후
    로그인 화면과 헤더를 표시한다.
  */
  await initializeBrandSettings();


  /* =====================================================
    모달 바깥 클릭 닫기
  ====================================================== */

  employeeManagementModal
    ?.addEventListener(
      "click",
      event => {
        if (
          event.target ===
          employeeManagementModal
        ) {
          closeEmployeeManagementModal();
        }
      }
    );


  /* =====================================================
    저장된 로그인 사용자 복원
  ====================================================== */

  const currentUser =
    loadCurrentUser();


  if (
    currentUser
  ) {
    openShiftLogApp(
      currentUser
    );


    return;
  }


  openLoginScreen();
}

document.addEventListener(
  "DOMContentLoaded",
  initializeShiftLogLogin
);

/* =========================================================
  GS Shift Log
  - 현황 / 조회 탭
  - 날짜 이동
  - 업무일지 작성 모달
  - 작업 항목 추가 / 삭제
  - 첨부파일 표시
  - 임시저장 / 저장 / 결재요청
  - 상세보기
  - TAG → Facility Navigator 이동
========================================================= */

const FACILITY_NAVIGATOR_URL =
  "https://gs-facility-navigator-2mg.pages.dev/";

const STORAGE_KEYS = {
  logs:
    "gsShiftLog.logs",

  draft:
    "gsShiftLog.draft",

  operationStatus:
    "gsShiftLog.operationStatus",

  memberWorkStatuses:
    "gsShiftLog.memberWorkStatuses"
};


/* =========================================================
  현재 근무일자·근무구분 계산

  D/S : 07:00 ~ 19:00
  N/S : 19:00 ~ 다음 날 07:00

  00:00 ~ 06:59는 전날 N/S로 처리한다.
========================================================= */

function getCurrentShiftContext(now = new Date()) {
  const currentDate =
    new Date(now);

  const hour =
    currentDate.getHours();

  if (hour >= 7 && hour < 19) {
    return {
      date:
        new Date(
          currentDate.getFullYear(),
          currentDate.getMonth(),
          currentDate.getDate()
        ),

      shift:
        "DS"
    };
  }

  if (hour < 7) {
    currentDate.setDate(
      currentDate.getDate() - 1
    );
  }

  return {
    date:
      new Date(
        currentDate.getFullYear(),
        currentDate.getMonth(),
        currentDate.getDate()
      ),

    shift:
      "NS"
  };
}


function getShiftDisplayName(shift) {
  return (
    String(shift || "")
      .trim()
      .toUpperCase() === "DS"
      ? "D/S"
      : "N/S"
  );
}


async function toggleSelectedShift() {
  appState.selectedShift =
    appState.selectedShift === "DS"
      ? "NS"
      : "DS";

  renderSelectedDate();

  await loadLegacyLogsForSelectedDate();

  renderLogTable();
  updateShiftMemberCardStates();
}

const initialShiftContext =
  getCurrentShiftContext();

const appState = {
  selectedDate:
    initialShiftContext.date,

  selectedShift:
    initialShiftContext.shift,

  currentDetailLogId:
    null,

  logs: [],

  editorEntries: [],

  editingEntryIndex:
    -1,

  /*
    날짜·근무·보직별 근무 상태

    예:
    2026-07-21||DS||TGO : 출근
    2026-07-21||DS||BCO1 : 휴가
  */
  memberWorkStatuses: {}
};

/* =========================================================
  근무자 출근·부재 상태 관리

  상태 종류:
  - 출근
  - 교육
  - 휴가
  - 출장
  - 결원
========================================================= */

function getMemberWorkStatusKey(
  date,
  shift,
  role
) {
  const normalizedDate =
    String(
      date || ""
    ).trim();

  const normalizedShift =
    String(
      shift || ""
    )
      .trim()
      .toUpperCase();

  const normalizedRole =
    normalizeMemberLogRole(
      role
    );

  return [
    normalizedDate,
    normalizedShift,
    normalizedRole
  ].join("||");
}


function loadMemberWorkStatuses() {
  const savedStatuses =
    localStorage.getItem(
      STORAGE_KEYS.memberWorkStatuses
    );

  if (!savedStatuses) {
    appState.memberWorkStatuses = {};
    return;
  }

  try {
    const parsedStatuses =
      JSON.parse(
        savedStatuses
      );

    appState.memberWorkStatuses =
      parsedStatuses &&
      typeof parsedStatuses ===
        "object" &&
      !Array.isArray(
        parsedStatuses
      )
        ? parsedStatuses
        : {};
  } catch (error) {
    console.error(
      "근무자 상태 불러오기 실패:",
      error
    );

    appState.memberWorkStatuses = {};

    localStorage.removeItem(
      STORAGE_KEYS.memberWorkStatuses
    );
  }
}


function persistMemberWorkStatuses() {
  localStorage.setItem(
    STORAGE_KEYS.memberWorkStatuses,
    JSON.stringify(
      appState.memberWorkStatuses
    )
  );
}


function getMemberWorkStatus(
  date,
  shift,
  role
) {
  const statusKey =
    getMemberWorkStatusKey(
      date,
      shift,
      role
    );

  const savedStatus =
    String(
      appState
        .memberWorkStatuses[
          statusKey
        ] ||
      ""
    ).trim();

  const validStatuses = [
    "출근",
    "교육",
    "휴가",
    "출장",
    "결원"
  ];

  return validStatuses.includes(
    savedStatus
  )
    ? savedStatus
    : "출근";
}


function setMemberWorkStatus(
  date,
  shift,
  role,
  status
) {
  const validStatuses = [
    "출근",
    "교육",
    "휴가",
    "출장",
    "결원"
  ];

  const normalizedStatus =
    String(
      status || ""
    ).trim();

  if (
    !validStatuses.includes(
      normalizedStatus
    )
  ) {
    return false;
  }

  const statusKey =
    getMemberWorkStatusKey(
      date,
      shift,
      role
    );

  /*
    기본값인 출근은 저장소에서 제거하여
    불필요한 데이터가 쌓이지 않게 한다.
  */
  if (
    normalizedStatus ===
    "출근"
  ) {
    delete appState
      .memberWorkStatuses[
        statusKey
      ];
  } else {
    appState
      .memberWorkStatuses[
        statusKey
      ] =
      normalizedStatus;
  }

  persistMemberWorkStatuses();

  return true;
}

/* =========================================================
  조회 기본 기간 설정

  종료일:
  오늘

  시작일:
  오늘 기준 7일 전

  예:
  오늘이 2026-07-23이면
  시작일 2026-07-16
  종료일 2026-07-23
========================================================= */

function setDefaultSearchDateRange() {
  const searchStartDate =
    document.getElementById(
      "searchStartDate"
    );

  const searchEndDate =
    document.getElementById(
      "searchEndDate"
    );


  if (
    !searchStartDate ||
    !searchEndDate
  ) {
    return;
  }


  const today =
    new Date();


  const sevenDaysAgo =
    new Date(today);


  sevenDaysAgo.setDate(
    sevenDaysAgo.getDate() - 7
  );


  searchStartDate.value =
    formatInputDate(
      sevenDaysAgo
    );


  searchEndDate.value =
    formatInputDate(
      today
    );
}

/* =========================================================
  초기 실행

  실행 순서:
  1. HTML 요소 및 이벤트 연결
  2. D1 공용 업무일지 로딩 완료
  3. legacy 업무일지 로딩 및 D1 자동 이전
  4. 최종 화면 렌더링

  D1 로딩과 legacy 로딩을 동시에 실행하면
  자동 이전된 일지가 legacy 자료로 다시 덮일 수 있으므로
  반드시 순서대로 기다린다.
========================================================= */

document.addEventListener(
  "DOMContentLoaded",
  async () => {
    /*
      모든 HTML 요소를 먼저 연결한다.
    */
    cacheElements();

    cacheMemberLogImportElements();

    initializeLogEntryTargetRoleVisibility();


    /*
      조회 화면 기본 기간:
      오늘부터 이전 7일까지
    */
    setDefaultSearchDateRange();


    /*
      근무자 카드 이벤트
    */
    bindShiftMemberCards();


    /*
      공통 이벤트
    */
    bindEvents();

    bindMemberLogImportEvents();

    bindLogEntryEditModeEvents();


    /*
      보직별 운전현황 이벤트
    */
    bindOperationStatusEvents();


    /*
      저장된 근무 상태
    */
    loadMemberWorkStatuses();


    /*
      최초 운전현황 표시
    */
    refreshOperationStatusForCurrentRole();


    /*
      D1 공용 업무일지를 먼저 끝까지 불러온다.

      이 await가 빠지면 아래의 legacy 로딩과 동시에 실행되어
      D1 자동 이전 결과가 다시 덮일 수 있다.
    */
    await loadLogs();


    /*
      legacy 업무일지를 불러온다.

      2026-07-22 이후 legacy 자료는
      migrateEditableLegacyLogsForSelectedDate()를 통해
      공용 D1 업무일지로 자동 이전된다.
    */
    await loadLegacyLogsForSelectedDate();


    /*
      모든 로딩과 이전이 끝난 뒤
      최종 화면을 한 번만 렌더링한다.
    */
    renderSelectedDate();

    renderLogTable();

    updateShiftMemberCardStates();


    setEditorDateFromSelectedDate();


    resetLogEntryInput();

    updateTagFieldVisibility();

    renderLogEntryTable();


    /*
      최초에는 인수인계사항 편집 모드를 끈다.
    */
    setLogEntryEditMode(
      false
    );


    updateMemberLogImportSection();
  }
);

