/* =========================================================
  삭제 클릭 시 legacy → D1 전환
========================================================= */

const deleteLogByIdBeforeLegacyManagement =
  deleteLogById;


deleteLogById =
  async function deleteLogById(
    logId
  ) {
    const targetLog =
      appState.logs.find(
        log => {
          return (
            String(
              log?.id ||
              ""
            ) ===

            String(
              logId ||
              ""
            )
          );
        }
      );


    /*
      이미 D1인 업무일지는 기존 삭제 기능 사용
    */
    if (
      !targetLog ||

      !isReadOnlyLegacyShiftLog(
        targetLog
      )
    ) {
      return deleteLogByIdBeforeLegacyManagement(
        logId
      );
    }


    if (
      !canCurrentUserEditShiftLog(
        targetLog
      )
    ) {
      showShiftLogEditDeniedMessage(
        targetLog
      );


      return null;
    }


    try {
      const sharedLog =
        await convertLegacyLogForSuperAdminManagement(
          targetLog
        );


      return deleteLogByIdBeforeLegacyManagement(
        sharedLog.id
      );

    } catch (
      error
    ) {
      console.error(
        "업무일지 삭제 준비 실패:",
        error
      );


      showToast(
        error.message ||
        "업무일지를 삭제 가능한 상태로 전환하지 못했습니다."
      );


      return null;
    }
  };

  /* =========================================================
  업무일지 작성창 저장 여부 추적 최종 연결

  기능:
  - 작성창이 완전히 열린 뒤 현재 상태를 저장 기준으로 기록
  - 임시저장·저장·결재요청 성공 후 저장 기준 갱신
  - 저장 후 자동으로 닫히는 경우에도 경고창이 뜨지 않음
========================================================= */


/* =========================================================
  기존 최종 openLogEditor 보존
========================================================= */

const openLogEditorBeforeUnsavedTracking =
  openLogEditor;


/* =========================================================
  저장 여부 추적이 적용된 작성창 열기
========================================================= */

openLogEditor =
  function openLogEditor(
    log = null,
    preset = null
  ) {
    const result =
      openLogEditorBeforeUnsavedTracking(
        log,
        preset
      );


    /*
      openLogEditor 내부에서
      reset·fill·운전현황 렌더링이 모두 끝난 다음
      기준 상태를 기록해야 한다.
    */
    window.requestAnimationFrame(
      () => {
        window.requestAnimationFrame(
          () => {
            markLogEditorAsSaved();
          }
        );
      }
    );


    return result;
  };


/* =========================================================
  기존 최종 saveCurrentLog 보존
========================================================= */

const saveCurrentLogBeforeUnsavedTracking =
  saveCurrentLog;


/* =========================================================
  저장 여부 추적이 적용된 업무일지 저장
========================================================= */

saveCurrentLog =
  async function saveCurrentLog(
    requestedStatus,
    options = {}
  ) {
    /*
      기존 저장 함수가 저장 성공 여부를
      업무일지 객체 또는 null로 반환한다.
    */
    const savedLog =
      await saveCurrentLogBeforeUnsavedTracking(
        requestedStatus,
        options
      );


    /*
      유효성 검사 실패·서버 저장 실패
      → null이 반환되므로 저장 상태를 갱신하지 않는다.
    */
    if (
      !savedLog
    ) {
      return savedLog;
    }


    /*
      저장 성공 직후 현재 화면 상태를
      새로운 저장 기준으로 갱신한다.

      closeAfterSave가 false인 임시저장에서도
      저장 이후 추가 변경이 없으면 바로 닫을 수 있다.
    */
    markLogEditorAsSaved();


    return savedLog;
  };

  /* =========================================================
  업무일지 상세보기 모달 크기 최종 강제 적용

  적용 방식:
  - CSS 중복 선언과 관계없이 인라인 !important 적용
  - 상세창이 열릴 때마다 다시 크기 적용
  - 브라우저 크기가 바뀌어도 자동 재계산
  - 업무일지 작성·수정창에는 영향 없음

  PC:
  - 최대 폭 1320px
  - 좌우 여백 18px
  - 화면 높이 약 94%

  모바일:
  - 전체 화면 사용
========================================================= */

function applyLogDetailModalSize() {
  const modal =
    document.getElementById(
      "logDetailModal"
    );


  if (
    !modal
  ) {
    return;
  }


  const panel =
    modal.querySelector(
      ".log-detail-modal"
    ) ||
    modal.querySelector(
      ".modal-panel"
    );


  const header =
    modal.querySelector(
      ".log-detail-modal__header"
    ) ||
    modal.querySelector(
      ".modal-header"
    );


  const body =
    modal.querySelector(
      ".log-detail-modal__body"
    ) ||
    modal.querySelector(
      ".modal-body"
    );


  const footer =
    modal.querySelector(
      ".log-detail-modal__footer"
    ) ||
    modal.querySelector(
      ".modal-footer"
    );


  if (
    !panel
  ) {
    return;
  }


  const isMobile =
    window.innerWidth <=
    600;


  const isTablet =
    window.innerWidth <=
    900;


  /*
    상세보기 배경 영역
  */
  modal.style.setProperty(
    "box-sizing",
    "border-box",
    "important"
  );


  modal.style.setProperty(
    "align-items",
    "center",
    "important"
  );


  modal.style.setProperty(
    "justify-content",
    "center",
    "important"
  );


  modal.style.setProperty(
    "padding",
    isMobile
      ? "0"
      : (
          isTablet
            ? "10px"
            : "18px"
        ),
    "important"
  );


  /*
    상세보기 모달 본체
  */
  panel.style.setProperty(
    "display",
    "flex",
    "important"
  );


  panel.style.setProperty(
    "flex-direction",
    "column",
    "important"
  );


  panel.style.setProperty(
    "box-sizing",
    "border-box",
    "important"
  );


  panel.style.setProperty(
    "margin",
    "0 auto",
    "important"
  );


  panel.style.setProperty(
    "overflow",
    "hidden",
    "important"
  );


  if (
    isMobile
  ) {
    panel.style.setProperty(
      "width",
      "100vw",
      "important"
    );


    panel.style.setProperty(
      "min-width",
      "0",
      "important"
    );


    panel.style.setProperty(
      "max-width",
      "100vw",
      "important"
    );


    panel.style.setProperty(
      "height",
      "100dvh",
      "important"
    );


    panel.style.setProperty(
      "min-height",
      "0",
      "important"
    );


    panel.style.setProperty(
      "max-height",
      "100dvh",
      "important"
    );


    panel.style.setProperty(
      "border-radius",
      "0",
      "important"
    );
  } else {
    panel.style.setProperty(
      "width",
      isTablet
        ? "calc(100vw - 20px)"
        : "min(1320px, calc(100vw - 36px))",
      "important"
    );


    panel.style.setProperty(
      "min-width",
      "0",
      "important"
    );


    panel.style.setProperty(
      "max-width",
      isTablet
        ? "none"
        : "1320px",
      "important"
    );


    panel.style.setProperty(
      "height",
      isTablet
        ? "calc(100vh - 20px)"
        : "min(94vh, 1040px)",
      "important"
    );


    panel.style.setProperty(
      "min-height",
      isTablet
        ? "0"
        : "650px",
      "important"
    );


    panel.style.setProperty(
      "max-height",
      isTablet
        ? "calc(100vh - 20px)"
        : "calc(100vh - 36px)",
      "important"
    );


    panel.style.setProperty(
      "border-radius",
      "15px",
      "important"
    );
  }


  /*
    상단
  */
  if (
    header
  ) {
    header.style.setProperty(
      "flex",
      "0 0 auto",
      "important"
    );


    header.style.setProperty(
      "width",
      "100%",
      "important"
    );


    header.style.setProperty(
      "box-sizing",
      "border-box",
      "important"
    );
  }


  /*
    본문 스크롤 영역
  */
  if (
    body
  ) {
    body.style.setProperty(
      "display",
      "block",
      "important"
    );


    body.style.setProperty(
      "flex",
      "1 1 auto",
      "important"
    );


    body.style.setProperty(
      "width",
      "100%",
      "important"
    );


    body.style.setProperty(
      "min-width",
      "0",
      "important"
    );


    body.style.setProperty(
      "max-width",
      "none",
      "important"
    );


    body.style.setProperty(
      "min-height",
      "0",
      "important"
    );


    body.style.setProperty(
      "box-sizing",
      "border-box",
      "important"
    );


    body.style.setProperty(
      "overflow-x",
      "hidden",
      "important"
    );


    body.style.setProperty(
      "overflow-y",
      "auto",
      "important"
    );


    body.style.setProperty(
      "padding",
      isMobile
        ? "9px"
        : "14px 18px 18px",
      "important"
    );
  }


  /*
    하단 버튼 영역
  */
  if (
    footer
  ) {
    footer.style.setProperty(
      "flex",
      "0 0 auto",
      "important"
    );


    footer.style.setProperty(
      "width",
      "100%",
      "important"
    );


    footer.style.setProperty(
      "box-sizing",
      "border-box",
      "important"
    );
  }


  /*
    상세 내용 내부의 max-width 제한 제거
  */
  const detailContent =
    document.getElementById(
      "logDetailContent"
    );


  if (
    detailContent
  ) {
    detailContent.style.setProperty(
      "width",
      "100%",
      "important"
    );


    detailContent.style.setProperty(
      "min-width",
      "0",
      "important"
    );


    detailContent.style.setProperty(
      "max-width",
      "none",
      "important"
    );


    detailContent
      .querySelectorAll(
        [
          ".shift-log-detail-document",
          ".detail-document",
          ".log-detail-layout",
          ".log-report",
          ".shift-log-detail-summary",
          ".shift-log-detail-section",
          ".log-detail-card",
          ".log-report-section"
        ].join(",")
      )
      .forEach(
        (element) => {
          element.style.setProperty(
            "width",
            "100%",
            "important"
          );


          element.style.setProperty(
            "min-width",
            "0",
            "important"
          );


          element.style.setProperty(
            "max-width",
            "none",
            "important"
          );


          element.style.setProperty(
            "box-sizing",
            "border-box",
            "important"
          );
        }
      );
  }
}


/* =========================================================
  상세창 열림 감시

  openModal()에서 is-open 클래스가 붙는 순간
  크기를 다시 강제로 적용한다.
========================================================= */

function initializeLogDetailModalSizeFix() {
  const modal =
    document.getElementById(
      "logDetailModal"
    );


  if (
    !modal
  ) {
    return;
  }


  /*
    페이지 로드 직후 한 번 적용
  */
  applyLogDetailModalSize();


  /*
    상세창의 class·aria-hidden 변경 감시
  */
  const observer =
    new MutationObserver(
      () => {
        if (
          modal.classList.contains(
            "is-open"
          ) ||
          modal.getAttribute(
            "aria-hidden"
          ) ===
            "false"
        ) {
          window.requestAnimationFrame(
            () => {
              applyLogDetailModalSize();
            }
          );
        }
      }
    );


  observer.observe(
    modal,
    {
      attributes:
        true,

      attributeFilter: [
        "class",
        "aria-hidden"
      ]
    }
  );


  /*
    화면 크기 변경 시 재적용
  */
  window.addEventListener(
    "resize",
    applyLogDetailModalSize
  );
}


if (
  document.readyState ===
  "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeLogDetailModalSizeFix
  );
} else {
  initializeLogDetailModalSizeFix();
}

/* =========================================================
  공지사항 댓글 API 공통 기능

  전체공지:
  - noticeType = "global"

  보직공지:
  - noticeType = "role"
========================================================= */

const NOTICE_COMMENT_API_URL =
  "/api/notice-comments";


const NOTICE_COMMENT_TYPES =
  new Set([
    "global",
    "role"
  ]);


const NOTICE_COMMENT_MAX_LENGTH =
  1000;


/* =========================================================
  댓글 API 오류
========================================================= */

class NoticeCommentApiError extends Error {
  constructor(
    message,
    options = {}
  ) {
    super(
      message
    );


    this.name =
      "NoticeCommentApiError";


    this.status =
      Number(
        options.status ||
        0
      );


    this.isConflict =
      this.status ===
        409 ||
      options.isConflict ===
        true;


    this.currentComment =
      options.currentComment ||
      null;
  }
}


/* =========================================================
  댓글 종류 정규화
========================================================= */

function normalizeNoticeCommentType(
  value
) {
  const noticeType =
    String(
      value ||
      ""
    )
      .trim()
      .toLowerCase();


  return NOTICE_COMMENT_TYPES.has(
    noticeType
  )
    ? noticeType
    : "";
}


/* =========================================================
  댓글 대상 ID 정규화
========================================================= */

function normalizeNoticeCommentTargetId(
  value
) {
  const noticeId =
    String(
      value ||
      ""
    ).trim();


  if (
    !noticeId ||
    noticeId.length >
      128 ||
    /[\u0000-\u001F\u007F]/.test(
      noticeId
    )
  ) {
    return "";
  }


  return noticeId;
}


/* =========================================================
  댓글 내용 정규화
========================================================= */

function normalizeNoticeCommentContent(
  value
) {
  return String(
    value ||
    ""
  )
    .replace(
      /\r\n/g,
      "\n"
    )
    .replace(
      /\r/g,
      "\n"
    )
    .trim();
}


/* =========================================================
  댓글 데이터 정규화
========================================================= */

function normalizeNoticeComment(
  comment
) {
  const sourceComment =
    comment &&
    typeof comment ===
      "object"
      ? comment
      : {};


  const revision =
    Math.max(
      1,
      Number(
        sourceComment.revision ||
        1
      ) ||
      1
    );


  const isMine =
    sourceComment.isMine ===
      true ||
    sourceComment.is_mine ===
      true ||
    Number(
      sourceComment.isMine ??
      sourceComment.is_mine ??
      0
    ) ===
      1;


  const canEdit =
    sourceComment.canEdit ===
      true ||
    sourceComment.can_edit ===
      true ||
    Number(
      sourceComment.canEdit ??
      sourceComment.can_edit ??
      0
    ) ===
      1;


  const canDelete =
    sourceComment.canDelete ===
      true ||
    sourceComment.can_delete ===
      true ||
    Number(
      sourceComment.canDelete ??
      sourceComment.can_delete ??
      0
    ) ===
      1;


  return {
    id:
      String(
        sourceComment.id ||
        sourceComment.commentId ||
        sourceComment.comment_id ||
        ""
      ).trim(),

    noticeType:
      normalizeNoticeCommentType(
        sourceComment.noticeType ||
        sourceComment.notice_type
      ),

    noticeId:
      normalizeNoticeCommentTargetId(
        sourceComment.noticeId ||
        sourceComment.notice_id
      ),

    content:
      normalizeNoticeCommentContent(
        sourceComment.content
      ),

    createdBy:
      String(
        sourceComment.createdBy ||
        sourceComment.created_by ||
        ""
      ).trim(),

    createdByName:
      String(
        sourceComment.createdByName ||
        sourceComment.created_by_name ||
        ""
      ).trim(),

    createdByPosition:
      String(
        sourceComment.createdByPosition ||
        sourceComment.created_by_position ||
        ""
      ).trim(),

    createdAt:
      String(
        sourceComment.createdAt ||
        sourceComment.created_at ||
        ""
      ).trim(),

    updatedBy:
      String(
        sourceComment.updatedBy ||
        sourceComment.updated_by ||
        ""
      ).trim(),

    updatedByName:
      String(
        sourceComment.updatedByName ||
        sourceComment.updated_by_name ||
        ""
      ).trim(),

    updatedAt:
      String(
        sourceComment.updatedAt ||
        sourceComment.updated_at ||
        sourceComment.createdAt ||
        sourceComment.created_at ||
        ""
      ).trim(),

    revision,

    isEdited:
      sourceComment.isEdited ===
        true ||
      sourceComment.is_edited ===
        true ||
      revision >
        1,

    isMine,

    canEdit,

    canDelete
  };
}


/* =========================================================
  댓글 대상 검증
========================================================= */

function validateNoticeCommentTarget(
  noticeTypeValue,
  noticeIdValue
) {
  const noticeType =
    normalizeNoticeCommentType(
      noticeTypeValue
    );


  const noticeId =
    normalizeNoticeCommentTargetId(
      noticeIdValue
    );


  if (
    !noticeType
  ) {
    throw new NoticeCommentApiError(
      "공지 종류가 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  if (
    !noticeId
  ) {
    throw new NoticeCommentApiError(
      "공지사항 ID가 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  return {
    noticeType,
    noticeId
  };
}


/* =========================================================
  댓글 내용 검증
========================================================= */

function validateNoticeCommentContent(
  value
) {
  const content =
    normalizeNoticeCommentContent(
      value
    );


  if (
    !content
  ) {
    throw new NoticeCommentApiError(
      "댓글 내용을 입력해 주세요.",
      {
        status:
          400
      }
    );
  }


  if (
    content.length >
      NOTICE_COMMENT_MAX_LENGTH
  ) {
    throw new NoticeCommentApiError(
      `댓글은 최대 ${NOTICE_COMMENT_MAX_LENGTH}자까지 입력할 수 있습니다.`,
      {
        status:
          400
      }
    );
  }


  return content;
}


/* =========================================================
  댓글 등록 중복 방지 요청 ID
========================================================= */

function createNoticeCommentClientRequestId() {
  const randomId =
    typeof globalThis.crypto
      ?.randomUUID ===
      "function"
      ? globalThis.crypto
          .randomUUID()
      : [
          Date.now(),
          Math.random()
            .toString(
              36
            )
            .slice(
              2
            )
        ].join("-");


  return [
    "notice-comment",
    Date.now(),
    randomId
  ]
    .join(":")
    .slice(
      0,
      160
    );
}


/* =========================================================
  댓글 API 공통 요청
========================================================= */

async function requestNoticeCommentApi(
  options = {}
) {
  const method =
    String(
      options.method ||
      "GET"
    ).toUpperCase();


  const requestUrl =
    new URL(
      NOTICE_COMMENT_API_URL,
      window.location.origin
    );


  const searchParams =
    options.searchParams &&
    typeof options.searchParams ===
      "object"
      ? options.searchParams
      : {};


  Object.entries(
    searchParams
  ).forEach(
    ([
      key,
      value
    ]) => {
      if (
        value ===
          undefined ||
        value ===
          null ||
        value ===
          ""
      ) {
        return;
      }


      requestUrl.searchParams.set(
        key,
        String(
          value
        )
      );
    }
  );


  if (
    method ===
      "GET"
  ) {
    requestUrl.searchParams.set(
      "_",
      String(
        Date.now()
      )
    );
  }


  const hasBody =
    options.body !==
      undefined;


  const requestOptions = {
    method,

    headers:
      getShiftLogAuthHeaders(
        hasBody
          ? {
              "Content-Type":
                "application/json"
            }
          : {}
      ),

    cache:
      "no-store"
  };


  if (
    hasBody
  ) {
    requestOptions.body =
      JSON.stringify(
        options.body
      );
  }


  let response;


  try {
    response =
      await fetch(
        requestUrl.toString(),
        requestOptions
      );

  } catch (
    error
  ) {
    console.error(
      "댓글 서버 연결 실패:",
      error
    );


    throw new NoticeCommentApiError(
      "댓글 서버에 연결할 수 없습니다."
    );
  }


  const responseText =
    await response.text();


  let result = {};


  if (
    responseText.trim()
  ) {
    try {
      result =
        JSON.parse(
          responseText
        );

    } catch {
      if (
        response.status ===
          401
      ) {
        clearCurrentUser();


        openLoginScreen();
      }


      throw new NoticeCommentApiError(
        "댓글 서버 응답 형식이 올바르지 않습니다.",
        {
          status:
            response.status
        }
      );
    }
  }


  if (
    response.status ===
      401
  ) {
    clearCurrentUser();


    openLoginScreen();
  }


  if (
    !response.ok ||
    result.ok ===
      false ||
    result.success ===
      false
  ) {
    const currentComment =
      result.currentComment &&
      typeof result.currentComment ===
        "object"
        ? normalizeNoticeComment(
            result.currentComment
          )
        : null;


    throw new NoticeCommentApiError(
      result.message ||
      result.error ||
      `댓글 요청 실패 (HTTP ${response.status})`,
      {
        status:
          response.status,

        isConflict:
          result.conflict ===
          true,

        currentComment
      }
    );
  }


  return result;
}


/* =========================================================
  댓글 개수 일괄 조회

  noticeType 생략:
  - 전체공지 + 보직공지 모두 조회
========================================================= */

async function loadNoticeCommentCounts(
  noticeTypeValue =
    ""
) {
  const rawNoticeType =
    String(
      noticeTypeValue ||
      ""
    ).trim();


  const noticeType =
    rawNoticeType
      ? normalizeNoticeCommentType(
          rawNoticeType
        )
      : "";


  if (
    rawNoticeType &&
    !noticeType
  ) {
    throw new NoticeCommentApiError(
      "공지 종류가 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  const result =
    await requestNoticeCommentApi({
      method:
        "GET",

      searchParams: {
        mode:
          "counts",

        noticeType
      }
    });


  const counts =
    Array.isArray(
      result.counts
    )
      ? result.counts
      : [];


  return counts
    .map(
      item => {
        return {
          noticeType:
            normalizeNoticeCommentType(
              item?.noticeType ||
              item?.notice_type
            ),

          noticeId:
            normalizeNoticeCommentTargetId(
              item?.noticeId ||
              item?.notice_id
            ),

          count:
            Math.max(
              0,
              Number(
                item?.count ??
                item?.commentCount ??
                item?.comment_count ??
                0
              ) ||
              0
            )
        };
      }
    )
    .filter(
      item => {
        return Boolean(
          item.noticeType &&
          item.noticeId
        );
      }
    );
}


/* =========================================================
  특정 공지 댓글 목록 조회
========================================================= */

async function loadNoticeComments(
  noticeTypeValue,
  noticeIdValue
) {
  const {
    noticeType,
    noticeId
  } =
    validateNoticeCommentTarget(
      noticeTypeValue,
      noticeIdValue
    );


  const result =
    await requestNoticeCommentApi({
      method:
        "GET",

      searchParams: {
        noticeType,
        noticeId
      }
    });


  const comments =
    (
      Array.isArray(
        result.comments
      )
        ? result.comments
        : []
    )
      .map(
        normalizeNoticeComment
      )
      .filter(
        comment => {
          return Boolean(
            comment.id &&
            comment.noticeType ===
              noticeType &&
            comment.noticeId ===
              noticeId
          );
        }
      );


  return {
    noticeType,
    noticeId,
    comments,

    totalCount:
      Math.max(
        0,
        Number(
          result.totalCount ??
          comments.length
        ) ||
        0
      )
  };
}


/* =========================================================
  새 댓글 등록
========================================================= */

async function createNoticeComment(
  options = {}
) {
  const {
    noticeType,
    noticeId
  } =
    validateNoticeCommentTarget(
      options.noticeType,
      options.noticeId
    );


  const content =
    validateNoticeCommentContent(
      options.content
    );


  const clientRequestId =
    String(
      options.clientRequestId ||
      createNoticeCommentClientRequestId()
    )
      .trim()
      .slice(
        0,
        160
      );


  const result =
    await requestNoticeCommentApi({
      method:
        "POST",

      body: {
        noticeType,
        noticeId,
        content,
        clientRequestId
      }
    });


  const comment =
    normalizeNoticeComment(
      result.comment
    );


  if (
    !comment.id
  ) {
    throw new NoticeCommentApiError(
      "등록된 댓글 정보를 확인할 수 없습니다.",
      {
        status:
          500
      }
    );
  }


  return {
    comment,
    clientRequestId,

    created:
      result.created !==
        false,

    duplicate:
      result.duplicate ===
        true,

    totalCount:
      Math.max(
        0,
        Number(
          result.totalCount ??
          0
        ) ||
        0
      )
  };
}


/* =========================================================
  본인 댓글 수정
========================================================= */

async function updateNoticeComment(
  options = {}
) {
  const id =
    normalizeNoticeCommentTargetId(
      options.id
    );


  const content =
    validateNoticeCommentContent(
      options.content
    );


  const expectedRevision =
    Number(
      options.expectedRevision ??
      options.revision
    );


  if (
    !id
  ) {
    throw new NoticeCommentApiError(
      "수정할 댓글 ID가 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  if (
    !Number.isInteger(
      expectedRevision
    ) ||
    expectedRevision <
      1
  ) {
    throw new NoticeCommentApiError(
      "댓글 수정 버전이 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  const result =
    await requestNoticeCommentApi({
      method:
        "PUT",

      body: {
        id,
        content,
        expectedRevision
      }
    });


  const comment =
    normalizeNoticeComment(
      result.comment
    );


  if (
    !comment.id
  ) {
    throw new NoticeCommentApiError(
      "수정된 댓글 정보를 확인할 수 없습니다.",
      {
        status:
          500
      }
    );
  }


  return comment;
}


/* =========================================================
  댓글 삭제
========================================================= */

async function deleteNoticeComment(
  options = {}
) {
  const id =
    normalizeNoticeCommentTargetId(
      options.id
    );


  const revision =
    Number(
      options.revision ??
      options.expectedRevision
    );


  if (
    !id
  ) {
    throw new NoticeCommentApiError(
      "삭제할 댓글 ID가 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  if (
    !Number.isInteger(
      revision
    ) ||
    revision <
      1
  ) {
    throw new NoticeCommentApiError(
      "댓글 삭제 버전이 올바르지 않습니다.",
      {
        status:
          400
      }
    );
  }


  const result =
    await requestNoticeCommentApi({
      method:
        "DELETE",

      searchParams: {
        id,
        revision
      }
    });


  return {
    deletedId:
      String(
        result.deletedId ||
        id
      ).trim(),

    noticeType:
      normalizeNoticeCommentType(
        result.noticeType ||
        result.notice_type
      ),

    noticeId:
      normalizeNoticeCommentTargetId(
        result.noticeId ||
        result.notice_id
      ),

    totalCount:
      Math.max(
        0,
        Number(
          result.totalCount ??
          0
        ) ||
        0
      )
  };
}

/* =========================================================
  공지사항 댓글 상태 + 공통 렌더링 기능

  전체공지:
  - noticeType = "global"

  보직공지:
  - noticeType = "role"

  이 블록의 역할:
  - 공지별 댓글 목록·개수·입력값·수정 상태 저장
  - 댓글 영역 공통 HTML 생성
  - 로딩·빈 목록·오류·수정 중 화면 출력
  - API 조회 결과를 화면 상태에 반영
========================================================= */

const noticeCommentState = {
  counts: new Map(),

  targets: new Map(),

  isLoadingCounts: false,

  countsLoaded: false,

  countErrorMessage: "",

  countRequestSequence: 0,

  countLoadPromise: null,

  generation: 0,

  eventsBound: false,
};


/* =========================================================
  공지 댓글 대상 키
========================================================= */

function getNoticeCommentTargetKey(
  noticeTypeValue,
  noticeIdValue
) {
  const noticeType =
    normalizeNoticeCommentType(
      noticeTypeValue
    );


  const noticeId =
    normalizeNoticeCommentTargetId(
      noticeIdValue
    );


  if (
    !noticeType ||
    !noticeId
  ) {
    return "";
  }


  return JSON.stringify([
    noticeType,
    noticeId
  ]);
}


/* =========================================================
  공지별 댓글 상태 생성·조회
========================================================= */

function getOrCreateNoticeCommentTargetState(
  noticeTypeValue,
  noticeIdValue
) {
  const noticeType =
    normalizeNoticeCommentType(
      noticeTypeValue
    );


  const noticeId =
    normalizeNoticeCommentTargetId(
      noticeIdValue
    );


  const targetKey =
    getNoticeCommentTargetKey(
      noticeType,
      noticeId
    );


  if (
    !targetKey
  ) {
    return null;
  }


  if (
    !noticeCommentState.targets.has(
      targetKey
    )
  ) {
    noticeCommentState.targets.set(
      targetKey,
      {
        noticeType,
        noticeId,

        comments: [],

        totalCount:
          noticeCommentState.counts.get(
            targetKey
          ) ||
          0,

        isOpen: false,

        isLoading: false,

        hasLoaded: false,

        errorMessage: "",

        draftContent: "",

        createClientRequestId: "",

        editingCommentId: "",

        editingDraft: "",

        pendingAction: "",

        pendingCommentId: "",

        requestSequence: 0,

        loadPromise: null
      }
    );
  }


  return noticeCommentState.targets.get(
    targetKey
  );
}


/* =========================================================
  댓글 개수 조회·저장
========================================================= */

function getNoticeCommentCount(
  noticeTypeValue,
  noticeIdValue
) {
  const targetKey =
    getNoticeCommentTargetKey(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetKey
  ) {
    return 0;
  }


  if (
    noticeCommentState.counts.has(
      targetKey
    )
  ) {
    return Math.max(
      0,
      Number(
        noticeCommentState.counts.get(
          targetKey
        )
      ) ||
      0
    );
  }


  return Math.max(
    0,
    Number(
      noticeCommentState.targets.get(
        targetKey
      )?.totalCount ||
      0
    ) ||
    0
  );
}


function setNoticeCommentCount(
  noticeTypeValue,
  noticeIdValue,
  countValue
) {
  const targetKey =
    getNoticeCommentTargetKey(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetKey
  ) {
    return 0;
  }


  const count =
    Math.max(
      0,
      Math.trunc(
        Number(
          countValue
        ) ||
        0
      )
    );


  noticeCommentState.counts.set(
    targetKey,
    count
  );


  const targetState =
    noticeCommentState.targets.get(
      targetKey
    );


  if (
    targetState
  ) {
    targetState.totalCount =
      count;
  }


  return count;
}


function replaceNoticeCommentCounts(
  countItems,
  noticeTypeValue = ""
) {
  const rawNoticeType =
    String(
      noticeTypeValue ||
      ""
    ).trim();


  const noticeType =
    rawNoticeType
      ? normalizeNoticeCommentType(
          rawNoticeType
        )
      : "";


  if (
    rawNoticeType &&
    !noticeType
  ) {
    return;
  }


  if (
    noticeType
  ) {
    [
      ...noticeCommentState.counts.keys()
    ].forEach(
      targetKey => {
        const targetState =
          noticeCommentState.targets.get(
            targetKey
          );


        let targetType =
          targetState?.noticeType ||
          "";


        if (
          !targetType
        ) {
          try {
            targetType =
              JSON.parse(
                targetKey
              )?.[0] ||
              "";

          } catch {
            targetType =
              "";
          }
        }


        if (
          targetType ===
            noticeType
        ) {
          noticeCommentState.counts.delete(
            targetKey
          );


          if (
            targetState
          ) {
            targetState.totalCount =
              0;
          }
        }
      }
    );

  } else {
    noticeCommentState.counts.clear();


    noticeCommentState.targets.forEach(
      targetState => {
        targetState.totalCount =
          0;
      }
    );
  }


  (
    Array.isArray(
      countItems
    )
      ? countItems
      : []
  ).forEach(
    item => {
      setNoticeCommentCount(
        item?.noticeType ||
        item?.notice_type,

        item?.noticeId ||
        item?.notice_id,

        item?.count ??
        item?.commentCount ??
        item?.comment_count ??
        0
      );
    }
  );
}


/* =========================================================
  댓글 작성일시 표시
========================================================= */

function formatNoticeCommentDateTime(
  value
) {
  const date =
    new Date(
      value
    );


  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return "-";
  }


  return [
    date.getFullYear(),
    ".",

    String(
      date.getMonth() +
      1
    ).padStart(
      2,
      "0"
    ),

    ".",

    String(
      date.getDate()
    ).padStart(
      2,
      "0"
    ),

    " ",

    String(
      date.getHours()
    ).padStart(
      2,
      "0"
    ),

    ":",

    String(
      date.getMinutes()
    ).padStart(
      2,
      "0"
    )
  ].join("");
}


/* =========================================================
  댓글 작성자 표시
========================================================= */

function getNoticeCommentAuthorText(
  comment
) {
  const authorName =
    String(
      comment?.createdByName ||
      comment?.createdBy ||
      "작성자 미확인"
    ).trim();


  const position =
    String(
      comment?.createdByPosition ||
      ""
    ).trim();


  return position
    ? `${authorName} · ${position}`
    : authorName;
}


/* =========================================================
  댓글 영역 DOM ID
========================================================= */

function createNoticeCommentPanelId(
  noticeTypeValue,
  noticeIdValue
) {
  const targetKey =
    getNoticeCommentTargetKey(
      noticeTypeValue,
      noticeIdValue
    ) ||
    "notice-comment";


  let hash =
    2166136261;


  for (
    let index = 0;
    index < targetKey.length;
    index += 1
  ) {
    hash ^=
      targetKey.charCodeAt(
        index
      );


    hash =
      Math.imul(
        hash,
        16777619
      );
  }


  return [
    "noticeCommentPanel",

    normalizeNoticeCommentType(
      noticeTypeValue
    ) ||
    "notice",

    (
      hash >>>
      0
    ).toString(
      36
    )
  ].join("-");
}


/* =========================================================
  댓글 1개 HTML
========================================================= */

function createNoticeCommentItemHtml(
  comment,
  targetState
) {
  const isEditing =
    targetState.editingCommentId ===
      comment.id;


  const isPending =
    targetState.pendingCommentId ===
      comment.id;


  const isBusy =
    Boolean(
      targetState.pendingAction
    );


  const authorText =
    getNoticeCommentAuthorText(
      comment
    );


  const dateText =
    formatNoticeCommentDateTime(
      comment.updatedAt ||
      comment.createdAt
    );


  if (
    isEditing
  ) {
    const editingDraft =
      normalizeNoticeCommentContent(
        targetState.editingDraft
      ).slice(
        0,
        NOTICE_COMMENT_MAX_LENGTH
      );


    return `
      <article
        class="notice-comment-item is-editing"
        data-notice-comment-item="${escapeHtml(
          comment.id
        )}"
      >

        <div class="notice-comment-item__meta">

          <strong class="notice-comment-item__author">
            ${escapeHtml(
              authorText
            )}
          </strong>


          <span class="notice-comment-item__date">
            ${escapeHtml(
              dateText
            )}
          </span>

        </div>


        <form
          class="notice-comment-edit-form"
          data-notice-comment-edit-form="${escapeHtml(
            comment.id
          )}"
          data-notice-comment-revision="${escapeHtml(
            comment.revision
          )}"
        >

          <textarea
            class="notice-comment-edit-form__input"
            data-notice-comment-edit-input
            maxlength="${NOTICE_COMMENT_MAX_LENGTH}"
            rows="3"
            aria-label="댓글 수정 내용"
            ${isBusy ? "disabled" : ""}
          >${escapeHtml(
            editingDraft
          )}</textarea>


          <div class="notice-comment-edit-form__footer">

            <span
              class="notice-comment-edit-form__count"
              data-notice-comment-edit-length
            >
              ${editingDraft.length}/${NOTICE_COMMENT_MAX_LENGTH}
            </span>


            <div class="notice-comment-edit-form__actions">

              <button
                type="button"
                class="notice-comment-button is-cancel"
                data-notice-comment-cancel-edit="${escapeHtml(
                  comment.id
                )}"
                ${isBusy ? "disabled" : ""}
              >
                취소
              </button>


              <button
                type="submit"
                class="notice-comment-button is-save"
                ${
                  isBusy ||
                  !editingDraft
                    ? "disabled"
                    : ""
                }
              >
                ${
                  isPending &&
                  targetState.pendingAction ===
                    "update"
                    ? "저장 중"
                    : "저장"
                }
              </button>

            </div>

          </div>

        </form>

      </article>
    `;
  }


  return `
    <article
      class="
        notice-comment-item
        ${isPending ? "is-pending" : ""}
      "
      data-notice-comment-item="${escapeHtml(
        comment.id
      )}"
    >

      <div class="notice-comment-item__meta">

        <strong class="notice-comment-item__author">
          ${escapeHtml(
            authorText
          )}
        </strong>


        <span class="notice-comment-item__date">
          ${escapeHtml(
            dateText
          )}

          ${comment.isEdited ? " · 수정됨" : ""}
        </span>

      </div>


      <p class="notice-comment-item__content">${escapeHtml(
        comment.content
      )}</p>


      ${
        comment.canEdit ||
        comment.canDelete
          ? `
            <div class="notice-comment-item__actions">

              ${
                comment.canEdit
                  ? `
                    <button
                      type="button"
                      class="notice-comment-item__action"
                      data-notice-comment-edit="${escapeHtml(
                        comment.id
                      )}"
                      ${isBusy ? "disabled" : ""}
                    >
                      수정
                    </button>
                  `
                  : ""
              }


              ${
                comment.canDelete
                  ? `
                    <button
                      type="button"
                      class="notice-comment-item__action is-delete"
                      data-notice-comment-delete="${escapeHtml(
                        comment.id
                      )}"
                      ${isBusy ? "disabled" : ""}
                    >
                      ${
                        isPending &&
                        targetState.pendingAction ===
                          "delete"
                          ? "삭제 중"
                          : "삭제"
                      }
                    </button>
                  `
                  : ""
              }

            </div>
          `
          : ""
      }

    </article>
  `;
}


/* =========================================================
  댓글 패널 내부 HTML
========================================================= */

function createNoticeCommentPanelContentHtml(
  targetState
) {
  const comments =
    Array.isArray(
      targetState.comments
    )
      ? targetState.comments
      : [];


  const isBusy =
    Boolean(
      targetState.pendingAction
    );


  const draftContent =
    String(
      targetState.draftContent ||
      ""
    ).slice(
      0,
      NOTICE_COMMENT_MAX_LENGTH
    );


  let listHtml =
    "";


  if (
    targetState.isLoading &&
    !targetState.hasLoaded
  ) {
    listHtml = `
      <div
        class="notice-comment-status is-loading"
        role="status"
      >
        댓글을 불러오는 중입니다.
      </div>
    `;

  } else if (
    comments.length
  ) {
    listHtml = `
      <div
        class="notice-comment-list"
        role="list"
      >
        ${comments
          .map(
            comment => {
              return createNoticeCommentItemHtml(
                comment,
                targetState
              );
            }
          )
          .join("")}
      </div>
    `;

  } else {
    listHtml = `
      <div class="notice-comment-status is-empty">
        아직 등록된 댓글이 없습니다.
      </div>
    `;
  }


  const errorHtml =
    targetState.errorMessage
      ? `
        <div
          class="notice-comment-status is-error"
          role="alert"
        >
          <span>
            ${escapeHtml(
              targetState.errorMessage
            )}
          </span>

          <button
            type="button"
            class="notice-comment-status__retry"
            data-notice-comment-retry
            ${
              targetState.isLoading ||
              isBusy
                ? "disabled"
                : ""
            }
          >
            다시 불러오기
          </button>
        </div>
      `
      : "";


  const refreshingHtml =
    targetState.isLoading &&
    targetState.hasLoaded
      ? `
        <p
          class="notice-comment-refreshing"
          role="status"
        >
          댓글을 새로 불러오는 중입니다.
        </p>
      `
      : "";


  return `
    <div class="notice-comment-panel__header">

      <strong class="notice-comment-panel__title">
        댓글
      </strong>

      <span
        class="notice-comment-panel__total"
        data-notice-comment-count
      >
        ${targetState.totalCount}
      </span>

    </div>


    ${errorHtml}

    ${refreshingHtml}

    ${listHtml}


    <form
      class="notice-comment-create-form"
      data-notice-comment-create-form
    >

      <textarea
        class="notice-comment-create-form__input"
        data-notice-comment-input
        maxlength="${NOTICE_COMMENT_MAX_LENGTH}"
        rows="3"
        placeholder="댓글을 입력해 주세요."
        aria-label="새 댓글 내용"
        ${isBusy ? "disabled" : ""}
      >${escapeHtml(
        draftContent
      )}</textarea>


      <div class="notice-comment-create-form__footer">

        <span
          class="notice-comment-create-form__count"
          data-notice-comment-length
        >
          ${draftContent.length}/${NOTICE_COMMENT_MAX_LENGTH}
        </span>


        <button
          type="submit"
          class="notice-comment-create-form__submit"
          ${
            isBusy ||
            !draftContent.trim()
              ? "disabled"
              : ""
          }
        >
          ${
            targetState.pendingAction ===
              "create"
              ? "등록 중"
              : "등록"
          }
        </button>

      </div>

    </form>
  `;
}


/* =========================================================
  공지 카드에 넣을 댓글 영역 HTML
========================================================= */

function createNoticeCommentSectionHtml(
  noticeTypeValue,
  noticeIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return "";
  }


  const panelId =
    createNoticeCommentPanelId(
      targetState.noticeType,
      targetState.noticeId
    );


  const count =
    getNoticeCommentCount(
      targetState.noticeType,
      targetState.noticeId
    );


  targetState.totalCount =
    count;


  return `
    <section
      class="
        notice-comment-section
        ${targetState.isOpen ? "is-open" : ""}
      "
      data-notice-comment-root
      data-notice-comment-type="${escapeHtml(
        targetState.noticeType
      )}"
      data-notice-comment-id="${escapeHtml(
        targetState.noticeId
      )}"
    >

      <button
        type="button"
        class="notice-comment-toggle"
        data-notice-comment-toggle
        aria-expanded="${targetState.isOpen ? "true" : "false"}"
        aria-controls="${escapeHtml(
          panelId
        )}"
      >
        <span class="notice-comment-toggle__label">
          댓글
        </span>

        <span
          class="notice-comment-toggle__count"
          data-notice-comment-count
        >
          ${count}
        </span>
      </button>


      <div
        id="${escapeHtml(
          panelId
        )}"
        class="notice-comment-panel"
        data-notice-comment-panel
        ${targetState.isOpen ? "" : "hidden"}
      >
        ${createNoticeCommentPanelContentHtml(
          targetState
        )}
      </div>

    </section>
  `;
}


/* =========================================================
  댓글 DOM에서 대상 정보 확인
========================================================= */

function getNoticeCommentTargetFromElement(
  element
) {
  const root =
    element?.closest?.(
      "[data-notice-comment-root]"
    );


  if (
    !root
  ) {
    return null;
  }


  const noticeType =
    normalizeNoticeCommentType(
      root.dataset.noticeCommentType
    );


  const noticeId =
    normalizeNoticeCommentTargetId(
      root.dataset.noticeCommentId
    );


  if (
    !noticeType ||
    !noticeId
  ) {
    return null;
  }


  return {
    root,
    noticeType,
    noticeId,

    targetState:
      getOrCreateNoticeCommentTargetState(
        noticeType,
        noticeId
      )
  };
}


/* =========================================================
  현재 입력 중인 댓글을 상태에 보존
========================================================= */

function captureNoticeCommentDrafts(
  root,
  targetState
) {
  if (
    !root ||
    !targetState
  ) {
    return;
  }


  const createInput =
    root.querySelector(
      "[data-notice-comment-input]"
    );


  if (
    createInput
  ) {
    targetState.draftContent =
      String(
        createInput.value ||
        ""
      ).slice(
        0,
        NOTICE_COMMENT_MAX_LENGTH
      );
  }


  const editInput =
    root.querySelector(
      "[data-notice-comment-edit-input]"
    );


  if (
    editInput &&
    targetState.editingCommentId
  ) {
    targetState.editingDraft =
      String(
        editInput.value ||
        ""
      ).slice(
        0,
        NOTICE_COMMENT_MAX_LENGTH
      );
  }
}


/* =========================================================
  특정 공지의 댓글 영역 찾기
========================================================= */

function getNoticeCommentRoots(
  noticeTypeValue,
  noticeIdValue
) {
  const noticeType =
    normalizeNoticeCommentType(
      noticeTypeValue
    );


  const noticeId =
    normalizeNoticeCommentTargetId(
      noticeIdValue
    );


  if (
    !noticeType ||
    !noticeId
  ) {
    return [];
  }


  return [
    ...document.querySelectorAll(
      "[data-notice-comment-root]"
    )
  ].filter(
    root => {
      return (
        normalizeNoticeCommentType(
          root.dataset.noticeCommentType
        ) ===
          noticeType &&
        normalizeNoticeCommentTargetId(
          root.dataset.noticeCommentId
        ) ===
          noticeId
      );
    }
  );
}


/* =========================================================
  특정 공지 댓글 영역 다시 출력
========================================================= */

function renderNoticeCommentTarget(
  noticeTypeValue,
  noticeIdValue,
  options = {}
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return;
  }


  const roots =
    getNoticeCommentRoots(
      targetState.noticeType,
      targetState.noticeId
    );


  if (
    !roots.length
  ) {
    return;
  }


  const activeRoot =
    roots.find(
      root => {
        return root.contains(
          document.activeElement
        );
      }
    ) ||
    roots[0];


  captureNoticeCommentDrafts(
    activeRoot,
    targetState
  );


  const panelId =
    createNoticeCommentPanelId(
      targetState.noticeType,
      targetState.noticeId
    );


  roots.forEach(
    root => {
      root.classList.toggle(
        "is-open",
        targetState.isOpen
      );


      root.classList.toggle(
        "is-loading",
        targetState.isLoading
      );


      root.classList.toggle(
        "has-error",
        Boolean(
          targetState.errorMessage
        )
      );


      root
        .querySelectorAll(
          "[data-notice-comment-count]"
        )
        .forEach(
          countElement => {
            countElement.textContent =
              String(
                targetState.totalCount
              );
          }
        );


      const toggleButton =
        root.querySelector(
          "[data-notice-comment-toggle]"
        );


      if (
        toggleButton
      ) {
        toggleButton.setAttribute(
          "aria-expanded",
          targetState.isOpen
            ? "true"
            : "false"
        );


        toggleButton.setAttribute(
          "aria-controls",
          panelId
        );
      }


      const panel =
        root.querySelector(
          "[data-notice-comment-panel]"
        );


      if (
        panel
      ) {
        panel.id =
          panelId;


        panel.hidden =
          !targetState.isOpen;


        panel.innerHTML =
          createNoticeCommentPanelContentHtml(
            targetState
          );
      }
    }
  );


  const focusTarget =
    String(
      options.focus ||
      ""
    );


  if (
    focusTarget &&
    targetState.isOpen
  ) {
    window.requestAnimationFrame(
      () => {
        const refreshedRoot =
          getNoticeCommentRoots(
            targetState.noticeType,
            targetState.noticeId
          )[0];


        const input =
          focusTarget ===
            "edit"
            ? refreshedRoot?.querySelector(
                "[data-notice-comment-edit-input]"
              )
            : refreshedRoot?.querySelector(
                "[data-notice-comment-input]"
              );


        input?.focus();
      }
    );
  }
}


/* =========================================================
  화면에 있는 모든 댓글 개수 갱신
========================================================= */

function renderAllNoticeCommentCounts() {
  document
    .querySelectorAll(
      "[data-notice-comment-root]"
    )
    .forEach(
      root => {
        const target =
          getNoticeCommentTargetFromElement(
            root
          );


        if (
          !target
        ) {
          return;
        }


        const count =
          getNoticeCommentCount(
            target.noticeType,
            target.noticeId
          );


        target.targetState.totalCount =
          count;


        root
          .querySelectorAll(
            "[data-notice-comment-count]"
          )
          .forEach(
            countElement => {
              countElement.textContent =
                String(
                  count
                );
            }
          );
      }
    );
}


/* =========================================================
  화면에 있는 열린 댓글 영역 다시 출력
========================================================= */

function renderAllOpenNoticeCommentTargets() {
  const renderedTargetKeys =
    new Set();


  document
    .querySelectorAll(
      "[data-notice-comment-root]"
    )
    .forEach(
      root => {
        const target =
          getNoticeCommentTargetFromElement(
            root
          );


        if (
          !target ||
          !target.targetState.isOpen
        ) {
          return;
        }


        const targetKey =
          getNoticeCommentTargetKey(
            target.noticeType,
            target.noticeId
          );


        if (
          renderedTargetKeys.has(
            targetKey
          )
        ) {
          return;
        }


        renderedTargetKeys.add(
          targetKey
        );


        renderNoticeCommentTarget(
          target.noticeType,
          target.noticeId
        );
      }
    );


  renderAllNoticeCommentCounts();
}


/* =========================================================
  댓글 영역 열기·닫기
========================================================= */

function setNoticeCommentTargetOpen(
  noticeTypeValue,
  noticeIdValue,
  isOpen
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return null;
  }


  targetState.isOpen =
    Boolean(
      isOpen
    );


  targetState.errorMessage =
    targetState.isOpen
      ? targetState.errorMessage
      : "";


  renderNoticeCommentTarget(
    targetState.noticeType,
    targetState.noticeId,
    {
      focus:
        targetState.isOpen &&
        targetState.hasLoaded
          ? "create"
          : ""
    }
  );


  return targetState;
}


function toggleNoticeCommentTarget(
  noticeTypeValue,
  noticeIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return null;
  }


  return setNoticeCommentTargetOpen(
    targetState.noticeType,
    targetState.noticeId,
    !targetState.isOpen
  );
}


/* =========================================================
  댓글 목록 상태 반영
========================================================= */

function setNoticeCommentsForTarget(
  noticeTypeValue,
  noticeIdValue,
  commentsValue,
  totalCountValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return null;
  }


  const comments =
    (
      Array.isArray(
        commentsValue
      )
        ? commentsValue
        : []
    )
      .map(
        normalizeNoticeComment
      )
      .filter(
        comment => {
          return (
            comment.id &&
            comment.noticeType ===
              targetState.noticeType &&
            comment.noticeId ===
              targetState.noticeId
          );
        }
      )
      .sort(
        (
          firstComment,
          secondComment
        ) => {
          const createdDifference =
            String(
              firstComment.createdAt ||
              ""
            ).localeCompare(
              String(
                secondComment.createdAt ||
                ""
              )
            );


          if (
            createdDifference !==
              0
          ) {
            return createdDifference;
          }


          return firstComment.id.localeCompare(
            secondComment.id
          );
        }
      );


  targetState.comments =
    comments;


  targetState.hasLoaded =
    true;


  const totalCount =
    totalCountValue ===
      undefined
      ? comments.length
      : Math.max(
          comments.length,
          Number(
            totalCountValue
          ) ||
          0
        );


  setNoticeCommentCount(
    targetState.noticeType,
    targetState.noticeId,
    totalCount
  );


  if (
    targetState.editingCommentId &&
    !comments.some(
      comment => {
        return comment.id ===
          targetState.editingCommentId;
      }
    )
  ) {
    targetState.editingCommentId =
      "";


    targetState.editingDraft =
      "";
  }


  return targetState;
}


function upsertNoticeCommentInState(
  commentValue,
  totalCountValue
) {
  const comment =
    normalizeNoticeComment(
      commentValue
    );


  const targetState =
    getOrCreateNoticeCommentTargetState(
      comment.noticeType,
      comment.noticeId
    );


  if (
    !targetState ||
    !comment.id
  ) {
    return null;
  }


  const existingIndex =
    targetState.comments.findIndex(
      currentComment => {
        return currentComment.id ===
          comment.id;
      }
    );


  if (
    existingIndex >=
      0
  ) {
    targetState.comments[
      existingIndex
    ] =
      comment;

  } else {
    targetState.comments.push(
      comment
    );
  }


  targetState.comments.sort(
    (
      firstComment,
      secondComment
    ) => {
      return String(
        firstComment.createdAt ||
        ""
      ).localeCompare(
        String(
          secondComment.createdAt ||
          ""
        )
      );
    }
  );


  targetState.hasLoaded =
    true;


  setNoticeCommentCount(
    targetState.noticeType,
    targetState.noticeId,

    totalCountValue ===
      undefined
      ? targetState.comments.length
      : totalCountValue
  );


  return targetState;
}


function removeNoticeCommentFromState(
  noticeTypeValue,
  noticeIdValue,
  commentIdValue,
  totalCountValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  const commentId =
    normalizeNoticeCommentTargetId(
      commentIdValue
    );


  if (
    !targetState ||
    !commentId
  ) {
    return null;
  }


  targetState.comments =
    targetState.comments.filter(
      comment => {
        return comment.id !==
          commentId;
      }
    );


  if (
    targetState.editingCommentId ===
      commentId
  ) {
    targetState.editingCommentId =
      "";


    targetState.editingDraft =
      "";
  }


  setNoticeCommentCount(
    targetState.noticeType,
    targetState.noticeId,

    totalCountValue ===
      undefined
      ? targetState.comments.length
      : totalCountValue
  );


  return targetState;
}


/* =========================================================
  댓글 입력·수정·처리 중 상태
========================================================= */

function setNoticeCommentDraft(
  noticeTypeValue,
  noticeIdValue,
  value
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return "";
  }


  targetState.draftContent =
    String(
      value ||
      ""
    ).slice(
      0,
      NOTICE_COMMENT_MAX_LENGTH
    );


  return targetState.draftContent;
}


function beginNoticeCommentEdit(
  noticeTypeValue,
  noticeIdValue,
  commentIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  const commentId =
    normalizeNoticeCommentTargetId(
      commentIdValue
    );


  const comment =
    targetState?.comments.find(
      currentComment => {
        return currentComment.id ===
          commentId;
      }
    );


  if (
    !targetState ||
    !comment ||
    !comment.canEdit
  ) {
    return null;
  }


  targetState.editingCommentId =
    comment.id;


  targetState.editingDraft =
    comment.content;


  targetState.errorMessage =
    "";


  renderNoticeCommentTarget(
    targetState.noticeType,
    targetState.noticeId,
    {
      focus:
        "edit"
    }
  );


  return comment;
}


function cancelNoticeCommentEdit(
  noticeTypeValue,
  noticeIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return;
  }


  targetState.editingCommentId =
    "";


  targetState.editingDraft =
    "";


  renderNoticeCommentTarget(
    targetState.noticeType,
    targetState.noticeId
  );
}


function setNoticeCommentPendingState(
  noticeTypeValue,
  noticeIdValue,
  action = "",
  commentId = ""
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return null;
  }


  targetState.pendingAction =
    String(
      action ||
      ""
    );


  targetState.pendingCommentId =
    normalizeNoticeCommentTargetId(
      commentId
    );


  renderNoticeCommentTarget(
    targetState.noticeType,
    targetState.noticeId
  );


  return targetState;
}


function getNoticeCommentCreateRequestId(
  noticeTypeValue,
  noticeIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    !targetState
  ) {
    return "";
  }


  if (
    !targetState.createClientRequestId
  ) {
    targetState.createClientRequestId =
      createNoticeCommentClientRequestId();
  }


  return targetState.createClientRequestId;
}


function clearNoticeCommentCreateRequestId(
  noticeTypeValue,
  noticeIdValue
) {
  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeTypeValue,
      noticeIdValue
    );


  if (
    targetState
  ) {
    targetState.createClientRequestId =
      "";
  }
}


/* =========================================================
  댓글 개수 서버 조회
========================================================= */

async function refreshNoticeCommentCounts(
  noticeTypeValue = ""
) {
  const rawNoticeType =
    String(
      noticeTypeValue ||
      ""
    ).trim();


  const noticeType =
    rawNoticeType
      ? normalizeNoticeCommentType(
          rawNoticeType
        )
      : "";


  if (
    rawNoticeType &&
    !noticeType
  ) {
    return [];
  }


  if (
    noticeCommentState.isLoadingCounts &&
    noticeCommentState.countLoadPromise
  ) {
    return noticeCommentState.countLoadPromise;
  }


  noticeCommentState.isLoadingCounts =
    true;


  noticeCommentState.countErrorMessage =
    "";


  noticeCommentState.countRequestSequence +=
    1;


  const requestSequence =
    noticeCommentState.countRequestSequence;


  const generation =
    noticeCommentState.generation;


  const loadPromise =
    (
      async () => {
        try {
          const counts =
            await loadNoticeCommentCounts(
              noticeType
            );


          if (
            generation !==
              noticeCommentState.generation ||
            requestSequence !==
              noticeCommentState.countRequestSequence
          ) {
            return counts;
          }


          replaceNoticeCommentCounts(
            counts,
            noticeType
          );


          noticeCommentState.countsLoaded =
            true;


          renderAllNoticeCommentCounts();


          return counts;

        } catch (
          error
        ) {
          console.error(
            "공지 댓글 개수 조회 실패:",
            error
          );


          if (
            generation ===
              noticeCommentState.generation &&
            requestSequence ===
              noticeCommentState.countRequestSequence
          ) {
            noticeCommentState.countErrorMessage =
              error?.message ||
              "댓글 개수를 불러오지 못했습니다.";
          }


          return [];

        } finally {
          if (
            generation ===
              noticeCommentState.generation &&
            requestSequence ===
              noticeCommentState.countRequestSequence
          ) {
            noticeCommentState.isLoadingCounts =
              false;


            noticeCommentState.countLoadPromise =
              null;
          }
        }
      }
    )();


  noticeCommentState.countLoadPromise =
    loadPromise;


  return loadPromise;
}


/* =========================================================
  특정 공지 댓글 서버 조회
========================================================= */

async function refreshNoticeComments(
  noticeTypeValue,
  noticeIdValue,
  options = {}
) {
  const {
    noticeType,
    noticeId
  } =
    validateNoticeCommentTarget(
      noticeTypeValue,
      noticeIdValue
    );


  const targetState =
    getOrCreateNoticeCommentTargetState(
      noticeType,
      noticeId
    );


  if (
    targetState.isLoading &&
    targetState.loadPromise
  ) {
    return targetState.loadPromise;
  }


  if (
    targetState.hasLoaded &&
    options.force !==
      true
  ) {
    renderNoticeCommentTarget(
      noticeType,
      noticeId
    );


    return targetState;
  }


  targetState.isLoading =
    true;


  targetState.errorMessage =
    "";


  targetState.requestSequence +=
    1;


  const requestSequence =
    targetState.requestSequence;


  const generation =
    noticeCommentState.generation;


  renderNoticeCommentTarget(
    noticeType,
    noticeId
  );


  const loadPromise =
    (
      async () => {
        try {
          const result =
            await loadNoticeComments(
              noticeType,
              noticeId
            );


          if (
            generation !==
              noticeCommentState.generation ||
            requestSequence !==
              targetState.requestSequence
          ) {
            return targetState;
          }


          setNoticeCommentsForTarget(
            noticeType,
            noticeId,
            result.comments,
            result.totalCount
          );


          targetState.errorMessage =
            "";


          return targetState;

        } catch (
          error
        ) {
          console.error(
            "공지 댓글 목록 조회 실패:",
            error
          );


          if (
            generation ===
              noticeCommentState.generation &&
            requestSequence ===
              targetState.requestSequence
          ) {
            targetState.errorMessage =
              error?.message ||
              "댓글을 불러오지 못했습니다.";
          }


          return targetState;

        } finally {
          if (
            generation ===
              noticeCommentState.generation &&
            requestSequence ===
              targetState.requestSequence
          ) {
            targetState.isLoading =
              false;


            targetState.loadPromise =
              null;


            renderNoticeCommentTarget(
              noticeType,
              noticeId
            );
          }
        }
      }
    )();


  targetState.loadPromise =
    loadPromise;


  return loadPromise;
}


/* =========================================================
  댓글 상태 초기화

  로그아웃 또는 사용자 변경 시 사용한다.
========================================================= */

function resetNoticeCommentState() {
  noticeCommentState.generation +=
    1;


  noticeCommentState.countRequestSequence +=
    1;


  noticeCommentState.counts.clear();


  noticeCommentState.targets.clear();


  noticeCommentState.isLoadingCounts =
    false;


  noticeCommentState.countsLoaded =
    false;


  noticeCommentState.countErrorMessage =
    "";


  noticeCommentState.countLoadPromise =
    null;
}

/* =========================================================
  공지사항 댓글 공통 이벤트

  - 댓글 영역 열기·닫기
  - 목록 다시 불러오기
  - 입력 글자 수 표시
  - 등록·수정·삭제
========================================================= */

function getNoticeCommentById(
  targetState,
  commentIdValue
) {
  const commentId =
    normalizeNoticeCommentTargetId(
      commentIdValue
    );

  if (
    !targetState ||
    !commentId
  ) {
    return null;
  }

  return (
    targetState.comments.find(
      comment => {
        return comment.id ===
          commentId;
      }
    ) ||
    null
  );
}


function initializeNoticeCommentEventState(
  targetState
) {
  if (
    !targetState
  ) {
    return null;
  }

  if (
    !Number.isInteger(
      targetState.editingRevision
    )
  ) {
    targetState.editingRevision =
      0;
  }

  return targetState;
}


function clearNoticeCommentCreateInputDom(
  noticeTypeValue,
  noticeIdValue
) {
  getNoticeCommentRoots(
    noticeTypeValue,
    noticeIdValue
  ).forEach(
    root => {
      const input =
        root.querySelector(
          "[data-notice-comment-input]"
        );

      if (
        input
      ) {
        input.value =
          "";
      }
    }
  );
}


function invalidateNoticeCommentCountRequest() {
  noticeCommentState.countRequestSequence +=
    1;

  noticeCommentState.isLoadingCounts =
    false;

  noticeCommentState.countLoadPromise =
    null;

  noticeCommentState.countErrorMessage =
    "";
}


function showNoticeCommentError(
  noticeTypeValue,
  noticeIdValue,
  error,
  options = {}
) {
  const targetState =
    initializeNoticeCommentEventState(
      getOrCreateNoticeCommentTargetState(
        noticeTypeValue,
        noticeIdValue
      )
    );

  if (
    !targetState
  ) {
    return;
  }

  targetState.errorMessage =
    error?.message ||
    String(
      error ||
      "댓글 처리 중 오류가 발생했습니다."
    );

  renderNoticeCommentTarget(
    targetState.noticeType,
    targetState.noticeId,
    options
  );
}


function handleNoticeCommentInput(
  event
) {
  const input =
    event.target;

  if (
    !input?.matches?.(
      "[data-notice-comment-input], " +
      "[data-notice-comment-edit-input]"
    )
  ) {
    return;
  }

  const target =
    getNoticeCommentTargetFromElement(
      input
    );

  if (
    !target?.targetState
  ) {
    return;
  }

  const targetState =
    initializeNoticeCommentEventState(
      target.targetState
    );

  const value =
    String(
      input.value ||
      ""
    ).slice(
      0,
      NOTICE_COMMENT_MAX_LENGTH
    );

  if (
    input.value !==
      value
  ) {
    input.value =
      value;
  }

  if (
    input.matches(
      "[data-notice-comment-edit-input]"
    )
  ) {
    targetState.editingDraft =
      value;

    const form =
      input.closest(
        "[data-notice-comment-edit-form]"
      );

    const lengthElement =
      form?.querySelector(
        "[data-notice-comment-edit-length]"
      );

    const submitButton =
      form?.querySelector(
        'button[type="submit"]'
      );

    if (
      lengthElement
    ) {
      lengthElement.textContent =
        `${value.length}/${NOTICE_COMMENT_MAX_LENGTH}`;
    }

    if (
      submitButton
    ) {
      submitButton.disabled =
        Boolean(
          targetState.pendingAction ||
          targetState.isLoading
        ) ||
        !normalizeNoticeCommentContent(
          value
        );
    }

    return;
  }

  const previousValue =
    targetState.draftContent;

  setNoticeCommentDraft(
    target.noticeType,
    target.noticeId,
    value
  );

  /*
    등록 실패 후 내용을 변경했다면
    이전 중복 방지 요청 ID는 폐기한다.

    내용을 바꾸지 않고 재시도할 때는
    기존 요청 ID를 그대로 유지한다.
  */
  if (
    previousValue !==
      value &&
    targetState.createClientRequestId &&
    !targetState.pendingAction
  ) {
    clearNoticeCommentCreateRequestId(
      target.noticeType,
      target.noticeId
    );
  }

  const form =
    input.closest(
      "[data-notice-comment-create-form]"
    );

  const lengthElement =
    form?.querySelector(
      "[data-notice-comment-length]"
    );

  const submitButton =
    form?.querySelector(
      'button[type="submit"]'
    );

  if (
    lengthElement
  ) {
    lengthElement.textContent =
      `${value.length}/${NOTICE_COMMENT_MAX_LENGTH}`;
  }

  if (
    submitButton
  ) {
    submitButton.disabled =
      Boolean(
        targetState.pendingAction ||
        targetState.isLoading
      ) ||
      !normalizeNoticeCommentContent(
        value
      );
  }
}


async function submitNoticeCommentCreate(
  form
) {
  const target =
    getNoticeCommentTargetFromElement(
      form
    );

  if (
    !target?.targetState ||
    target.targetState.pendingAction
  ) {
    return;
  }

  const targetState =
    initializeNoticeCommentEventState(
      target.targetState
    );

  const input =
    form.querySelector(
      "[data-notice-comment-input]"
    );

  const inputValue =
    input
      ? input.value
      : targetState.draftContent;

  setNoticeCommentDraft(
    target.noticeType,
    target.noticeId,
    inputValue
  );

  let content =
    "";

  try {
    content =
      validateNoticeCommentContent(
        targetState.draftContent
      );

  } catch (
    error
  ) {
    showNoticeCommentError(
      target.noticeType,
      target.noticeId,
      error,
      {
        focus:
          "create"
      }
    );

    return;
  }

  const generation =
    noticeCommentState.generation;

  /*
    댓글 목록을 불러오는 중이라면
    목록 조회가 끝난 다음 등록한다.
  */
  if (
    targetState.isLoading &&
    targetState.loadPromise
  ) {
    const loadPromise =
      targetState.loadPromise;

    setNoticeCommentPendingState(
      target.noticeType,
      target.noticeId,
      "create-wait"
    );

    await loadPromise;

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }

    if (
      !targetState.hasLoaded
    ) {
      targetState.pendingAction =
        "";

      targetState.pendingCommentId =
        "";

      renderNoticeCommentTarget(
        target.noticeType,
        target.noticeId
      );

      return;
    }
  }

  const clientRequestId =
    getNoticeCommentCreateRequestId(
      target.noticeType,
      target.noticeId
    );

  targetState.errorMessage =
    "";

  setNoticeCommentPendingState(
    target.noticeType,
    target.noticeId,
    "create"
  );

  try {
    const result =
      await createNoticeComment({
        noticeType:
          target.noticeType,

        noticeId:
          target.noticeId,

        content,

        clientRequestId
      });

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }

    invalidateNoticeCommentCountRequest();

    upsertNoticeCommentInState(
      result.comment,
      result.totalCount
    );

    targetState.draftContent =
      "";

    targetState.errorMessage =
      "";

    clearNoticeCommentCreateRequestId(
      target.noticeType,
      target.noticeId
    );

    /*
      성공 후 기존 textarea 값이 다시 상태에
      들어오는 것을 막기 위해 DOM 값도 비운다.
    */
    clearNoticeCommentCreateInputDom(
      target.noticeType,
      target.noticeId
    );

    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        "댓글이 등록되었습니다."
      );
    }

  } catch (
    error
  ) {
    console.error(
      "공지 댓글 등록 실패:",
      error
    );

    if (
      generation ===
        noticeCommentState.generation
    ) {
      targetState.errorMessage =
        error?.message ||
        "댓글을 등록하지 못했습니다.";
    }

  } finally {
    if (
      generation ===
        noticeCommentState.generation
    ) {
      targetState.pendingAction =
        "";

      targetState.pendingCommentId =
        "";

      renderNoticeCommentTarget(
        target.noticeType,
        target.noticeId,
        {
          focus:
            "create"
        }
      );
    }
  }
}


async function submitNoticeCommentEdit(
  form
) {
  const target =
    getNoticeCommentTargetFromElement(
      form
    );

  if (
    !target?.targetState ||
    target.targetState.pendingAction
  ) {
    return;
  }

  const targetState =
    initializeNoticeCommentEventState(
      target.targetState
    );

  const commentId =
    normalizeNoticeCommentTargetId(
      form.dataset.noticeCommentEditForm
    );

  const input =
    form.querySelector(
      "[data-notice-comment-edit-input]"
    );

  targetState.editingDraft =
    String(
      input
        ? input.value
        : targetState.editingDraft ||
          ""
    ).slice(
      0,
      NOTICE_COMMENT_MAX_LENGTH
    );

  let content =
    "";

  try {
    content =
      validateNoticeCommentContent(
        targetState.editingDraft
      );

  } catch (
    error
  ) {
    showNoticeCommentError(
      target.noticeType,
      target.noticeId,
      error,
      {
        focus:
          "edit"
      }
    );

    return;
  }

  const generation =
    noticeCommentState.generation;

  if (
    targetState.isLoading &&
    targetState.loadPromise
  ) {
    const loadPromise =
      targetState.loadPromise;

    setNoticeCommentPendingState(
      target.noticeType,
      target.noticeId,
      "update-wait",
      commentId
    );

    await loadPromise;

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }
  }

  const comment =
    getNoticeCommentById(
      targetState,
      commentId
    );

  if (
    !comment ||
    !comment.canEdit
  ) {
    targetState.pendingAction =
      "";

    targetState.pendingCommentId =
      "";

    targetState.editingRevision =
      0;

    showNoticeCommentError(
      target.noticeType,
      target.noticeId,
      "수정할 수 있는 댓글이 아닙니다."
    );

    return;
  }

  const expectedRevision =
    Number(
      targetState.editingRevision ||
      comment.revision
    );

  targetState.errorMessage =
    "";

  setNoticeCommentPendingState(
    target.noticeType,
    target.noticeId,
    "update",
    comment.id
  );

  try {
    const updatedComment =
      await updateNoticeComment({
        id:
          comment.id,

        content,

        expectedRevision
      });

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }

    upsertNoticeCommentInState(
      updatedComment,
      targetState.totalCount
    );

    targetState.editingCommentId =
      "";

    targetState.editingDraft =
      "";

    targetState.editingRevision =
      0;

    targetState.errorMessage =
      "";

    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        "댓글이 수정되었습니다."
      );
    }

  } catch (
    error
  ) {
    console.error(
      "공지 댓글 수정 실패:",
      error
    );

    if (
      generation ===
        noticeCommentState.generation
    ) {
      if (
        error?.isConflict &&
        error.currentComment
      ) {
        upsertNoticeCommentInState(
          error.currentComment,
          targetState.totalCount
        );

        if (
          error.currentComment.canEdit
        ) {
          targetState.editingCommentId =
            error.currentComment.id;

          targetState.editingRevision =
            error.currentComment.revision;

          targetState.errorMessage =
            "다른 화면에서 댓글이 먼저 수정되었습니다. " +
            "입력한 내용은 유지했습니다. 현재 내용으로 다시 반영하려면 저장을 다시 눌러 주세요.";

        } else {
          targetState.editingCommentId =
            "";

          targetState.editingDraft =
            "";

          targetState.editingRevision =
            0;

          targetState.errorMessage =
            "댓글이 변경되어 더 이상 수정할 수 없습니다.";
        }

      } else {
        targetState.errorMessage =
          error?.message ||
          "댓글을 수정하지 못했습니다.";
      }
    }

  } finally {
    if (
      generation ===
        noticeCommentState.generation
    ) {
      targetState.pendingAction =
        "";

      targetState.pendingCommentId =
        "";

      renderNoticeCommentTarget(
        target.noticeType,
        target.noticeId,
        {
          focus:
            targetState.editingCommentId
              ? "edit"
              : ""
        }
      );
    }
  }
}


async function removeNoticeComment(
  noticeTypeValue,
  noticeIdValue,
  commentIdValue
) {
  const targetState =
    initializeNoticeCommentEventState(
      getOrCreateNoticeCommentTargetState(
        noticeTypeValue,
        noticeIdValue
      )
    );

  if (
    !targetState ||
    targetState.pendingAction
  ) {
    return;
  }

  const firstComment =
    getNoticeCommentById(
      targetState,
      commentIdValue
    );

  if (
    !firstComment ||
    !firstComment.canDelete
  ) {
    showNoticeCommentError(
      noticeTypeValue,
      noticeIdValue,
      "삭제할 수 있는 댓글이 아닙니다."
    );

    return;
  }

  const generation =
    noticeCommentState.generation;

  /*
    비동기 확인창이 떠 있는 동안
    삭제 버튼 중복 클릭을 막는다.
  */
  setNoticeCommentPendingState(
    targetState.noticeType,
    targetState.noticeId,
    "delete-confirm",
    firstComment.id
  );

  let shouldDelete =
    false;

  try {
    shouldDelete =
      typeof showCompactConfirm ===
        "function"
        ? await showCompactConfirm({
            title:
              "댓글 삭제",

            message:
              "이 댓글을 삭제하시겠습니까? 삭제한 댓글은 복구할 수 없습니다.",

            confirmText:
              "삭제",

            cancelText:
              "취소"
          })
        : window.confirm(
            "이 댓글을 삭제하시겠습니까?\n" +
            "삭제한 댓글은 복구할 수 없습니다."
          );

  } catch (
    error
  ) {
    console.error(
      "댓글 삭제 확인창 오류:",
      error
    );
  }

  if (
    generation !==
      noticeCommentState.generation
  ) {
    return;
  }

  if (
    !shouldDelete
  ) {
    targetState.pendingAction =
      "";

    targetState.pendingCommentId =
      "";

    renderNoticeCommentTarget(
      targetState.noticeType,
      targetState.noticeId
    );

    return;
  }

  if (
    targetState.isLoading &&
    targetState.loadPromise
  ) {
    const loadPromise =
      targetState.loadPromise;

    setNoticeCommentPendingState(
      targetState.noticeType,
      targetState.noticeId,
      "delete-wait",
      firstComment.id
    );

    await loadPromise;

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }
  }

  const comment =
    getNoticeCommentById(
      targetState,
      firstComment.id
    );

  if (
    !comment ||
    !comment.canDelete
  ) {
    targetState.pendingAction =
      "";

    targetState.pendingCommentId =
      "";

    showNoticeCommentError(
      targetState.noticeType,
      targetState.noticeId,
      "댓글이 변경되어 현재 상태에서는 삭제할 수 없습니다."
    );

    return;
  }

  targetState.errorMessage =
    "";

  setNoticeCommentPendingState(
    targetState.noticeType,
    targetState.noticeId,
    "delete",
    comment.id
  );

  try {
    const result =
      await deleteNoticeComment({
        id:
          comment.id,

        revision:
          comment.revision
      });

    if (
      generation !==
        noticeCommentState.generation
    ) {
      return;
    }

    const deletedId =
      result.deletedId ||
      comment.id;

    const deletedCommentWasEditing =
      targetState.editingCommentId ===
        deletedId;

    invalidateNoticeCommentCountRequest();

    removeNoticeCommentFromState(
      result.noticeType ||
      targetState.noticeType,

      result.noticeId ||
      targetState.noticeId,

      deletedId,

      result.totalCount
    );

    if (
      deletedCommentWasEditing
    ) {
      targetState.editingRevision =
        0;
    }

    targetState.errorMessage =
      "";

    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        "댓글이 삭제되었습니다."
      );
    }

  } catch (
    error
  ) {
    console.error(
      "공지 댓글 삭제 실패:",
      error
    );

    if (
      generation ===
        noticeCommentState.generation
    ) {
      if (
        error?.isConflict &&
        error.currentComment
      ) {
        upsertNoticeCommentInState(
          error.currentComment,
          targetState.totalCount
        );

        targetState.errorMessage =
          error.message ||
          "댓글이 다른 곳에서 먼저 수정되었습니다. 최신 내용을 확인한 뒤 다시 삭제해 주세요.";

      } else {
        targetState.errorMessage =
          error?.message ||
          "댓글을 삭제하지 못했습니다.";
      }
    }

  } finally {
    if (
      generation ===
        noticeCommentState.generation
    ) {
      targetState.pendingAction =
        "";

      targetState.pendingCommentId =
        "";

      renderNoticeCommentTarget(
        targetState.noticeType,
        targetState.noticeId
      );
    }
  }
}


function handleNoticeCommentClick(
  event
) {
  const clickedElement =
    event.target;

  if (
    !clickedElement?.closest
  ) {
    return;
  }

  const actionElement =
    clickedElement.closest(
      "[data-notice-comment-toggle], " +
      "[data-notice-comment-retry], " +
      "[data-notice-comment-edit], " +
      "[data-notice-comment-cancel-edit], " +
      "[data-notice-comment-delete]"
    );

  if (
    !actionElement
  ) {
    return;
  }

  const target =
    getNoticeCommentTargetFromElement(
      actionElement
    );

  if (
    !target?.targetState
  ) {
    return;
  }

  const targetState =
    initializeNoticeCommentEventState(
      target.targetState
    );

  event.preventDefault();

  if (
    actionElement.matches(
      "[data-notice-comment-toggle]"
    )
  ) {
    const toggledState =
      toggleNoticeCommentTarget(
        target.noticeType,
        target.noticeId
      );

    if (
      toggledState?.isOpen
    ) {
      const generation =
        noticeCommentState.generation;

      void refreshNoticeComments(
        target.noticeType,
        target.noticeId
      ).then(
        loadedState => {
          if (
            generation ===
              noticeCommentState.generation &&
            loadedState?.isOpen &&
            loadedState.hasLoaded
          ) {
            renderNoticeCommentTarget(
              target.noticeType,
              target.noticeId,
              {
                focus:
                  "create"
              }
            );
          }
        }
      );
    }

    return;
  }

  if (
    actionElement.matches(
      "[data-notice-comment-retry]"
    )
  ) {
    void refreshNoticeComments(
      target.noticeType,
      target.noticeId,
      {
        force:
          true
      }
    );

    return;
  }

  if (
    actionElement.matches(
      "[data-notice-comment-edit]"
    )
  ) {
    const comment =
      getNoticeCommentById(
        targetState,
        actionElement.dataset.noticeCommentEdit
      );

    if (
      comment?.canEdit
    ) {
      targetState.editingRevision =
        comment.revision;

      beginNoticeCommentEdit(
        target.noticeType,
        target.noticeId,
        comment.id
      );
    }

    return;
  }

  if (
    actionElement.matches(
      "[data-notice-comment-cancel-edit]"
    )
  ) {
    targetState.editingRevision =
      0;

    cancelNoticeCommentEdit(
      target.noticeType,
      target.noticeId
    );

    return;
  }

  if (
    actionElement.matches(
      "[data-notice-comment-delete]"
    )
  ) {
    void removeNoticeComment(
      target.noticeType,
      target.noticeId,
      actionElement.dataset.noticeCommentDelete
    );
  }
}


function handleNoticeCommentSubmit(
  event
) {
  const form =
    event.target;

  if (
    form?.matches?.(
      "[data-notice-comment-create-form]"
    )
  ) {
    event.preventDefault();

    void submitNoticeCommentCreate(
      form
    );

    return;
  }

  if (
    form?.matches?.(
      "[data-notice-comment-edit-form]"
    )
  ) {
    event.preventDefault();

    void submitNoticeCommentEdit(
      form
    );
  }
}


function bindNoticeCommentEvents() {
  if (
    noticeCommentState.eventsBound
  ) {
    return;
  }

  noticeCommentState.eventsBound =
    true;

  /*
    공지 카드는 목록 렌더링 때마다 교체되므로
    document 이벤트 위임 방식으로 한 번만 연결한다.
  */
  document.addEventListener(
    "click",
    handleNoticeCommentClick
  );

  document.addEventListener(
    "input",
    handleNoticeCommentInput
  );

  document.addEventListener(
    "submit",
    handleNoticeCommentSubmit
  );
}


bindNoticeCommentEvents();

/* =========================================================
  공지 댓글 개수 최초 일괄 조회

  - 전체공지와 보직공지 개수를 한 번에 조회
  - 이미 조회했다면 현재 화면에 저장된 개수만 반영
  - 조회 실패 시 다음 공지창 열기에서 다시 시도
========================================================= */

async function ensureNoticeCommentCountsLoaded() {
  if (
    noticeCommentState.countsLoaded
  ) {
    renderAllNoticeCommentCounts();

    return;
  }


  await refreshNoticeCommentCounts();
}

