/* =====================================================
  날짜 숫자 두 자리 처리
===================================================== */

function padAuxiliaryMaterialDateNumber(
  value
) {
  return String(
    value
  ).padStart(
    2,
    "0"
  );
}


/* =====================================================
  Date 객체를 YYYY-MM-DD 형식으로 변환

  UTC가 아닌 현재 PC의 로컬 날짜를 사용한다.
===================================================== */

function formatAuxiliaryMaterialIsoDate(
  date
) {
  if (
    !(
      date instanceof
        Date
    ) ||
    Number.isNaN(
      date.getTime()
    )
  ) {
    return "";
  }


  return [
    date.getFullYear(),

    padAuxiliaryMaterialDateNumber(
      date.getMonth() +
      1
    ),

    padAuxiliaryMaterialDateNumber(
      date.getDate()
    )
  ].join(
    "-"
  );
}


/* =====================================================
  현재 월 반환

  형식:
  YYYY-MM
===================================================== */

function getCurrentAuxiliaryMaterialMonthValue() {
  const today =
    new Date();


  return (
    `${today.getFullYear()}-` +
    `${padAuxiliaryMaterialDateNumber(
      today.getMonth() +
      1
    )}`
  );
}


/* =====================================================
  선택한 월의 시작일·종료일 계산

  과거 월:
  해당 월 1일 ~ 말일

  현재 월:
  해당 월 1일 ~ 오늘

  미래 월:
  조회하지 않음
===================================================== */

function getAuxiliaryMaterialMonthRange(
  monthValue
) {
  const match =
    String(
      monthValue ||
      ""
    ).match(
      /^(\d{4})-(\d{2})$/
    );


  if (
    !match
  ) {
    return null;
  }


  const year =
    Number(
      match[1]
    );


  const month =
    Number(
      match[2]
    );


  if (
    !Number.isInteger(
      year
    ) ||
    month <
      1 ||
    month >
      12
  ) {
    return null;
  }


  const firstDate =
    new Date(
      year,
      month -
        1,
      1
    );


  const lastDate =
    new Date(
      year,
      month,
      0
    );


  const today =
    new Date();


  today.setHours(
    0,
    0,
    0,
    0
  );


  /*
    미래 월은 조회하지 않는다.
  */
  if (
    firstDate >
      today
  ) {
    return null;
  }


  const endDate =
    lastDate >
      today
      ? today
      : lastDate;


  return {
    startDate:
      formatAuxiliaryMaterialIsoDate(
        firstDate
      ),

    endDate:
      formatAuxiliaryMaterialIsoDate(
        endDate
      )
  };
}


/* =====================================================
  부재료 조회 상태 문구 표시
===================================================== */

function setAuxiliaryMaterialStatus(
  message,
  status =
    "idle"
) {
  const {
    status:
      statusElement
  } =
    getAuxiliaryMaterialElements();


  if (
    !statusElement
  ) {
    return;
  }


  statusElement.textContent =
    String(
      message ||
      ""
    );


  statusElement.dataset.status =
    status;
}


/* =====================================================
  선택 월을 시작일·종료일에 반영
===================================================== */

function applyAuxiliaryMaterialMonthRange(
  monthValue
) {
  const elements =
    getAuxiliaryMaterialElements();


  const currentMonthValue =
    getCurrentAuxiliaryMaterialMonthValue();


  const normalizedMonthValue =
    String(
      monthValue ||
      ""
    ).trim();


  /*
    미래 월이 선택되면 현재 월로 되돌린다.
  */
  const selectedMonthValue =
    normalizedMonthValue &&
    normalizedMonthValue <=
      currentMonthValue
      ? normalizedMonthValue
      : currentMonthValue;


  const range =
    getAuxiliaryMaterialMonthRange(
      selectedMonthValue
    );


  if (
    !range
  ) {
    return false;
  }


  if (
    elements.monthInput
  ) {
    elements.monthInput.value =
      selectedMonthValue;
  }


  if (
    elements.startDateInput
  ) {
    elements.startDateInput.value =
      range.startDate;
  }


  if (
    elements.endDateInput
  ) {
    elements.endDateInput.value =
      range.endDate;
  }


  /*
    현재 월에서는 다음 달 버튼을 비활성화한다.
  */
  if (
    elements.nextMonthButton
  ) {
    elements.nextMonthButton.disabled =
      selectedMonthValue >=
      currentMonthValue;
  }


  setAuxiliaryMaterialStatus(
    `${range.startDate} ~ ${range.endDate} 기간이 선택되었습니다.`,
    "idle"
  );


  return true;
}


/* =====================================================
  이전 달·다음 달 이동
===================================================== */

function moveAuxiliaryMaterialMonth(
  amount
) {
  const {
    monthInput
  } =
    getAuxiliaryMaterialElements();


  if (
    !monthInput
  ) {
    return;
  }


  const currentMonthValue =
    getCurrentAuxiliaryMaterialMonthValue();


  const baseMonthValue =
    monthInput.value ||
    currentMonthValue;


  const match =
    baseMonthValue.match(
      /^(\d{4})-(\d{2})$/
    );


  if (
    !match
  ) {
    applyAuxiliaryMaterialMonthRange(
      currentMonthValue
    );


    return;
  }


  const date =
    new Date(
      Number(
        match[1]
      ),

      Number(
        match[2]
      ) -
        1 +
        Number(
          amount ||
          0
        ),

      1
    );


  const movedMonthValue =
    (
      `${date.getFullYear()}-` +
      `${padAuxiliaryMaterialDateNumber(
        date.getMonth() +
        1
      )}`
    );


  /*
    미래 월로 넘어가는 것을 막는다.
  */
  applyAuxiliaryMaterialMonthRange(
    movedMonthValue >
      currentMonthValue
      ? currentMonthValue
      : movedMonthValue
  );
}

/* =========================================================
  부재료 모바일 모니터링 모드 판정
========================================================= */

function isAuxiliaryMaterialMobileMonitorMode() {
  return window.matchMedia(
    "(max-width: 768px)"
  ).matches;
}


/* =========================================================
  부재료 모바일 모니터링 전용 화면 준비
========================================================= */

function prepareAuxiliaryMaterialMobileMonitorOnlyLayout() {
  const elements =
    getAuxiliaryMaterialElements();


  if (
    !elements.view
  ) {
    return;
  }


  /*
    Slurry 밀도 고정값 설정 영역의
    가장 가까운 공통 부모를 찾는다.
  */
  const densityControls = [
    elements.densityEffectiveDateInput,
    elements.unitOneFixedDensityInput,
    elements.unitTwoFixedDensityInput,
    elements.fixedDensitySaveButton,
    elements.fixedDensityStatus
  ].filter(
    Boolean
  );


  if (
    densityControls.length >=
      2
  ) {
    let densityPanel =
      densityControls[0]
        .parentElement;


    while (
      densityPanel &&
      densityPanel !==
        elements.view &&
      !densityControls.every(
        control =>
          densityPanel.contains(
            control
          )
      )
    ) {
      densityPanel =
        densityPanel.parentElement;
    }


    if (
      densityPanel &&
      densityPanel !==
        elements.view
    ) {
      densityPanel.classList.add(
        "auxiliary-material-mobile-admin-panel"
      );
    }
  }


  /*
    기존 기간 평균 요약 카드는
    PC 관리화면에는 그대로 두고
    모바일에서만 숨긴다.
  */
  [
    elements.savedDays,
    elements.limestoneAverage,
    elements.limePowderAverage,
    elements.ammoniaAverage
  ]
    .filter(
      Boolean
    )
    .forEach(
      valueElement => {
        valueElement
          .closest(
            "article"
          )
          ?.classList.add(
            "auxiliary-material-mobile-desktop-summary"
          );
      }
    );
}

/* =====================================================
  부재료 날짜 제어 초기화
===================================================== */

function initializeAuxiliaryMaterialDateControls() {
  const elements =
    getAuxiliaryMaterialElements();

  if (
    !elements.view ||
    !elements.monthInput ||
    !elements.startDateInput ||
    !elements.endDateInput
  ) {
    return;
  }

  if (
    elements
      .monthInput
      .dataset
      .auxiliaryMaterialDateBound ===
        "true"
  ) {
    return;
  }

  const currentMonthValue =
    getCurrentAuxiliaryMaterialMonthValue();

  /*
    미래 월 선택 방지
  */
  elements.monthInput.max =
    currentMonthValue;

  /*
    최초 날짜 범위만 설정한다.
    서버 조회는 하지 않는다.
  */
  applyAuxiliaryMaterialMonthRange(
    elements.monthInput.value ||
    currentMonthValue
  );

  /*
    월을 직접 변경해도
    날짜 범위만 변경한다.
  */
  elements.monthInput.addEventListener(
    "change",
    () => {
      applyAuxiliaryMaterialMonthRange(
        elements.monthInput.value
      );
    }
  );

  /*
    이전 달 이동도
    날짜 범위만 변경한다.
  */
  elements
    .previousMonthButton
    ?.addEventListener(
      "click",
      () => {
        moveAuxiliaryMaterialMonth(
          -1
        );
      }
    );

  /*
    다음 달 이동도
    날짜 범위만 변경한다.
  */
  elements
    .nextMonthButton
    ?.addEventListener(
      "click",
      () => {
        moveAuxiliaryMaterialMonth(
          1
        );
      }
    );

  elements
    .monthInput
    .dataset
    .auxiliaryMaterialDateBound =
      "true";
}

/* =====================================================
  초기 실행
===================================================== */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialDateControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialDateControls();
}

/* =====================================================
  부재료 저장자료 화면 상태
===================================================== */

const auxiliaryMaterialHistoryState = {
  items: [],

  summary: {},

  fixedDensitySettings: [],

  /*
    같은 조회 범위로 부재료 메뉴를 다시 열 때
    불필요한 D1 조회를 반복하지 않기 위한 상태
  */
  loadedRangeKey: "",

  loadingRangeKey: "",

  /*
    날짜를 빠르게 이동했을 때
    이전 응답이 최신 화면을 덮지 않도록 구분
  */
  loadSequence: 0
};


function getAuxiliaryMaterialHistoryRangeKey(
  range
) {
  return (
    `${String(
      range?.startDate ||
      ""
    )}|` +
    `${String(
      range?.endDate ||
      ""
    )}`
  );
}


const AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE =
  "2026-08-10";


/* =====================================================
  부재료 Limestone 사용량 연동 숫자 확인
===================================================== */

function parseAuxiliaryMaterialLinkedLimestoneNumber(
  value
) {
  if (
    value ===
      null ||
    value ===
      undefined ||
    String(
      value
    ).trim() ===
      ""
  ) {
    return null;
  }


  const numericValue =
    Number(
      value
    );


  return Number.isFinite(
    numericValue
  )
    ? numericValue
    : null;
}


/* =====================================================
  부재료 자료 + 석회석 저장 사용량 병합

  - 2026-08-09까지: 기존 엑셀 업로드값 유지
  - 2026-08-10부터: 석회석 화면 D1 저장값 사용
===================================================== */

function mergeAuxiliaryMaterialLimestoneUsageHistory(
  materialItems,
  limestoneHistoryItems,
  options =
    {}
) {
  const sourceItems =
    Array.isArray(
      materialItems
    )
      ? materialItems
      : [];


  if (
    options.linkedResponseLoaded !==
      true
  ) {
    return sourceItems;
  }


  const mergedItems =
    sourceItems.map(
      item => {
        const recordDate =
          String(
            item?.recordDate ||
            ""
          ).trim();


        if (
          !isValidAuxiliaryMaterialIsoDate(
            recordDate
          ) ||
          recordDate <
            AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE
        ) {
          return item;
        }


        return {
          ...item,

          limestoneUsageTpd:
            null,

          limestoneUsageLinked:
            true
        };
      }
    );


  const itemIndexByDateAndUnit =
    new Map();


  mergedItems.forEach(
    (
      item,
      index
    ) => {
      const recordDate =
        String(
          item?.recordDate ||
          ""
        ).trim();


      const unitNo =
        Number(
          item?.unitNo
        );


      if (
        isValidAuxiliaryMaterialIsoDate(
          recordDate
        ) &&
        [
          1,
          2
        ].includes(
          unitNo
        )
      ) {
        itemIndexByDateAndUnit.set(
          `${recordDate}:${unitNo}`,
          index
        );
      }
    }
  );


  (
    Array.isArray(
      limestoneHistoryItems
    )
      ? limestoneHistoryItems
      : []
  ).forEach(
    historyItem => {
      const recordDate =
        String(
          historyItem?.usageDate ||
          ""
        ).trim();


      if (
        !isValidAuxiliaryMaterialIsoDate(
          recordDate
        ) ||
        recordDate <
          AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE
      ) {
        return;
      }


      [
        {
          unitNo:
            1,

          value:
            historyItem?.unitOneUsage
        },

        {
          unitNo:
            2,

          value:
            historyItem?.unitTwoUsage
        }
      ].forEach(
        unitItem => {
          const limestoneUsageTpd =
            parseAuxiliaryMaterialLinkedLimestoneNumber(
              unitItem.value
            );


          if (
            limestoneUsageTpd ===
              null
          ) {
            return;
          }


          const key =
            `${recordDate}:${unitItem.unitNo}`;


          const existingIndex =
            itemIndexByDateAndUnit.get(
              key
            );


          if (
            existingIndex !==
              undefined
          ) {
            mergedItems[
              existingIndex
            ] = {
              ...mergedItems[
                existingIndex
              ],

              limestoneUsageTpd,

              limestoneUsageLinked:
                true
            };


            return;
          }


          itemIndexByDateAndUnit.set(
            key,
            mergedItems.length
          );


          mergedItems.push({
            recordDate,

            unitNo:
              unitItem.unitNo,

            limestoneUsageTpd,

            limestoneUsageLinked:
              true,

            revision:
              0,

            remarks:
              ""
          });
        }
      );
    }
  );


  return mergedItems;
}


/* =====================================================
  석회석 화면의 기간 저장 사용량 불러오기
===================================================== */

async function loadAuxiliaryMaterialLinkedLimestoneUsage(
  range,
  headers
) {
  if (
    range.endDate <
      AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE
  ) {
    return {
      loaded:
        false,

      items: []
    };
  }


  const startDate =
    range.startDate <
      AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE
      ? AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE
      : range.startDate;


  const query =
    new URLSearchParams({
      action:
        "usage_history",

      startDate,

      endDate:
        range.endDate,

      _:
        String(
          Date.now()
        )
    });


  try {
    const response =
      await fetch(
        (
          "/api/ois-data-requests?" +
          query.toString()
        ),
        {
          method:
            "GET",

          headers,

          cache:
            "no-store"
        }
      );


    const result =
      await readAuxiliaryMaterialJsonResponse(
        response
      );


    return {
      loaded:
        true,

      items:
        Array.isArray(
          result.items
        )
          ? result.items
          : []
    };

  } catch (
    error
  ) {
    console.warn(
      "부재료 Limestone 사용량 연동 실패:",
      error
    );


    return {
      loaded:
        false,

      items: []
    };
  }
}


