/* =====================================================
  부재료 숫자 표시

  값이 없으면 "-"
===================================================== */

function formatAuxiliaryMaterialDisplayNumber(
  value,
  decimalPlaces =
    2
) {
  if (
    value ===
      null ||
    value ===
      undefined ||
    String(
      value
    ).trim() ===
      ""
  ) {
    return "-";
  }


  const numericValue =
    Number(
      value
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    return "-";
  }


  return numericValue.toLocaleString(
    "ko-KR",
    {
      minimumFractionDigits:
        decimalPlaces,

      maximumFractionDigits:
        decimalPlaces
    }
  );
}


/* =====================================================
  HTML 특수문자 변환
===================================================== */

function escapeAuxiliaryMaterialHtml(
  value
) {
  return String(
    value ??
    ""
  ).replace(
    /[&<>"']/g,
    character => {
      const entities = {
        "&":
          "&amp;",

        "<":
          "&lt;",

        ">":
          "&gt;",

        "\"":
          "&quot;",

        "'":
          "&#039;"
      };


      return entities[
        character
      ];
    }
  );
}


/* =====================================================
  부재료 수치 수정 입력값 표시
===================================================== */

function formatAuxiliaryMaterialEditInputValue(
  value,
  decimalPlaces
) {
  if (
    value ===
      null ||
    value ===
      undefined ||
    String(
      value
    ).trim() ===
      ""
  ) {
    return "";
  }


  const numericValue =
    Number(
      value
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    return "";
  }


  return numericValue.toFixed(
    decimalPlaces
  );
}


/* =====================================================
  호기별 Slurry 밀도 고정값 찾기
===================================================== */

function getAuxiliaryMaterialFixedDensitySetting(
  unitNo
) {
  return (
    Array.isArray(
      auxiliaryMaterialHistoryState
        .fixedDensitySettings
    )
      ? auxiliaryMaterialHistoryState
          .fixedDensitySettings
      : []
  ).find(
    setting => Number(
      setting?.unitNo
    ) ===
      Number(
        unitNo
      )
  ) ||
  null;
}


/* =====================================================
  해당 날짜의 고정 밀도 적용 여부
===================================================== */

function isAuxiliaryMaterialFixedDensityDate(
  recordDate,
  unitNo
) {
  const setting =
    getAuxiliaryMaterialFixedDensitySetting(
      unitNo
    );


  return Boolean(
    setting &&
    isValidAuxiliaryMaterialIsoDate(
      setting.effectiveFrom
    ) &&
    recordDate >=
      setting.effectiveFrom
  );
}


/* =====================================================
  Lime Powder 자동 계산
===================================================== */

function calculateAuxiliaryMaterialLimePowder(
  flow,
  density
) {
  const flowValue =
    Number(
      flow
    );


  const densityValue =
    Number(
      density
    );


  if (
    !Number.isFinite(
      flowValue
    ) ||
    !Number.isFinite(
      densityValue
    ) ||
    flowValue <=
      0 ||
    densityValue <=
      1000
  ) {
    return null;
  }


  return (
    flowValue *
    densityValue *
    (
      densityValue -
      1000
    ) /
    (
      1102 -
      1000
    ) *
    0.15 *
    24 /
    1000
  );
}


/* =====================================================
  부재료 일반 셀 또는 수정 입력칸 생성
===================================================== */

function renderAuxiliaryMaterialValueCell(
  item,
  field,
  unitClass,
  recordDate,
  unitNo
) {
  const isFixedDensity =
    field.key ===
      "limeSlurryDensityKgm3" &&
    isAuxiliaryMaterialFixedDensityDate(
      recordDate,
      unitNo
    );


  const isLinkedLimestoneUsage =
    field.key ===
      "limestoneUsageTpd" &&
    recordDate >=
      AUXILIARY_MATERIAL_LIMESTONE_LINK_START_DATE;


  const cellClasses = [
    field.cssClass,
    unitClass,

    isFixedDensity
      ? "is-fixed-density"
      : "",

    isLinkedLimestoneUsage
      ? "is-linked-limestone-usage"
      : ""
  ]
    .filter(
      Boolean
    )
    .join(
      " "
    );


  const cellTitle =
    isFixedDensity
      ? `${unitNo}호기 Slurry 밀도 고정값 적용 중`
      : isLinkedLimestoneUsage
        ? "석회석 화면 연동값 · 수동 수정 가능"
        : "";


  /*
    일반 표시 모드
  */
  if (
    !auxiliaryMaterialValueEditState
      .isEditing ||
    !item
  ) {
    return `
      <td
        class="${cellClasses}"
        ${cellTitle
          ? `title="${escapeAuxiliaryMaterialHtml(
              cellTitle
            )}"`
          : ""}
      >
        ${formatAuxiliaryMaterialDisplayNumber(
          item?.[
            field.key
          ],
          field.decimalPlaces
        )}
      </td>
    `;
  }


  /*
    수정 모드

    중요:
    Limestone 사용량을 포함하여
    모든 부재료 수치에 입력칸을 만든다.
  */
  const inputValue =
    formatAuxiliaryMaterialEditInputValue(
      item?.[
        field.key
      ],
      field.decimalPlaces
    );


  return `
    <td
      class="${cellClasses} is-value-edit-cell"
      ${cellTitle
        ? `title="${escapeAuxiliaryMaterialHtml(
            cellTitle
          )}"`
        : ""}
    >
      <input
        type="text"
        inputmode="decimal"
        class="auxiliary-material-value-input"

        data-record-date="${escapeAuxiliaryMaterialHtml(
          recordDate
        )}"

        data-unit-no="${unitNo}"

        data-field="${escapeAuxiliaryMaterialHtml(
          field.key
        )}"

        data-original-value="${escapeAuxiliaryMaterialHtml(
          inputValue
        )}"

        data-step="${escapeAuxiliaryMaterialHtml(
          field.step
        )}"

        value="${escapeAuxiliaryMaterialHtml(
          inputValue
        )}"

        placeholder="-"
        autocomplete="off"

        aria-label="${escapeAuxiliaryMaterialHtml(
          `${recordDate} ${unitNo}호기 ${field.label}`
        )}"
      />
    </td>
  `;
}

/* =====================================================
  부재료 항목 평균 계산
===================================================== */

function calculateAuxiliaryMaterialAverage(
  propertyName
) {
  const values =
    auxiliaryMaterialHistoryState
      .items
      .filter(
        item => {
          const value =
            item?.[
              propertyName
            ];


          return (
            value !==
              null &&
            value !==
              undefined &&
            String(
              value
            ).trim() !==
              ""
          );
        }
      )
      .map(
        item => Number(
          item?.[
            propertyName
          ]
        )
      )
      .filter(
        Number.isFinite
      );


  if (
    values.length <
      1
  ) {
    return null;
  }


  return (
    values.reduce(
      (
        total,
        value
      ) => total +
        value,
      0
    ) /
    values.length
  );
}


/* =====================================================
  실제 존재하는 날짜인지 확인
===================================================== */

function isValidAuxiliaryMaterialIsoDate(
  value
) {
  const match =
    String(
      value ||
      ""
    ).match(
      /^(\d{4})-(\d{2})-(\d{2})$/
    );


  if (
    !match
  ) {
    return false;
  }


  const year =
    Number(
      match[1]
    );


  const month =
    Number(
      match[2]
    );


  const day =
    Number(
      match[3]
    );


  const date =
    new Date(
      year,
      month -
        1,
      day
    );


  return (
    date.getFullYear() ===
      year &&
    date.getMonth() ===
      month -
        1 &&
    date.getDate() ===
      day
  );
}


/* =====================================================
  부재료 조회 기간 확인
===================================================== */

function readAuxiliaryMaterialDateRange() {
  const elements =
    getAuxiliaryMaterialElements();


  const startDate =
    String(
      elements
        .startDateInput
        ?.value ||
      ""
    ).trim();


  const endDate =
    String(
      elements
        .endDateInput
        ?.value ||
      ""
    ).trim();


  if (
    !isValidAuxiliaryMaterialIsoDate(
      startDate
    ) ||
    !isValidAuxiliaryMaterialIsoDate(
      endDate
    )
  ) {
    throw new Error(
      "부재료 조회 시작일과 종료일을 확인해 주세요."
    );
  }


  if (
    startDate >
      endDate
  ) {
    throw new Error(
      "시작일은 종료일보다 늦을 수 없습니다."
    );
  }


  const today =
    formatAuxiliaryMaterialIsoDate(
      new Date()
    );


  if (
    endDate >
      today
  ) {
    throw new Error(
      "종료일은 오늘보다 늦을 수 없습니다."
    );
  }


  const startTime =
    new Date(
      `${startDate}T00:00:00`
    ).getTime();


  const endTime =
    new Date(
      `${endDate}T00:00:00`
    ).getTime();


  const dayCount =
    Math.floor(
      (
        endTime -
        startTime
      ) /
      86400000
    ) +
    1;


  if (
    dayCount <
      1 ||
    dayCount >
      366
  ) {
    throw new Error(
      "저장자료 조회 기간은 1일 이상 366일 이하로 선택해 주세요."
    );
  }


  return {
    startDate,
    endDate,
    dayCount
  };
}


/* =====================================================
  부재료 표와 요약 표시

  한 날짜:
  - A: 일자
  - B:I: 1호기
  - J:Q: 2호기
  - R: 비고
===================================================== */

function renderAuxiliaryMaterialHistory() {
  const elements =
    getAuxiliaryMaterialElements();

  if (
    !elements.tableBody
  ) {
    return;
  }

  const table =
    elements.tableBody.closest(
      ".auxiliary-material-sheet-table"
    );

  const isExpanded =
    document.body.classList.contains(
      "is-auxiliary-material-expanded"
    );

  table?.classList.toggle(
    "is-split-layout",
    !isExpanded
  );

  table?.classList.toggle(
    "is-combined-layout",
    isExpanded
  );

  const items =
    Array.isArray(
      auxiliaryMaterialHistoryState.items
    )
      ? auxiliaryMaterialHistoryState.items
      : [];

  const rowsByDate =
    new Map();

  items.forEach(
    item => {
      const recordDate =
        String(
          item?.recordDate ||
          ""
        ).trim();

      const unitNo =
        Number(
          item?.unitNo
        );

      if (
        !isValidAuxiliaryMaterialIsoDate(
          recordDate
        ) ||
        (
          unitNo !== 1 &&
          unitNo !== 2
        )
      ) {
        return;
      }

      if (
        !rowsByDate.has(
          recordDate
        )
      ) {
        rowsByDate.set(
          recordDate,
          {
            recordDate,

            unitOne:
              null,

            unitTwo:
              null
          }
        );
      }

      const row =
        rowsByDate.get(
          recordDate
        );

      if (
        unitNo === 1
      ) {
        row.unitOne =
          item;

      } else {
        row.unitTwo =
          item;
      }
    }
  );

  const rows =
    Array.from(
      rowsByDate.values()
    ).sort(
      (
        first,
        second
      ) =>
        second.recordDate.localeCompare(
          first.recordDate
        )
    );

  /*
    화면에서 표시할 순서만 지정한다.

    엑셀 업로드·다운로드 열 순서에는
    영향을 주지 않는다.
  */
  const displayFieldKeys = [
    "soxPpm",
    "limestoneUsageTpd",
    "limestoneReceiptTon",
    "limePowderTpd",
    "limeSlurryFlowM3h",
    "limeSlurryDensityKgm3",
    "noxPpm",
    "ammoniaM3d"
  ];

  const displayFields =
    displayFieldKeys
      .map(
        fieldKey =>
          AUXILIARY_MATERIAL_EDIT_FIELDS.find(
            field =>
              field.key ===
              fieldKey
          )
      )
      .filter(
        Boolean
      );

  const splitColumns = [
    [
      "is-sox",
      "SOx",
      "ppm"
    ],

    [
      "is-limestone-usage",
      "Limestone 사용량",
      "t/d"
    ],

    [
      "is-limestone-receipt",
      "Limestone 입고량",
      "t"
    ],

    [
      "is-lime-powder",
      "Lime Powder",
      "t/d"
    ],

    [
      "is-slurry-flow",
      "Lime Slurry 유량",
      "m³/h"
    ],

    [
      "is-density",
      "Slurry 밀도",
      "kg/m³"
    ],

    [
      "is-nox",
      "NOx",
      "ppm"
    ],

    [
      "is-ammonia",
      "Ammonia 일사용량",
      "m³/d"
    ]
  ];

  function renderUnitCells(
    item,
    unitClass,
    recordDate,
    unitNo
  ) {
    return displayFields
      .map(
        field =>
          renderAuxiliaryMaterialValueCell(
            item,
            field,
            unitClass,
            recordDate,
            unitNo
          )
      )
      .join(
        ""
      );
  }

  function getCombinedRemarks(
    row
  ) {
    const unitOneRemarks =
      String(
        row.unitOne?.remarks ??
        ""
      ).trim();

    const unitTwoRemarks =
      String(
        row.unitTwo?.remarks ??
        ""
      ).trim();

    if (
      unitOneRemarks &&
      unitTwoRemarks &&
      unitOneRemarks !==
        unitTwoRemarks
    ) {
      return (
        `1호기: ${unitOneRemarks} / ` +
        `2호기: ${unitTwoRemarks}`
      );
    }

    return (
      unitOneRemarks ||
      unitTwoRemarks
    );
  }

  /*
    일반 모드에서는 기존 비고 문구를 표시하고,
    수정 모드에서는 비고 입력칸을 만든다.
  */
  function renderRemarksCell({
    recordDate,
    unitNos,
    remarks,
    hasRecord,
    ariaLabel
  }) {
    const normalizedRemarks =
      String(
        remarks ??
        ""
      ).trim();

    if (
      !auxiliaryMaterialValueEditState
        .isEditing ||
      !hasRecord
    ) {
      return `
        <td class="is-remarks">
          ${normalizedRemarks
            ? escapeAuxiliaryMaterialHtml(
                normalizedRemarks
              )
            : "-"}
        </td>
      `;
    }

    return `
      <td class="is-remarks is-remarks-edit-cell">
        <input
          type="text"
          class="auxiliary-material-remarks-input"

          data-record-date="${escapeAuxiliaryMaterialHtml(
            recordDate
          )}"

          data-unit-nos="${escapeAuxiliaryMaterialHtml(
            unitNos.join(
              ","
            )
          )}"

          data-original-value="${escapeAuxiliaryMaterialHtml(
            normalizedRemarks
          )}"

          value="${escapeAuxiliaryMaterialHtml(
            normalizedRemarks
          )}"

          maxlength="1000"
          placeholder="비고 입력"
          autocomplete="off"

          aria-label="${escapeAuxiliaryMaterialHtml(
            ariaLabel
          )}"
        />
      </td>
    `;
  }

  function renderSplitColumnHeading(
    unitClass
  ) {
    const valueHeadings =
      splitColumns
        .map(
          (
            [
              cssClass,
              label,
              unit
            ]
          ) => `
            <th class="${cssClass}">
              <span>
                ${label}
              </span>

              <small>
                ${unit}
              </small>
            </th>
          `
        )
        .join(
          ""
        );

    return `
      <tr
        class="auxiliary-material-split-column-heading ${unitClass}"
      >
        <th class="is-date">
          일자
        </th>

        ${valueHeadings}

        <th class="is-remarks">
          비고
        </th>
      </tr>
    `;
  }

  function renderSplitUnitSection(
    unitNo,
    unitClass
  ) {
    const itemKey =
      unitNo === 1
        ? "unitOne"
        : "unitTwo";

    const unitRows =
      rows
        .map(
          row => {
            const item =
              row[
                itemKey
              ];

            const remarks =
              String(
                item?.remarks ??
                ""
              ).trim();

            return `
              <tr
                class="auxiliary-material-split-data-row ${unitClass} ${auxiliaryMaterialValueEditState.isEditing
                  ? "is-value-editing"
                  : ""}"

                data-record-date="${escapeAuxiliaryMaterialHtml(
                  row.recordDate
                )}"

                data-unit-no="${unitNo}"
              >
                <td class="is-date">
                  <strong>
                    ${escapeAuxiliaryMaterialHtml(
                      row.recordDate
                    )}
                  </strong>
                </td>

                ${renderUnitCells(
                  item,
                  unitClass,
                  row.recordDate,
                  unitNo
                )}

                ${renderRemarksCell({
                  recordDate:
                    row.recordDate,

                  unitNos: [
                    unitNo
                  ],

                  remarks,

                  hasRecord:
                    Boolean(
                      item
                    ),

                  ariaLabel:
                    `${row.recordDate} ${unitNo}호기 비고`
                })}
              </tr>
            `;
          }
        )
        .join(
          ""
        );

    return `
      <tr
        class="auxiliary-material-split-unit-heading ${unitClass}"
      >
        <th colspan="${splitColumns.length + 2}">
          <span class="auxiliary-material-split-unit-title">
            <strong>
              ${unitNo}호기
            </strong>

            <span>
              날짜별 부재료 수치
            </span>
          </span>

          <span class="auxiliary-material-split-unit-count">
            ${rows.length}일 · 최신순
          </span>
        </th>
      </tr>

      ${renderSplitColumnHeading(
        unitClass
      )}

      ${unitRows}
    `;
  }

  function renderCombinedRows() {
    return rows
      .map(
        row => {
          const remarks =
            getCombinedRemarks(
              row
            );

          const unitNos = [
            ...(row.unitOne
              ? [
                  1
                ]
              : []),

            ...(row.unitTwo
              ? [
                  2
                ]
              : [])
          ];

          return `
            <tr
              class="${auxiliaryMaterialValueEditState.isEditing
                ? "is-value-editing"
                : ""}"

              data-record-date="${escapeAuxiliaryMaterialHtml(
                row.recordDate
              )}"
            >
              <td class="is-date">
                <strong>
                  ${escapeAuxiliaryMaterialHtml(
                    row.recordDate
                  )}
                </strong>
              </td>

              ${renderUnitCells(
                row.unitOne,
                "is-unit-one",
                row.recordDate,
                1
              )}

              ${renderUnitCells(
                row.unitTwo,
                "is-unit-two",
                row.recordDate,
                2
              )}

              ${renderRemarksCell({
                recordDate:
                  row.recordDate,

                unitNos,

                remarks,

                hasRecord:
                  Boolean(
                    row.unitOne ||
                    row.unitTwo
                  ),

                ariaLabel:
                  `${row.recordDate} 공통 비고`
              })}
            </tr>
          `;
        }
      )
      .join(
        ""
      );
  }

  elements.tableBody.innerHTML =
    rows.length < 1
      ? ""
      : isExpanded
        ? renderCombinedRows()
        : (
            renderSplitUnitSection(
              1,
              "is-unit-one"
            ) +
            renderSplitUnitSection(
              2,
              "is-unit-two"
            )
          );

  if (
    elements.emptyState
  ) {
    elements.emptyState.hidden =
      rows.length > 0;
  }

  if (
    elements.rowCount
  ) {
    elements.rowCount.textContent =
      `${rows.length}건`;
  }

  if (
    elements.savedDays
  ) {
    elements.savedDays.textContent =
      `${rows.length}일`;
  }
}

