function renderAuxiliaryMaterialMobileMonitor() {
  const elements =
    getAuxiliaryMaterialElements();


  if (
    !elements.tableBody
  ) {
    return;
  }


  const tableWrap =
    elements.tableBody.closest(
      ".auxiliary-material-table-wrap"
    );


  if (
    !tableWrap
  ) {
    return;
  }


  let monitor =
    document.getElementById(
      "auxiliaryMaterialMobileMonitor"
    );


  if (
    !monitor
  ) {
    monitor =
      document.createElement(
        "div"
      );


    monitor.id =
      "auxiliaryMaterialMobileMonitor";


    monitor.className =
      "auxiliary-material-mobile-monitor";


    tableWrap.insertAdjacentElement(
      "beforebegin",
      monitor
    );
  }


  const rowsByDate =
    new Map();


  const items =
    Array.isArray(
      auxiliaryMaterialHistoryState.items
    )
      ? auxiliaryMaterialHistoryState.items
      : [];


  items.forEach(
    item => {
      const recordDate =
        String(
          item?.recordDate ||
          ""
        ).trim();


      const unitNo =
        Number(
          item?.unitNo
        );


      if (
        !isValidAuxiliaryMaterialIsoDate(
          recordDate
        ) ||
        ![
          1,
          2
        ].includes(
          unitNo
        )
      ) {
        return;
      }


      if (
        !rowsByDate.has(
          recordDate
        )
      ) {
        rowsByDate.set(
          recordDate,
          {
            recordDate,
            unitOne:
              null,
            unitTwo:
              null
          }
        );
      }


      const row =
        rowsByDate.get(
          recordDate
        );


      if (
        unitNo ===
          1
      ) {
        row.unitOne =
          item;

      } else {
        row.unitTwo =
          item;
      }
    }
  );


  const rows =
    Array.from(
      rowsByDate.values()
    ).sort(
      (
        first,
        second
      ) =>
        second.recordDate.localeCompare(
          first.recordDate
        )
    );


  if (
    rows.length <
      1
  ) {
    monitor.innerHTML = `
      <div class="auxiliary-material-mobile-empty">
        선택한 월의 저장된 부재료 자료가 없습니다.
      </div>
    `;


    return;
  }


  const metrics = [
    {
      key:
        "limestoneUsageTpd",

      label:
        "Limestone",

      unit:
        "t/d",

      decimalPlaces:
        2,

      cssClass:
        "is-limestone-usage"
    },

    {
      key:
        "limePowderTpd",

      label:
        "Lime Powder",

      unit:
        "t/d",

      decimalPlaces:
        2,

      cssClass:
        "is-lime-powder"
    },

    {
      key:
        "ammoniaM3d",

      label:
        "Ammonia",

      unit:
        "m³/d",

      decimalPlaces:
        3,

      cssClass:
        "is-ammonia"
    },

    {
      key:
        "soxPpm",

      label:
        "SOx",

      unit:
        "ppm",

      decimalPlaces:
        2,

      cssClass:
        "is-sox"
    },

    {
      key:
        "noxPpm",

      label:
        "NOx",

      unit:
        "ppm",

      decimalPlaces:
        2,

      cssClass:
        "is-nox"
    }
  ];


  const weekdayNames = [
    "일",
    "월",
    "화",
    "수",
    "목",
    "금",
    "토"
  ];


  function formatMobileDate(
    recordDate
  ) {
    const date =
      new Date(
        `${recordDate}T00:00:00`
      );


    if (
      Number.isNaN(
        date.getTime()
      )
    ) {
      return {
        title:
          recordDate,

        weekday:
          ""
      };
    }


    return {
      title:
        `${date.getMonth() + 1}월 ${date.getDate()}일`,

      weekday:
        `${weekdayNames[date.getDay()]}요일`
    };
  }


  function formatMobileValue(
    item,
    metric
  ) {
    return formatAuxiliaryMaterialDisplayNumber(
      item?.[
        metric.key
      ],
      metric.decimalPlaces
    );
  }


  function getRemarks(
    row
  ) {
    const unitOneRemarks =
      String(
        row.unitOne?.remarks ??
        ""
      ).trim();


    const unitTwoRemarks =
      String(
        row.unitTwo?.remarks ??
        ""
      ).trim();


    if (
      unitOneRemarks &&
      unitTwoRemarks &&
      unitOneRemarks !==
        unitTwoRemarks
    ) {
      return (
        `1호기: ${unitOneRemarks} / ` +
        `2호기: ${unitTwoRemarks}`
      );
    }


    return (
      unitOneRemarks ||
      unitTwoRemarks
    );
  }


  monitor.innerHTML =
    rows
      .map(
        row => {
          const dateLabel =
            formatMobileDate(
              row.recordDate
            );


          const remarks =
            getRemarks(
              row
            );


          const metricRows =
            metrics
              .map(
                metric => `
                  <div
                    class="auxiliary-material-mobile-metric-row ${metric.cssClass}"
                  >
                    <div class="auxiliary-material-mobile-metric-label">
                      <strong>
                        ${escapeAuxiliaryMaterialHtml(
                          metric.label
                        )}
                      </strong>

                      <small>
                        ${escapeAuxiliaryMaterialHtml(
                          metric.unit
                        )}
                      </small>
                    </div>

                    <strong class="auxiliary-material-mobile-value is-unit-one">
                      ${escapeAuxiliaryMaterialHtml(
                        formatMobileValue(
                          row.unitOne,
                          metric
                        )
                      )}
                    </strong>

                    <strong class="auxiliary-material-mobile-value is-unit-two">
                      ${escapeAuxiliaryMaterialHtml(
                        formatMobileValue(
                          row.unitTwo,
                          metric
                        )
                      )}
                    </strong>
                  </div>
                `
              )
              .join(
                ""
              );


          return `
            <article
              class="auxiliary-material-mobile-day-card"
              data-record-date="${escapeAuxiliaryMaterialHtml(
                row.recordDate
              )}"
            >
              <header class="auxiliary-material-mobile-day-card__header">
                <div>
                  <strong>
                    ${escapeAuxiliaryMaterialHtml(
                      dateLabel.title
                    )}
                  </strong>

                  <span>
                    ${escapeAuxiliaryMaterialHtml(
                      dateLabel.weekday
                    )}
                  </span>
                </div>

                <span class="auxiliary-material-mobile-saved-badge">
                  D1 저장
                </span>
              </header>

              <div class="auxiliary-material-mobile-metric-head">
                <span>
                  항목
                </span>

                <strong>
                  1호기
                </strong>

                <strong>
                  2호기
                </strong>
              </div>

              <div class="auxiliary-material-mobile-metric-list">
                ${metricRows}
              </div>

              ${remarks
                ? `
                    <div class="auxiliary-material-mobile-remarks">
                      <span>
                        비고
                      </span>

                      <strong>
                        ${escapeAuxiliaryMaterialHtml(
                          remarks
                        )}
                      </strong>
                    </div>
                  `
                : ""}
            </article>
          `;
        }
      )
      .join(
        ""
      );
}

/* =========================================================
  Slurry 밀도 고정값 화면 표시
========================================================= */

function setAuxiliaryMaterialFixedDensityStatus(
  message,
  status =
    "idle"
) {
  const {
    fixedDensityStatus
  } =
    getAuxiliaryMaterialElements();


  if (
    !fixedDensityStatus
  ) {
    return;
  }


  fixedDensityStatus.textContent =
    String(
      message ||
      ""
    );


  fixedDensityStatus.dataset.status =
    String(
      status ||
      "idle"
    );
}


function getLatestAuxiliaryMaterialDensity(
  unitNo
) {
  const item =
    (
      Array.isArray(
        auxiliaryMaterialHistoryState
          .items
      )
        ? auxiliaryMaterialHistoryState
            .items
        : []
    )
      .filter(
        candidate =>
          Number(
            candidate?.unitNo
          ) ===
            Number(
              unitNo
            ) &&
          Number.isFinite(
            Number(
              candidate?.limeSlurryDensityKgm3
            )
          )
      )
      .sort(
        (
          first,
          second
        ) =>
          String(
            second?.recordDate ||
            ""
          ).localeCompare(
            String(
              first?.recordDate ||
              ""
            )
          )
      )[0];


  return item
    ? Number(
        item.limeSlurryDensityKgm3
      )
    : null;
}


function renderAuxiliaryMaterialFixedDensitySettings() {
  const elements =
    getAuxiliaryMaterialElements();


  const today =
    formatAuxiliaryMaterialIsoDate(
      new Date()
    );


  const settings =
    Array.isArray(
      auxiliaryMaterialHistoryState
        .fixedDensitySettings
    )
      ? auxiliaryMaterialHistoryState
          .fixedDensitySettings
      : [];


  const unitOneSetting =
    getAuxiliaryMaterialFixedDensitySetting(
      1
    );


  const unitTwoSetting =
    getAuxiliaryMaterialFixedDensitySetting(
      2
    );


  const effectiveFrom =
    unitOneSetting?.effectiveFrom ||
    unitTwoSetting?.effectiveFrom ||
    today;


  if (
    elements.densityEffectiveDateInput
  ) {
    elements.densityEffectiveDateInput.min =
      "2026-08-10";

    elements.densityEffectiveDateInput.max =
      today;


    if (
      document.activeElement !==
        elements.densityEffectiveDateInput
    ) {
      elements.densityEffectiveDateInput.value =
        effectiveFrom;
    }
  }


  [
    {
      input:
        elements.unitOneFixedDensityInput,

      setting:
        unitOneSetting,

      fallback:
        getLatestAuxiliaryMaterialDensity(
          1
        )
    },

    {
      input:
        elements.unitTwoFixedDensityInput,

      setting:
        unitTwoSetting,

      fallback:
        getLatestAuxiliaryMaterialDensity(
          2
        )
    }
  ].forEach(
    definition => {
      if (
        !definition.input ||
        document.activeElement ===
          definition.input
      ) {
        return;
      }


      const value =
        definition.setting?.densityKgm3 ??
        definition.fallback;


      definition.input.value =
        Number.isFinite(
          Number(
            value
          )
        )
          ? Number(
              value
            ).toFixed(
              1
            )
          : "";
    }
  );


  if (
    settings.length >=
      2
  ) {
    setAuxiliaryMaterialFixedDensityStatus(
      (
        `${effectiveFrom}부터 고정 · ` +
        `1호기 ${Number(unitOneSetting.densityKgm3).toFixed(1)} / ` +
        `2호기 ${Number(unitTwoSetting.densityKgm3).toFixed(1)} kg/m³`
      ),
      "complete"
    );

  } else {
    setAuxiliaryMaterialFixedDensityStatus(
      "고정값 미설정 · 최근 저장 밀도를 입력칸에 표시했습니다.",
      "idle"
    );
  }
}

/* =========================================================
  부재료 수치 수정값 읽기
========================================================= */

function parseAuxiliaryMaterialEditNumber(
  value,
  field,
  label
) {
  const normalizedValue =
    String(
      value ??
      ""
    )
      .trim()
      .replace(
        /,/g,
        ""
      );


  if (
    !normalizedValue ||
    normalizedValue ===
      "-" ||
    normalizedValue ===
      "—"
  ) {
    return null;
  }


  const numericValue =
    Number(
      normalizedValue
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    throw new Error(
      `${label} 값을 숫자로 입력해 주세요.`
    );
  }


  const minimum =
    Number.isFinite(
      Number(
        field.minimum
      )
    )
      ? Number(
          field.minimum
        )
      : 0;


  const maximum =
    Number.isFinite(
      Number(
        field.maximum
      )
    )
      ? Number(
          field.maximum
        )
      : 1000000;


  if (
    (
      field.minimumExclusive ===
        true
        ? numericValue <=
          minimum
        : numericValue <
          minimum
    ) ||
    numericValue >
      maximum
  ) {
    throw new Error(
      `${label} 값의 범위를 확인해 주세요.`
    );
  }


  return numericValue;
}


function areAuxiliaryMaterialEditNumbersEqual(
  first,
  second
) {
  if (
    first ===
      null ||
    second ===
      null
  ) {
    return first ===
      second;
  }


  return Math.abs(
    first -
    second
  ) <
    0.0000001;
}

function collectAuxiliaryMaterialChangedRecords() {
  const grouped = new Map();

  const historyItems =
    Array.isArray(
      auxiliaryMaterialHistoryState.items
    )
      ? auxiliaryMaterialHistoryState.items
      : [];

  function getOriginalItem(
    recordDate,
    unitNo
  ) {
    return (
      historyItems.find(
        item =>
          item.recordDate === recordDate &&
          Number(item.unitNo) === Number(unitNo)
      ) ||
      null
    );
  }

  /*
    숫자 또는 비고 중 하나만 변경해도
    서버에는 해당 날짜·호기의 전체 값을 전달한다.
  */
  function ensureGroup(
    recordDate,
    unitNo
  ) {
    const key =
      `${recordDate}:${unitNo}`;

    if (
      grouped.has(
        key
      )
    ) {
      return grouped.get(
        key
      );
    }

    const originalItem =
      getOriginalItem(
        recordDate,
        unitNo
      );

    if (
      !originalItem
    ) {
      return null;
    }

    const originalRemarks =
      String(
        originalItem.remarks ??
        ""
      ).trim();

    const group = {
      recordDate,
      unitNo,

      revision:
        Number(
          originalItem.revision
        ) ||
        0,

      values:
        Object.fromEntries(
          AUXILIARY_MATERIAL_EDIT_FIELDS.map(
            field => [
              field.key,

              originalItem[
                field.key
              ] ??
              null
            ]
          )
        ),

      remarks:
        originalRemarks,

      originalRemarks,

      changed:
        false
    };

    grouped.set(
      key,
      group
    );

    return group;
  }

  /*
    기존 숫자 입력값 수집
  */
  document
    .querySelectorAll(
      "#auxiliaryMaterialTableBody .auxiliary-material-value-input"
    )
    .forEach(
      input => {
        const recordDate =
          String(
            input.dataset.recordDate ||
            ""
          ).trim();

        const unitNo =
          Number(
            input.dataset.unitNo
          );

        const fieldKey =
          String(
            input.dataset.field ||
            ""
          );

        const field =
          AUXILIARY_MATERIAL_EDIT_FIELDS.find(
            definition =>
              definition.key === fieldKey
          );

        if (
          !field ||
          !isValidAuxiliaryMaterialIsoDate(
            recordDate
          ) ||
          ![
            1,
            2
          ].includes(
            unitNo
          )
        ) {
          return;
        }

        const label =
          `${recordDate} ${unitNo}호기 ${field.label}`;

        const value =
          parseAuxiliaryMaterialEditNumber(
            input.value,
            field,
            label
          );

        const originalValue =
          parseAuxiliaryMaterialEditNumber(
            input.dataset.originalValue,
            field,
            label
          );

        const group =
          ensureGroup(
            recordDate,
            unitNo
          );

        if (
          !group
        ) {
          return;
        }

        group.values[
          fieldKey
        ] =
          value;

        if (
          !areAuxiliaryMaterialEditNumbersEqual(
            value,
            originalValue
          )
        ) {
          group.changed =
            true;
        }
      }
    );

  /*
    비고 입력값 수집

    축소보기:
    - 해당 호기만 수정

    크게보기:
    - 해당 날짜의 1·2호기에 같은 비고 적용
  */
  document
    .querySelectorAll(
      "#auxiliaryMaterialTableBody .auxiliary-material-remarks-input"
    )
    .forEach(
      input => {
        const recordDate =
          String(
            input.dataset.recordDate ||
            ""
          ).trim();

        const unitNos =
          Array.from(
            new Set(
              String(
                input.dataset.unitNos ||
                ""
              )
                .split(
                  ","
                )
                .map(
                  value =>
                    Number(
                      value
                    )
                )
                .filter(
                  unitNo =>
                    [
                      1,
                      2
                    ].includes(
                      unitNo
                    )
                )
            )
          );

        if (
          !isValidAuxiliaryMaterialIsoDate(
            recordDate
          ) ||
          unitNos.length < 1
        ) {
          return;
        }

        const remarks =
          String(
            input.value ??
            ""
          ).trim();

        const originalDisplayValue =
          String(
            input.dataset.originalValue ??
            ""
          ).trim();

        if (
          remarks.length > 1000
        ) {
          throw new Error(
            `${recordDate} 비고는 1,000자 이하로 입력해 주세요.`
          );
        }

        /*
          크게보기에서 1·2호기 비고가 서로 다르면
          화면에는 합쳐진 문구가 표시된다.

          사용자가 내용을 바꾸지 않았다면
          각 호기의 기존 비고를 그대로 보호한다.
        */
        if (
          remarks ===
          originalDisplayValue
        ) {
          return;
        }

        unitNos.forEach(
          unitNo => {
            const group =
              ensureGroup(
                recordDate,
                unitNo
              );

            if (
              !group
            ) {
              return;
            }

            group.remarks =
              remarks;

            if (
              remarks !==
              group.originalRemarks
            ) {
              group.changed =
                true;
            }
          }
        );
      }
    );

  return Array.from(
    grouped.values()
  )
    .filter(
      item =>
        item.changed === true
    )
    .map(
      item => {
        const {
          originalRemarks,
          changed,
          ...record
        } = item;

        return record;
      }
    );
}

/* =========================================================
  부재료 수치 수정 모드
========================================================= */

function updateAuxiliaryMaterialValueEditButtons() {
  const elements =
    getAuxiliaryMaterialElements();


  elements.view?.classList.toggle(
    "is-value-editing",
    auxiliaryMaterialValueEditState
      .isEditing
  );


  if (
    elements.editValuesButton
  ) {
    elements.editValuesButton.disabled =
      auxiliaryMaterialValueEditState
        .isSaving;

    elements.editValuesButton.textContent =
      auxiliaryMaterialValueEditState
        .isSaving
        ? "저장 중..."
        : auxiliaryMaterialValueEditState
            .isEditing
          ? "수정 저장"
          : "수치 수정";

    elements.editValuesButton.setAttribute(
      "aria-pressed",
      String(
        auxiliaryMaterialValueEditState
          .isEditing
      )
    );
  }


  if (
    elements.cancelEditButton
  ) {
    elements.cancelEditButton.hidden =
      !auxiliaryMaterialValueEditState
        .isEditing;

    elements.cancelEditButton.disabled =
      auxiliaryMaterialValueEditState
        .isSaving;
  }
}


function setAuxiliaryMaterialValueEditMode(
  isEditing
) {
  const nextState =
    Boolean(
      isEditing
    );


  /*
    모바일 부재료 화면은 모니터링 전용이다.
    수정 모드 진입 자체를 막는다.
  */
  if (
    nextState &&
    isAuxiliaryMaterialMobileMonitorMode()
  ) {
    auxiliaryMaterialValueEditState.isEditing =
      false;

    auxiliaryMaterialValueEditState.isSaving =
      false;


    updateAuxiliaryMaterialValueEditButtons();


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        "모바일에서는 저장된 부재료 결과만 확인할 수 있습니다."
      );
    }


    return;
  }


  if (
    nextState &&
    auxiliaryMaterialHistoryState
      .items.length <
      1
  ) {
    const message =
      "수정할 부재료 저장자료가 없습니다.";


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


    return;
  }


  auxiliaryMaterialValueEditState.isEditing =
    nextState;

  auxiliaryMaterialValueEditState.isSaving =
    false;


  updateAuxiliaryMaterialValueEditButtons();

  renderAuxiliaryMaterialHistory();


  if (
    nextState
  ) {
    window.requestAnimationFrame(
      () => {
        document
          .querySelector(
            "#auxiliaryMaterialTableBody .auxiliary-material-value-input"
          )
          ?.focus();
      }
    );
  }
}


async function saveAuxiliaryMaterialEditedValues() {
  let items;


  try {
    items =
      collectAuxiliaryMaterialChangedRecords();

  } catch (
    error
  ) {
    const message =
      error instanceof Error
        ? error.message
        : "부재료 수정값을 확인해 주세요.";


    setAuxiliaryMaterialStatus(
      message,
      "error"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


    return;
  }


  if (
    items.length <
      1
  ) {
    const message =
      "변경된 부재료 수치가 없습니다.";


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


    return;
  }


  auxiliaryMaterialValueEditState.isSaving =
    true;


  updateAuxiliaryMaterialValueEditButtons();


  try {
    const headers = {
      ...(
        typeof getShiftLogAuthHeaders ===
          "function"
          ? getShiftLogAuthHeaders()
          : {}
      ),

      "Content-Type":
        "application/json",

      Accept:
        "application/json"
    };


    const response =
      await fetch(
        "/api/ois-data-requests",
        {
          method:
            "POST",

          headers,

          body:
            JSON.stringify({
              action:
                "update_auxiliary_material_rows",

              items
            })
        }
      );


    const result =
      await readAuxiliaryMaterialJsonResponse(
        response
      );


    auxiliaryMaterialValueEditState.isEditing =
      false;


    await loadAuxiliaryMaterialHistory({
      silent:
        true
    });


    const message =
      result.message ||
      `${items.length}건의 부재료 수치를 수정했습니다.`;


    setAuxiliaryMaterialStatus(
      message,
      "complete"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }

  } catch (
    error
  ) {
    const message =
      error instanceof Error
        ? error.message
        : "부재료 수치를 저장하지 못했습니다.";


    setAuxiliaryMaterialStatus(
      message,
      "error"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


  } finally {
    auxiliaryMaterialValueEditState.isSaving =
      false;


    updateAuxiliaryMaterialValueEditButtons();
  }
}

/* =========================================================
  유량·밀도 수정 시 Lime Powder 자동 계산

  사용자가 Powder 칸을 직접 수정한 경우에는 그 값을 유지한다.
========================================================= */

function handleAuxiliaryMaterialValueInput(
  event
) {
  const input =
    event.target instanceof
      HTMLInputElement &&
    event.target.classList.contains(
      "auxiliary-material-value-input"
    )
      ? event.target
      : null;


  if (
    !input
  ) {
    return;
  }


  const fieldKey =
    String(
      input.dataset
        .field ||
      ""
    );


  if (
    fieldKey ===
      "limePowderTpd"
  ) {
    input.dataset.userEdited =
      "true";


    return;
  }


  if (
    fieldKey !==
      "limeSlurryFlowM3h" &&
    fieldKey !==
      "limeSlurryDensityKgm3"
  ) {
    return;
  }


  const tableBody =
    input.closest(
      "#auxiliaryMaterialTableBody"
    );


  if (
    !tableBody
  ) {
    return;
  }


  const inputs =
    [
      ...tableBody.querySelectorAll(
        ".auxiliary-material-value-input"
      )
    ].filter(
      candidate =>
        candidate.dataset.recordDate ===
          input.dataset.recordDate &&
        candidate.dataset.unitNo ===
          input.dataset.unitNo
    );


  const getInput =
    targetField =>
      inputs.find(
        candidate =>
          candidate.dataset.field ===
            targetField
      ) ||
      null;


  const flowInput =
    getInput(
      "limeSlurryFlowM3h"
    );


  const densityInput =
    getInput(
      "limeSlurryDensityKgm3"
    );


  const powderInput =
    getInput(
      "limePowderTpd"
    );


  if (
    !flowInput ||
    !densityInput ||
    !powderInput ||
    powderInput.dataset
      .userEdited ===
      "true"
  ) {
    return;
  }


  const calculatedValue =
    calculateAuxiliaryMaterialLimePowder(
      String(
        flowInput.value
      ).replace(
        /,/g,
        ""
      ),

      String(
        densityInput.value
      ).replace(
        /,/g,
        ""
      )
    );


  powderInput.value =
    calculatedValue ===
      null
      ? ""
      : calculatedValue.toFixed(
          2
        );
}

/* =========================================================
  Slurry 밀도 고정값 D1 저장
========================================================= */

async function saveAuxiliaryMaterialFixedDensity() {
  const elements =
    getAuxiliaryMaterialElements();


  const effectiveFrom =
    String(
      elements.densityEffectiveDateInput
        ?.value ||
      ""
    ).trim();


  const densityField =
    AUXILIARY_MATERIAL_EDIT_FIELDS.find(
      field =>
        field.key ===
          "limeSlurryDensityKgm3"
    );


  let unitOneDensity;
  let unitTwoDensity;


  try {
    if (
      !isValidAuxiliaryMaterialIsoDate(
        effectiveFrom
      ) ||
      effectiveFrom <
        "2026-08-10"
    ) {
      throw new Error(
        "Slurry 밀도 적용 시작일을 확인해 주세요."
      );
    }


    unitOneDensity =
      parseAuxiliaryMaterialEditNumber(
        elements.unitOneFixedDensityInput
          ?.value,
        densityField,
        "1호기 Slurry 밀도"
      );


    unitTwoDensity =
      parseAuxiliaryMaterialEditNumber(
        elements.unitTwoFixedDensityInput
          ?.value,
        densityField,
        "2호기 Slurry 밀도"
      );


    if (
      unitOneDensity ===
        null ||
      unitTwoDensity ===
        null
    ) {
      throw new Error(
        "1호기와 2호기 Slurry 밀도를 모두 입력해 주세요."
      );
    }

  } catch (
    error
  ) {
    const message =
      error instanceof Error
        ? error.message
        : "Slurry 밀도 고정값을 확인해 주세요.";


    setAuxiliaryMaterialFixedDensityStatus(
      message,
      "error"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


    return;
  }


  if (
    elements.fixedDensitySaveButton
  ) {
    elements.fixedDensitySaveButton.disabled =
      true;

    elements.fixedDensitySaveButton.textContent =
      "저장 중...";
  }


  setAuxiliaryMaterialFixedDensityStatus(
    "Slurry 밀도 고정값을 저장하고 있습니다.",
    "loading"
  );


  try {
    const headers = {
      ...(
        typeof getShiftLogAuthHeaders ===
          "function"
          ? getShiftLogAuthHeaders()
          : {}
      ),

      "Content-Type":
        "application/json",

      Accept:
        "application/json"
    };


    const response =
      await fetch(
        "/api/ois-data-requests",
        {
          method:
            "POST",

          headers,

          body:
            JSON.stringify({
              action:
                "save_auxiliary_material_density_settings",

              effectiveFrom,

              unitOneDensityKgm3:
                unitOneDensity,

              unitTwoDensityKgm3:
                unitTwoDensity
            })
        }
      );


    const result =
      await readAuxiliaryMaterialJsonResponse(
        response
      );


    auxiliaryMaterialHistoryState.fixedDensitySettings =
      Array.isArray(
        result.fixedDensitySettings
      )
        ? result.fixedDensitySettings
        : [];


    await loadAuxiliaryMaterialHistory({
      silent:
        true
    });


    const message =
      result.message ||
      `${effectiveFrom}부터 Slurry 밀도 고정값을 저장했습니다.`;


    setAuxiliaryMaterialFixedDensityStatus(
      message,
      "complete"
    );


    setAuxiliaryMaterialStatus(
      message,
      "complete"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }

  } catch (
    error
  ) {
    const message =
      error instanceof Error
        ? error.message
        : "Slurry 밀도 고정값을 저장하지 못했습니다.";


    setAuxiliaryMaterialFixedDensityStatus(
      message,
      "error"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }


  } finally {
    if (
      elements.fixedDensitySaveButton
    ) {
      elements.fixedDensitySaveButton.disabled =
        false;

      elements.fixedDensitySaveButton.textContent =
        "고정값 저장";
    }
  }
}

/* =========================================================
  부재료 수치 수정 · 밀도 고정 이벤트 연결
========================================================= */

function initializeAuxiliaryMaterialValueEditControls() {
  const elements =
    getAuxiliaryMaterialElements();


  if (
    !elements.view ||
    elements.view.dataset
      .auxiliaryMaterialValueEditBound ===
      "true"
  ) {
    return;
  }


  prepareAuxiliaryMaterialMobileMonitorOnlyLayout();


  elements.editValuesButton?.addEventListener(
    "click",
    () => {
      if (
        isAuxiliaryMaterialMobileMonitorMode()
      ) {
        if (
          typeof showToast ===
            "function"
        ) {
          showToast(
            "모바일 부재료 화면은 모니터링 전용입니다."
          );
        }


        return;
      }


      if (
        auxiliaryMaterialValueEditState
          .isEditing
      ) {
        saveAuxiliaryMaterialEditedValues();

      } else {
        setAuxiliaryMaterialValueEditMode(
          true
        );
      }
    }
  );


  elements.cancelEditButton?.addEventListener(
    "click",
    () => {
      setAuxiliaryMaterialValueEditMode(
        false
      );
    }
  );


  elements.fixedDensitySaveButton?.addEventListener(
    "click",
    () => {
      if (
        isAuxiliaryMaterialMobileMonitorMode()
      ) {
        if (
          typeof showToast ===
            "function"
        ) {
          showToast(
            "모바일 부재료 화면은 모니터링 전용입니다."
          );
        }


        return;
      }


      saveAuxiliaryMaterialFixedDensity();
    }
  );


  elements.tableBody?.addEventListener(
    "input",
    event => {
      if (
        isAuxiliaryMaterialMobileMonitorMode()
      ) {
        return;
      }


      handleAuxiliaryMaterialValueInput(
        event
      );
    }
  );


  document.addEventListener(
    "keydown",
    event => {
      if (
        isAuxiliaryMaterialMobileMonitorMode()
      ) {
        return;
      }


      if (
        event.key ===
          "Escape" &&
        auxiliaryMaterialValueEditState
          .isEditing &&
        !auxiliaryMaterialValueEditState
          .isSaving &&
        !document.body.classList.contains(
          "is-auxiliary-material-expanded"
        )
      ) {
        setAuxiliaryMaterialValueEditMode(
          false
        );
      }
    }
  );


  elements.view.dataset
    .auxiliaryMaterialValueEditBound =
    "true";


  if (
    isAuxiliaryMaterialMobileMonitorMode()
  ) {
    auxiliaryMaterialValueEditState.isEditing =
      false;

    auxiliaryMaterialValueEditState.isSaving =
      false;
  }


  updateAuxiliaryMaterialValueEditButtons();

  renderAuxiliaryMaterialFixedDensitySettings();
}

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialValueEditControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialValueEditControls();
}

/* =========================================================
  부재료 평균 - 1호기 · 2호기 · 통합 표시
========================================================= */

(function installAuxiliaryMaterialUnitAverageSummary() {

  function getValidAverageValues(
    propertyName,
    unitNo = null
  ) {
    const normalizedUnitNo =
      Number(unitNo);

    const shouldFilterByUnit =
      Number.isInteger(
        normalizedUnitNo
      ) &&
      normalizedUnitNo > 0;

    return (
      Array.isArray(
        auxiliaryMaterialHistoryState
          ?.items
      )
        ? auxiliaryMaterialHistoryState
            .items
        : []
    )
      .filter(item => {
        if (
          shouldFilterByUnit &&
          Number(item?.unitNo) !==
            normalizedUnitNo
        ) {
          return false;
        }

        const value =
          item?.[propertyName];

        return (
          value !== null &&
          value !== undefined &&
          String(value).trim() !== "" &&
          Number.isFinite(
            Number(value)
          )
        );
      })
      .map(item =>
        Number(
          item?.[propertyName]
        )
      );
  }


  function calculateUnitAverage(
    propertyName,
    unitNo = null
  ) {
    const values =
      getValidAverageValues(
        propertyName,
        unitNo
      );

    if (values.length < 1) {
      return null;
    }

    return (
      values.reduce(
        (total, value) =>
          total + value,
        0
      ) /
      values.length
    );
  }


  function upgradeAverageCard({
    combinedId,
    unitOneId,
    unitTwoId,
    title,
    unit
  }) {
    const combinedElement =
      document.getElementById(
        combinedId
      );

    const card =
      combinedElement?.closest(
        "article"
      );

    if (
      !card ||
      card.dataset
        .unitAverageReady ===
        "true"
    ) {
      return;
    }

    card.classList.add(
      "auxiliary-material-average-card"
    );

    card.innerHTML = `
      <div class="auxiliary-material-average-title">
        <span>${title} 평균</span>
        <small>${unit}</small>
      </div>

      <div class="auxiliary-material-average-values">
        <div class="auxiliary-material-average-value">
          <span>1호기</span>
          <strong id="${unitOneId}">-</strong>
        </div>

        <div class="auxiliary-material-average-value">
          <span>2호기</span>
          <strong id="${unitTwoId}">-</strong>
        </div>

        <div class="auxiliary-material-average-value is-combined">
          <span>통합</span>
          <strong id="${combinedId}">-</strong>
        </div>
      </div>
    `;

    card.dataset.unitAverageReady =
      "true";
  }


  function upgradeAverageSummaryMarkup() {
    const savedDaysElement =
      document.getElementById(
        "auxiliaryMaterialSavedDays"
      );

    savedDaysElement
      ?.closest("article")
      ?.classList.add(
        "auxiliary-material-saved-card"
      );

    [
      {
        combinedId:
          "auxiliaryMaterialLimestoneAverage",

        unitOneId:
          "auxiliaryMaterialLimestoneUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialLimestoneUnitTwoAverage",

        title:
          "Limestone",

        unit:
          "t/d"
      },

      {
        combinedId:
          "auxiliaryMaterialLimePowderAverage",

        unitOneId:
          "auxiliaryMaterialLimePowderUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialLimePowderUnitTwoAverage",

        title:
          "Lime Powder",

        unit:
          "t/d"
      },

      {
        combinedId:
          "auxiliaryMaterialAmmoniaAverage",

        unitOneId:
          "auxiliaryMaterialAmmoniaUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialAmmoniaUnitTwoAverage",

        title:
          "Ammonia",

        unit:
          "m³/d"
      }
    ].forEach(
      upgradeAverageCard
    );
  }


  function setAverageText(
    elementId,
    value,
    decimalPlaces
  ) {
    const element =
      document.getElementById(
        elementId
      );

    if (!element) return;

    element.textContent =
      formatAuxiliaryMaterialDisplayNumber(
        value,
        decimalPlaces
      );
  }


  function renderUnitAverageSummary() {
    [
      {
        propertyName:
          "limestoneUsageTpd",

        decimalPlaces:
          2,

        combinedId:
          "auxiliaryMaterialLimestoneAverage",

        unitOneId:
          "auxiliaryMaterialLimestoneUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialLimestoneUnitTwoAverage"
      },

      {
        propertyName:
          "limePowderTpd",

        decimalPlaces:
          2,

        combinedId:
          "auxiliaryMaterialLimePowderAverage",

        unitOneId:
          "auxiliaryMaterialLimePowderUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialLimePowderUnitTwoAverage"
      },

      {
        propertyName:
          "ammoniaM3d",

        decimalPlaces:
          3,

        combinedId:
          "auxiliaryMaterialAmmoniaAverage",

        unitOneId:
          "auxiliaryMaterialAmmoniaUnitOneAverage",

        unitTwoId:
          "auxiliaryMaterialAmmoniaUnitTwoAverage"
      }
    ].forEach(config => {

      setAverageText(
        config.unitOneId,

        calculateUnitAverage(
          config.propertyName,
          1
        ),

        config.decimalPlaces
      );

      setAverageText(
        config.unitTwoId,

        calculateUnitAverage(
          config.propertyName,
          2
        ),

        config.decimalPlaces
      );

      setAverageText(
        config.combinedId,

        calculateUnitAverage(
          config.propertyName
        ),

        config.decimalPlaces
      );
    });
  }


  const originalRenderAuxiliaryMaterialHistory =
    renderAuxiliaryMaterialHistory;


renderAuxiliaryMaterialHistory =
    function renderAuxiliaryMaterialHistoryWithUnitAverages() {

      upgradeAverageSummaryMarkup();

      originalRenderAuxiliaryMaterialHistory();

      renderUnitAverageSummary();

      renderAuxiliaryMaterialMobileMonitor();
    };


  function initializeUnitAverageSummary() {
    upgradeAverageSummaryMarkup();

    renderUnitAverageSummary();
  }


  if (
    document.readyState ===
      "loading"
  ) {
    document.addEventListener(
      "DOMContentLoaded",
      initializeUnitAverageSummary,
      {
        once: true
      }
    );

  } else {
    initializeUnitAverageSummary();
  }

})();

/* =====================================================
  부재료 API 응답 확인
===================================================== */

async function readAuxiliaryMaterialJsonResponse(
  response
) {
  const result =
    await response
      .json()
      .catch(
        () => ({})
      );


  if (
    !response.ok ||
    result.ok ===
      false
  ) {
    throw new Error(
      result.message ||
      (
        "부재료 저장자료를 불러오지 못했습니다. " +
        `(HTTP ${response.status})`
      )
    );
  }


  return result;
}

/* =========================================================
  부재료 엑셀 보관용 선택 월 정보

  예:
  월 선택 = 2026-08

  결과:
  - 2026-08-01 ~ 2026-08-31
  - 시트명: 2026.08
  - 파일명용: 2026-08

  현재 월인 경우에는
  미래 날짜를 조회하지 않기 위해 오늘까지만 가져온다.
========================================================= */

function getAuxiliaryMaterialArchiveDownloadContext() {
  const elements =
    getAuxiliaryMaterialElements();


  const monthValue =
    String(
      elements.monthInput?.value ||
      getCurrentAuxiliaryMaterialMonthValue()
    ).trim();


  const match =
    monthValue.match(
      /^(\d{4})-(\d{2})$/
    );


  if (
    !match
  ) {
    throw new Error(
      "엑셀로 저장할 조회 월을 확인할 수 없습니다."
    );
  }


  const year =
    Number(
      match[1]
    );


  const month =
    Number(
      match[2]
    );


  const range =
    getAuxiliaryMaterialMonthRange(
      monthValue
    );


  if (
    !range
  ) {
    throw new Error(
      "선택한 월의 부재료 자료를 조회할 수 없습니다."
    );
  }


  /*
    해당 달 전체 일수

    예:
    2026년 8월 → 31일
  */
  const calendarDayCount =
    new Date(
      year,
      month,
      0
    ).getDate();


  /*
    실제 조회기간 일수

    과거 월:
    전체 일수

    현재 월:
    오늘까지
  */
  const startDate =
    new Date(
      `${range.startDate}T00:00:00`
    );


  const endDate =
    new Date(
      `${range.endDate}T00:00:00`
    );


  const requestedDayCount =
    Math.floor(
      (
        endDate.getTime() -
        startDate.getTime()
      ) /
      86400000
    ) +
    1;


  return {
    monthValue,

    year,

    month,

    monthText:
      String(
        month
      ).padStart(
        2,
        "0"
      ),

    /*
      원본 엑셀 시트명
      예: 2026.08
    */
    sheetName:
      `${year}.${String(
        month
      ).padStart(
        2,
        "0"
      )}`,

    startDate:
      range.startDate,

    endDate:
      range.endDate,

    calendarDayCount,

    requestedDayCount
  };
}


/* =========================================================
  부재료 엑셀 보관용 D1 월간 자료 조회

  화면의 시작일/종료일을 사용하지 않고
  상단의 "조회 월"을 기준으로 직접 조회한다.

  이유:
  사용자가 기간 입력을 임의 변경했더라도
  엑셀 보관본은 반드시 선택 월 기준으로 생성하기 위함.
========================================================= */

async function fetchAuxiliaryMaterialArchiveMonthData() {
  const context =
    getAuxiliaryMaterialArchiveDownloadContext();


  const query =
    new URLSearchParams({
      action:
        "materials_history",

      startDate:
        context.startDate,

      endDate:
        context.endDate,

      _:
        String(
          Date.now()
        )
    });


  const headers =
    typeof getShiftLogAuthHeaders ===
      "function"
      ? getShiftLogAuthHeaders()
      : {
          Accept:
            "application/json"
        };


  const response =
    await fetch(
      (
        "/api/ois-data-requests?" +
        query.toString()
      ),
      {
        method:
          "GET",

        headers,

        cache:
          "no-store"
      }
    );


  const result =
    await readAuxiliaryMaterialJsonResponse(
      response
    );


  const items =
    Array.isArray(
      result.items
    )
      ? result.items
      : [];


  const summary =
    result.summary &&
    typeof result.summary ===
      "object"
      ? result.summary
      : {};


  return {
    ...context,

    items,

    summary,

    savedDateCount:
      Number(
        summary.savedDateCount ||
        0
      )
  };
}

/* =========================================================
  부재료 보관 엑셀 날짜 → Excel 일련번호

  예:
  2026-08-01

  원본 엑셀 A열의 날짜 형식을 그대로 유지하기 위해
  문자 날짜가 아니라 Excel 날짜 숫자로 입력한다.
========================================================= */

function createAuxiliaryMaterialArchiveExcelDateSerial(
  isoDate
) {
  if (
    !isValidAuxiliaryMaterialIsoDate(
      isoDate
    )
  ) {
    return null;
  }


  const [
    year,
    month,
    day
  ] =
    isoDate
      .split(
        "-"
      )
      .map(
        Number
      );


  return (
    Math.floor(
      Date.UTC(
        year,
        month - 1,
        day
      ) /
      86400000
    ) +
    25569
  );
}


/* =========================================================
  부재료 보관 엑셀 숫자값 정리

  null / 빈값:
  → 엑셀 빈칸

  0:
  → 실제 숫자 0 유지
========================================================= */

function normalizeAuxiliaryMaterialArchiveNumber(
  value
) {
  if (
    value ===
      null ||
    value ===
      undefined ||
    String(
      value
    ).trim() ===
      ""
  ) {
    return null;
  }


  const numericValue =
    Number(
      value
    );


  return Number.isFinite(
    numericValue
  )
    ? numericValue
    : null;
}


/* =========================================================
  날짜별 1·2호기 비고 합치기
========================================================= */

function createAuxiliaryMaterialArchiveRemarks(
  unitOne,
  unitTwo
) {
  const unitOneRemarks =
    String(
      unitOne?.remarks ??
      ""
    ).trim();


  const unitTwoRemarks =
    String(
      unitTwo?.remarks ??
      ""
    ).trim();


  if (
    unitOneRemarks &&
    unitTwoRemarks &&
    unitOneRemarks !==
      unitTwoRemarks
  ) {
    return (
      `1호기: ${unitOneRemarks} / ` +
      `2호기: ${unitTwoRemarks}`
    );
  }


  return (
    unitOneRemarks ||
    unitTwoRemarks ||
    ""
  );
}


/* =========================================================
  D1 월간 자료 → 원본 엑셀 A:R 행 구조 변환

  원본 양식:

  A   일자

  B   1호기 SOx
  C   1호기 Limestone 사용량
  D   1호기 Limestone 입고량
  E   1호기 Lime Slurry 유량
  F   1호기 Slurry 밀도
  G   1호기 Lime Powder
  H   1호기 NOx
  I   1호기 Ammonia

  J   2호기 SOx
  K   2호기 Limestone 사용량
  L   2호기 Limestone 입고량
  M   2호기 Lime Slurry 유량
  N   2호기 Slurry 밀도
  O   2호기 Lime Powder
  P   2호기 NOx
  Q   2호기 Ammonia

  R   비고

  중요:
  - 4행 = 해당 월 1일
  - 5행 = 2일
  - ...
  - 저장되지 않은 날짜 B:R은 빈칸
========================================================= */

function createAuxiliaryMaterialArchiveRows(
  archiveData
) {
  if (
    !archiveData ||
    !Number.isInteger(
      archiveData.year
    ) ||
    !Number.isInteger(
      archiveData.month
    )
  ) {
    throw new Error(
      "부재료 엑셀 변환용 월 정보를 확인할 수 없습니다."
    );
  }


  const items =
    Array.isArray(
      archiveData.items
    )
      ? archiveData.items
      : [];


  /*
    날짜별 1호기 / 2호기 묶기
  */
  const rowsByDate =
    new Map();


  items.forEach(
    item => {
      const recordDate =
        String(
          item?.recordDate ||
          ""
        ).trim();


      const unitNo =
        Number(
          item?.unitNo
        );


      if (
        !isValidAuxiliaryMaterialIsoDate(
          recordDate
        ) ||
        ![
          1,
          2
        ].includes(
          unitNo
        )
      ) {
        return;
      }


      /*
        선택한 월의 자료만 사용한다.
      */
      if (
        recordDate.slice(
          0,
          7
        ) !==
          archiveData.monthValue
      ) {
        return;
      }


      if (
        !rowsByDate.has(
          recordDate
        )
      ) {
        rowsByDate.set(
          recordDate,
          {
            unitOne:
              null,

            unitTwo:
              null
          }
        );
      }


      const row =
        rowsByDate.get(
          recordDate
        );


      if (
        unitNo ===
          1
      ) {
        row.unitOne =
          item;

      } else {
        row.unitTwo =
          item;
      }
    }
  );


  const rows =
    [];


  /*
    저장된 날짜만 만드는 것이 아니라
    해당 월 1일 ~ 말일까지 전부 만든다.

    이유:
    원본 템플릿에 들어 있던 기존 값이나 수식을
    반드시 지우고 D1 확정값만 남기기 위함.
  */
  for (
    let day =
      1;
    day <=
      archiveData.calendarDayCount;
    day +=
      1
  ) {
    const recordDate =
      (
        `${archiveData.year}-` +
        `${String(
          archiveData.month
        ).padStart(
          2,
          "0"
        )}-` +
        `${String(
          day
        ).padStart(
          2,
          "0"
        )}`
      );


    const source =
      rowsByDate.get(
        recordDate
      ) || {
        unitOne:
          null,

        unitTwo:
          null
      };


    const unitOne =
      source.unitOne;


    const unitTwo =
      source.unitTwo;


    /*
      원본 엑셀 기준

      4행 = 1일
      5행 = 2일
      ...
    */
    const excelRowNumber =
      day +
      3;


    const values = [
      /*
        A
      */
      createAuxiliaryMaterialArchiveExcelDateSerial(
        recordDate
      ),


      /*
        B:I
        1호기
      */
      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.soxPpm
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.limestoneUsageTpd
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.limestoneReceiptTon
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.limeSlurryFlowM3h
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.limeSlurryDensityKgm3
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.limePowderTpd
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.noxPpm
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitOne?.ammoniaM3d
      ),


      /*
        J:Q
        2호기
      */
      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.soxPpm
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.limestoneUsageTpd
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.limestoneReceiptTon
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.limeSlurryFlowM3h
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.limeSlurryDensityKgm3
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.limePowderTpd
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.noxPpm
      ),

      normalizeAuxiliaryMaterialArchiveNumber(
        unitTwo?.ammoniaM3d
      ),


      /*
        R
      */
      createAuxiliaryMaterialArchiveRemarks(
        unitOne,
        unitTwo
      )
    ];


    rows.push({
      recordDate,

      day,

      excelRowNumber,

      unitOne,

      unitTwo,

      values
    });
  }


  return rows;
}

/* =========================================================
  부재료 보관 엑셀 XML Namespace
========================================================= */

const AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE =
  "http://schemas.openxmlformats.org/spreadsheetml/2006/main";


const AUXILIARY_MATERIAL_ARCHIVE_OFFICE_RELATIONSHIP_NAMESPACE =
  "http://schemas.openxmlformats.org/officeDocument/2006/relationships";


const AUXILIARY_MATERIAL_ARCHIVE_PACKAGE_RELATIONSHIP_NAMESPACE =
  "http://schemas.openxmlformats.org/package/2006/relationships";


/* =========================================================
  부재료 보관 엑셀 XML 파싱
========================================================= */

function parseAuxiliaryMaterialArchiveXml(
  xmlText,
  description
) {
  const documentObject =
    new DOMParser()
      .parseFromString(
        xmlText,
        "application/xml"
      );


  if (
    documentObject.querySelector(
      "parsererror"
    )
  ) {
    throw new Error(
      `${description} XML을 읽지 못했습니다.`
    );
  }


  return documentObject;
}


/* =========================================================
  XLSX 내부 상대 경로 정규화

  예:
  xl + worksheets/sheet1.xml
  → xl/worksheets/sheet1.xml
========================================================= */

function normalizeAuxiliaryMaterialArchiveZipPath(
  basePath,
  targetPath
) {
  if (
    String(
      targetPath ||
      ""
    ).startsWith(
      "/"
    )
  ) {
    return String(
      targetPath
    ).replace(
      /^\/+/,
      ""
    );
  }


  const parts =
    `${basePath}/${targetPath}`
      .split(
        "/"
      );


  const normalizedParts =
    [];


  parts.forEach(
    part => {
      if (
        !part ||
        part ===
          "."
      ) {
        return;
      }


      if (
        part ===
          ".."
      ) {
        normalizedParts.pop();

        return;
      }


      normalizedParts.push(
        part
      );
    }
  );


  return normalizedParts.join(
    "/"
  );
}


/* =========================================================
  선택 월의 실제 worksheet XML 경로 찾기

  중요:
  sheet1.xml 같은 파일명을 하드코딩하지 않는다.

  예:
  sheetName = 2026.08

  workbook.xml:
  2026.08 → rId1

  workbook.xml.rels:
  rId1 → worksheets/sheet1.xml
========================================================= */

async function findAuxiliaryMaterialArchiveWorksheetPath(
  zip,
  sheetName
) {
  const workbookFile =
    zip.file(
      "xl/workbook.xml"
    );


  const relationshipFile =
    zip.file(
      "xl/_rels/workbook.xml.rels"
    );


  if (
    !workbookFile ||
    !relationshipFile
  ) {
    throw new Error(
      "부재료 보관 엑셀의 통합문서 구조를 찾지 못했습니다."
    );
  }


  const workbookDocument =
    parseAuxiliaryMaterialArchiveXml(
      await workbookFile.async(
        "string"
      ),
      "부재료 통합문서"
    );


  const relationshipDocument =
    parseAuxiliaryMaterialArchiveXml(
      await relationshipFile.async(
        "string"
      ),
      "부재료 통합문서 관계"
    );


  const sheets =
    Array.from(
      workbookDocument
        .getElementsByTagNameNS(
          AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
          "sheet"
        )
    );


  const targetSheet =
    sheets.find(
      sheet =>
        String(
          sheet.getAttribute(
            "name"
          ) ||
          ""
        ).trim() ===
          sheetName
    );


  if (
    !targetSheet
  ) {
    throw new Error(
      `원본 부재료 엑셀에서 '${sheetName}' 시트를 찾지 못했습니다.`
    );
  }


  const relationshipId =
    targetSheet.getAttributeNS(
      AUXILIARY_MATERIAL_ARCHIVE_OFFICE_RELATIONSHIP_NAMESPACE,
      "id"
    );


  if (
    !relationshipId
  ) {
    throw new Error(
      `${sheetName} 시트의 연결 정보를 찾지 못했습니다.`
    );
  }


  const relationships =
    Array.from(
      relationshipDocument
        .getElementsByTagNameNS(
          AUXILIARY_MATERIAL_ARCHIVE_PACKAGE_RELATIONSHIP_NAMESPACE,
          "Relationship"
        )
    );


  const targetRelationship =
    relationships.find(
      relationship =>
        relationship.getAttribute(
          "Id"
        ) ===
          relationshipId
    );


  if (
    !targetRelationship
  ) {
    throw new Error(
      `${sheetName} 시트의 XML 파일 연결 정보를 찾지 못했습니다.`
    );
  }


  const targetPath =
    String(
      targetRelationship.getAttribute(
        "Target"
      ) ||
      ""
    ).trim();


  if (
    !targetPath
  ) {
    throw new Error(
      `${sheetName} 시트 XML 경로를 확인하지 못했습니다.`
    );
  }


  return normalizeAuxiliaryMaterialArchiveZipPath(
    "xl",
    targetPath
  );
}


/* =========================================================
  셀 자식 데이터 제거

  중요:
  <c r="B4" s="11">의
  r / s 같은 셀 주소와 스타일 속성은 유지한다.

  제거 대상:
  - f  수식
  - v  값
  - is inline string

  따라서:
  색상 / 테두리 / 숫자서식 / 정렬은 그대로 보존된다.
========================================================= */

function clearAuxiliaryMaterialArchiveCellContent(
  cell
) {
  if (
    !cell
  ) {
    return;
  }


  Array.from(
    cell.childNodes
  ).forEach(
    child => {
      if (
        child.nodeType !==
          1
      ) {
        return;
      }


      if (
        [
          "f",
          "v",
          "is"
        ].includes(
          child.localName
        )
      ) {
        child.remove();
      }
    }
  );


  /*
    shared string / inline string 등의
    기존 데이터 형식도 제거한다.
  */
  cell.removeAttribute(
    "t"
  );
}

/* =========================================================
  부재료 보관 엑셀 기존 데이터 영역 완전 초기화

  B4:R35의 기존 값 / 수식 / 문자열을 모두 제거한다.

  중요:
  - 셀 자체는 삭제하지 않는다.
  - style 속성은 유지한다.
  - 따라서 색상 / 테두리 / 숫자형식 / 정렬은 그대로 유지
  - 공유수식 master / follower를 전부 함께 제거하므로
    Excel 복구 경고가 발생하지 않는다.

  A열 날짜는 원본 양식을 유지하고,
  실제 월 날짜는 이후 D1 자료로 다시 덮어쓴다.
========================================================= */

function clearAuxiliaryMaterialArchiveTemplateDataArea(
  worksheetDocument
) {
  const startColumnIndex =
    1; // B


  const endColumnIndex =
    17; // R


  const startRow =
    4;


  const endRow =
    35;


  for (
    let rowNumber =
      startRow;
    rowNumber <=
      endRow;
    rowNumber +=
      1
  ) {
    for (
      let columnIndex =
        startColumnIndex;
      columnIndex <=
        endColumnIndex;
      columnIndex +=
        1
    ) {
      const column =
        getAuxiliaryMaterialArchiveExcelColumn(
          columnIndex
        );


      const cellReference =
        `${column}${rowNumber}`;


      const cell =
        findAuxiliaryMaterialArchiveCell(
          worksheetDocument,
          cellReference
        );


      /*
        원본에 셀이 실제로 존재하는 경우만 정리
      */
      if (
        !cell
      ) {
        continue;
      }


      clearAuxiliaryMaterialArchiveCellContent(
        cell
      );
    }
  }
}

/* =========================================================
  특정 셀 찾기

  예:
  B4
  Q34
========================================================= */

function findAuxiliaryMaterialArchiveCell(
  worksheetDocument,
  cellReference
) {
  const cells =
    Array.from(
      worksheetDocument
        .getElementsByTagNameNS(
          AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
          "c"
        )
    );


  return (
    cells.find(
      cell =>
        String(
          cell.getAttribute(
            "r"
          ) ||
          ""
        ).toUpperCase() ===
        String(
          cellReference ||
          ""
        ).toUpperCase()
    ) ||
    null
  );
}


/* =========================================================
  숫자 셀 입력

  기존 스타일은 유지하고
  기존 수식은 제거한 뒤 D1 확정 숫자를 직접 넣는다.
========================================================= */

function setAuxiliaryMaterialArchiveNumericCell(
  worksheetDocument,
  cellReference,
  value
) {
  const cell =
    findAuxiliaryMaterialArchiveCell(
      worksheetDocument,
      cellReference
    );


  if (
    !cell
  ) {
    throw new Error(
      `원본 부재료 엑셀에서 ${cellReference} 셀을 찾지 못했습니다.`
    );
  }


  clearAuxiliaryMaterialArchiveCellContent(
    cell
  );


  if (
    value ===
      null ||
    value ===
      undefined ||
    value ===
      ""
  ) {
    /*
      값을 넣지 않는다.

      <c r="B20" s="11"/>
      형태로 남기므로 서식은 유지되고
      화면에는 빈칸으로 표시된다.
    */
    return;
  }


  const numericValue =
    Number(
      value
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    return;
  }


  const valueElement =
    worksheetDocument
      .createElementNS(
        AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
        "v"
      );


  valueElement.textContent =
    String(
      numericValue
    );


  cell.appendChild(
    valueElement
  );
}


/* =========================================================
  문자열 셀 입력

  비고는 sharedStrings.xml을 수정하지 않고
  inlineStr 형식으로 직접 저장한다.

  → 기존 workbook의 sharedStrings 구조와 충돌하지 않음
========================================================= */

function setAuxiliaryMaterialArchiveTextCell(
  worksheetDocument,
  cellReference,
  value
) {
  const cell =
    findAuxiliaryMaterialArchiveCell(
      worksheetDocument,
      cellReference
    );


  if (
    !cell
  ) {
    throw new Error(
      `원본 부재료 엑셀에서 ${cellReference} 셀을 찾지 못했습니다.`
    );
  }


  clearAuxiliaryMaterialArchiveCellContent(
    cell
  );


  const text =
    String(
      value ??
      ""
    );


  if (
    !text
  ) {
    return;
  }


  cell.setAttribute(
    "t",
    "inlineStr"
  );


  const inlineString =
    worksheetDocument
      .createElementNS(
        AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
        "is"
      );


  const textElement =
    worksheetDocument
      .createElementNS(
        AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
        "t"
      );


  /*
    앞뒤 공백도 혹시 있다면 그대로 보존한다.
  */
  textElement.setAttributeNS(
    "http://www.w3.org/XML/1998/namespace",
    "xml:space",
    "preserve"
  );


  textElement.textContent =
    text;


  inlineString.appendChild(
    textElement
  );


  cell.appendChild(
    inlineString
  );
}


/* =========================================================
  Excel 열 문자

  0 → A
  1 → B
  ...
  17 → R
========================================================= */

function getAuxiliaryMaterialArchiveExcelColumn(
  columnIndex
) {
  let index =
    Number(
      columnIndex
    );


  if (
    !Number.isInteger(
      index
    ) ||
    index <
      0
  ) {
    throw new Error(
      "엑셀 열 번호가 올바르지 않습니다."
    );
  }


  let columnName =
    "";


  index +=
    1;


  while (
    index >
      0
  ) {
    const remainder =
      (
        index -
        1
      ) %
      26;


    columnName =
      String.fromCharCode(
        65 +
        remainder
      ) +
      columnName;


    index =
      Math.floor(
        (
          index -
          1
        ) /
        26
      );
  }


  return columnName;
}


/* =========================================================
  A:R 한 행을 실제 worksheet에 반영

  values 배열:
  0  → A
  1  → B
  ...
  17 → R
========================================================= */

function applyAuxiliaryMaterialArchiveRowToWorksheet(
  worksheetDocument,
  archiveRow
) {
  if (
    !archiveRow ||
    !Array.isArray(
      archiveRow.values
    ) ||
    archiveRow.values.length !==
      18
  ) {
    throw new Error(
      "부재료 보관 엑셀 행 자료 구조가 올바르지 않습니다."
    );
  }


  const excelRowNumber =
    Number(
      archiveRow.excelRowNumber
    );


  if (
    !Number.isInteger(
      excelRowNumber
    ) ||
    excelRowNumber <
      1
  ) {
    throw new Error(
      "부재료 보관 엑셀 행 번호가 올바르지 않습니다."
    );
  }


  archiveRow.values.forEach(
    (
      value,
      columnIndex
    ) => {
      const column =
        getAuxiliaryMaterialArchiveExcelColumn(
          columnIndex
        );


      const cellReference =
        `${column}${excelRowNumber}`;


      /*
        R열 = 비고
      */
      if (
        column ===
          "R"
      ) {
        setAuxiliaryMaterialArchiveTextCell(
          worksheetDocument,
          cellReference,
          value
        );


        return;
      }


      /*
        A:Q = 날짜 또는 숫자
      */
      setAuxiliaryMaterialArchiveNumericCell(
        worksheetDocument,
        cellReference,
        value
      );
    }
  );
}

/* =========================================================
  XLSX Content Types Namespace
========================================================= */

const AUXILIARY_MATERIAL_ARCHIVE_CONTENT_TYPES_NAMESPACE =
  "http://schemas.openxmlformats.org/package/2006/content-types";


/* =========================================================
  오래된 calcChain 제거

  선택 월 A:R의 기존 수식을 D1 확정값으로 바꾸므로
  기존 계산 체인이 남아 있지 않게 정리한다.
========================================================= */

async function removeAuxiliaryMaterialArchiveCalcChain(
  zip
) {
  /*
    실제 calcChain 파일 제거
  */
  zip.remove(
    "xl/calcChain.xml"
  );


  /* =====================================================
    workbook.xml.rels에서 calcChain 연결 제거
  ====================================================== */

  const relationshipPath =
    "xl/_rels/workbook.xml.rels";


  const relationshipFile =
    zip.file(
      relationshipPath
    );


  if (
    relationshipFile
  ) {
    const relationshipDocument =
      parseAuxiliaryMaterialArchiveXml(
        await relationshipFile.async(
          "string"
        ),
        "부재료 통합문서 관계"
      );


    const relationships =
      Array.from(
        relationshipDocument
          .getElementsByTagNameNS(
            AUXILIARY_MATERIAL_ARCHIVE_PACKAGE_RELATIONSHIP_NAMESPACE,
            "Relationship"
          )
      );


    relationships.forEach(
      relationship => {
        const type =
          String(
            relationship.getAttribute(
              "Type"
            ) ||
            ""
          );


        if (
          type.endsWith(
            "/calcChain"
          )
        ) {
          relationship.remove();
        }
      }
    );


    zip.file(
      relationshipPath,

      new XMLSerializer()
        .serializeToString(
          relationshipDocument
        )
    );
  }


  /* =====================================================
    [Content_Types].xml에서 calcChain 등록 제거
  ====================================================== */

  const contentTypesPath =
    "[Content_Types].xml";


  const contentTypesFile =
    zip.file(
      contentTypesPath
    );


  if (
    contentTypesFile
  ) {
    const contentTypesDocument =
      parseAuxiliaryMaterialArchiveXml(
        await contentTypesFile.async(
          "string"
        ),
        "부재료 콘텐츠 형식"
      );


    const overrides =
      Array.from(
        contentTypesDocument
          .getElementsByTagNameNS(
            AUXILIARY_MATERIAL_ARCHIVE_CONTENT_TYPES_NAMESPACE,
            "Override"
          )
      );


    overrides.forEach(
      override => {
        const partName =
          String(
            override.getAttribute(
              "PartName"
            ) ||
            ""
          );


        if (
          partName ===
            "/xl/calcChain.xml"
        ) {
          override.remove();
        }
      }
    );


    zip.file(
      contentTypesPath,

      new XMLSerializer()
        .serializeToString(
          contentTypesDocument
        )
    );
  }
}


/* =========================================================
  Excel 재계산 설정

  선택 월의 A:R은 확정값이지만
  원본 파일의 다른 시트/영역에는 수식이 남아 있을 수 있다.

  Excel에서 파일을 열 때
  필요한 나머지 수식을 다시 계산하게 한다.
========================================================= */

async function prepareAuxiliaryMaterialArchiveRecalculation(
  zip
) {
  const workbookPath =
    "xl/workbook.xml";


  const workbookFile =
    zip.file(
      workbookPath
    );


  if (
    !workbookFile
  ) {
    throw new Error(
      "부재료 보관 엑셀의 workbook.xml을 찾지 못했습니다."
    );
  }


  const workbookDocument =
    parseAuxiliaryMaterialArchiveXml(
      await workbookFile.async(
        "string"
      ),
      "부재료 통합문서"
    );


  const workbookRoot =
    workbookDocument
      .documentElement;


  let calcPr =
    workbookDocument
      .getElementsByTagNameNS(
        AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
        "calcPr"
      )[0];


  if (
    !calcPr
  ) {
    calcPr =
      workbookDocument
        .createElementNS(
          AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
          "calcPr"
        );


    const extList =
      workbookDocument
        .getElementsByTagNameNS(
          AUXILIARY_MATERIAL_ARCHIVE_MAIN_XML_NAMESPACE,
          "extLst"
        )[0];


    workbookRoot.insertBefore(
      calcPr,
      extList ||
      null
    );
  }


  calcPr.setAttribute(
    "calcMode",
    "auto"
  );


  calcPr.setAttribute(
    "fullCalcOnLoad",
    "1"
  );


  calcPr.setAttribute(
    "forceFullCalc",
    "1"
  );


  calcPr.setAttribute(
    "calcId",
    "0"
  );


  zip.file(
    workbookPath,

    new XMLSerializer()
      .serializeToString(
        workbookDocument
      )
  );
}


/* =========================================================
  부재료 월간 보관용 XLSX 생성

  처리 순서:

  1. 현재 조회 월 확인
  2. 해당 월 D1 저장자료 조회
  3. 원본 XLSX 템플릿 로드
  4. 선택 월 시트 검색
  5. A:R에 D1 확정값 직접 입력
  6. 기존 서식 / 병합 / 열너비 / 차트 등 유지
  7. 오래된 calcChain 제거
  8. XLSX Blob 생성

  여기서는 다운로드하지 않는다.
  다음 단계에서 버튼과 연결한다.
========================================================= */

async function createAuxiliaryMaterialArchiveWorkbook() {
  if (
    typeof JSZip ===
      "undefined"
  ) {
    throw new Error(
      "JSZip 라이브러리를 불러오지 못했습니다."
    );
  }


  /* =====================================================
    선택 월 D1 자료
  ====================================================== */

  const archiveData =
    await fetchAuxiliaryMaterialArchiveMonthData();


  const archiveRows =
    createAuxiliaryMaterialArchiveRows(
      archiveData
    );


  /* =====================================================
    원본 템플릿 다운로드
  ====================================================== */

  const templateResponse =
    await fetch(
      "/assets/templates/auxiliary-material-archive-template.xlsx",
      {
        method:
          "GET",

        cache:
          "no-store"
      }
    );


  if (
    !templateResponse.ok
  ) {
    throw new Error(
      (
        "부재료 보관용 원본 엑셀을 불러오지 못했습니다. " +
        `(${templateResponse.status})`
      )
    );
  }


  const templateBuffer =
    await templateResponse
      .arrayBuffer();


  /* =====================================================
    XLSX 열기
  ====================================================== */

  const zip =
    await JSZip.loadAsync(
      templateBuffer
    );


  /* =====================================================
    선택 월 시트 찾기

    예:
    2026-08
    → 2026.08
  ====================================================== */

  const worksheetPath =
    await findAuxiliaryMaterialArchiveWorksheetPath(
      zip,
      archiveData.sheetName
    );


  const worksheetFile =
    zip.file(
      worksheetPath
    );


  if (
    !worksheetFile
  ) {
    throw new Error(
      `${archiveData.sheetName} 시트 파일을 열지 못했습니다.`
    );
  }


  const worksheetDocument =
    parseAuxiliaryMaterialArchiveXml(
      await worksheetFile.async(
        "string"
      ),
      `${archiveData.sheetName} 부재료 시트`
    );

      /*
    원본 B4:R35에 남아 있는
    기존 공유수식과 캐시값을 먼저 전부 제거한다.
  */
  clearAuxiliaryMaterialArchiveTemplateDataArea(
    worksheetDocument
  );

  /* =====================================================
    D1 확정값 A:R 반영

    월의 모든 날짜를 순회하므로
    저장되지 않은 날짜의 기존 값/수식도 빈칸으로 정리된다.
  ====================================================== */

  archiveRows.forEach(
    archiveRow => {
      applyAuxiliaryMaterialArchiveRowToWorksheet(
        worksheetDocument,
        archiveRow
      );
    }
  );


  /* =====================================================
    수정된 시트 XML 저장
  ====================================================== */

  zip.file(
    worksheetPath,

    new XMLSerializer()
      .serializeToString(
        worksheetDocument
      )
  );


  /* =====================================================
    계산 관련 정리
  ====================================================== */

  await removeAuxiliaryMaterialArchiveCalcChain(
    zip
  );


  await prepareAuxiliaryMaterialArchiveRecalculation(
    zip
  );


  /* =====================================================
    최종 XLSX Blob 생성
  ====================================================== */

  const blob =
    await zip.generateAsync(
      {
        type:
          "blob",

        mimeType:
          "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",

        compression:
          "DEFLATE",

        compressionOptions: {
          level:
            6
        }
      }
    );


  /* =====================================================
    파일명

    예:
    #1, 2 BLR 부재료 사용량 변화 비교_2026_08월_보관본.xlsx
  ====================================================== */

  const fileName =
    (
      "#1, 2 BLR 부재료 사용량 변화 비교_" +
      `${archiveData.year}_` +
      `${archiveData.monthText}월_보관본.xlsx`
    );


  return {
    blob,

    fileName,

    archiveData,

    archiveRows,

    savedDateCount:
      archiveData.savedDateCount,

    calendarDayCount:
      archiveData.calendarDayCount
  };
}

/* =========================================================
  부재료 보관 엑셀 다운로드 버튼 상태
========================================================= */

function setAuxiliaryMaterialArchiveDownloadButtonState(
  isRunning
) {
  const button =
    document.getElementById(
      "downloadAuxiliaryMaterialExcelButton"
    );


  if (
    !button
  ) {
    return;
  }


  const running =
    isRunning ===
      true;


  button.disabled =
    running;


  button.textContent =
    running
      ? "엑셀 생성 중..."
      : "엑셀 다운로드";


  button.title =
    running
      ? "부재료 보관용 엑셀을 생성하고 있습니다."
      : "선택한 월의 D1 부재료 자료를 원본 양식으로 다운로드";
}


/* =========================================================
  부재료 보관 XLSX 실제 다운로드
========================================================= */

function downloadAuxiliaryMaterialArchiveBlob(
  blob,
  fileName
) {
  if (
    !(blob instanceof Blob)
  ) {
    throw new Error(
      "다운로드할 부재료 엑셀 파일을 만들지 못했습니다."
    );
  }


  const objectUrl =
    URL.createObjectURL(
      blob
    );


  const downloadLink =
    document.createElement(
      "a"
    );


  downloadLink.href =
    objectUrl;


  downloadLink.download =
    fileName;


  downloadLink.style.display =
    "none";


  document.body.appendChild(
    downloadLink
  );


  downloadLink.click();


  downloadLink.remove();


  window.setTimeout(
    () => {
      URL.revokeObjectURL(
        objectUrl
      );
    },
    1000
  );
}


/* =========================================================
  부재료 보관 엑셀 다운로드 실행
========================================================= */

async function handleAuxiliaryMaterialArchiveDownload() {
  const button =
    document.getElementById(
      "downloadAuxiliaryMaterialExcelButton"
    );


  if (
    !button ||
    button.disabled
  ) {
    return;
  }


  /*
    모바일 부재료 화면은
    모니터링 전용이므로 다운로드하지 않는다.
  */
  if (
    typeof isAuxiliaryMaterialMobileMonitorMode ===
      "function" &&
    isAuxiliaryMaterialMobileMonitorMode()
  ) {
    return;
  }


  setAuxiliaryMaterialArchiveDownloadButtonState(
    true
  );


  try {
    const result =
      await createAuxiliaryMaterialArchiveWorkbook();


    downloadAuxiliaryMaterialArchiveBlob(
      result.blob,
      result.fileName
    );


    const monthLabel =
      (
        `${result.archiveData.year}년 ` +
        `${result.archiveData.month}월`
      );


    const savedDateCount =
      Number.isFinite(
        Number(
          result.savedDateCount
        )
      )
        ? Number(
            result.savedDateCount
          )
        : 0;


    const calendarDayCount =
      Number.isFinite(
        Number(
          result.calendarDayCount
        )
      )
        ? Number(
            result.calendarDayCount
          )
        : 0;


    const message =
      (
        `${monthLabel} 부재료 보관용 엑셀을 다운로드했습니다. ` +
        `D1 저장 ${savedDateCount}/${calendarDayCount}일`
      );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );

    } else {
      window.alert(
        message
      );
    }

  } catch (
    error
  ) {
    console.error(
      "부재료 보관 엑셀 다운로드 오류:",
      error
    );


    const message =
      (
        error instanceof Error &&
        error.message
      )
        ? error.message
        : "부재료 보관용 엑셀을 생성하지 못했습니다.";


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );

    } else {
      window.alert(
        message
      );
    }

  } finally {
    setAuxiliaryMaterialArchiveDownloadButtonState(
      false
    );
  }
}


/* =========================================================
  부재료 보관 엑셀 다운로드 초기화
========================================================= */

function initializeAuxiliaryMaterialArchiveDownloadControls() {
  /*
    모바일에서는 다운로드 버튼을 만들지 않는다.
  */
  if (
    typeof isAuxiliaryMaterialMobileMonitorMode ===
      "function" &&
    isAuxiliaryMaterialMobileMonitorMode()
  ) {
    return;
  }


  /*
    다운로드 버튼이 아직 생성되지 않았다면
    PC 상단 컴팩트 영역부터 준비한다.
  */
  if (
    typeof prepareAuxiliaryMaterialPcCompactControls ===
      "function"
  ) {
    prepareAuxiliaryMaterialPcCompactControls();
  }


  const button =
    document.getElementById(
      "downloadAuxiliaryMaterialExcelButton"
    );


  if (
    !button
  ) {
    return;
  }


  /*
    이벤트 중복 연결 방지
  */
  if (
    button.dataset
      .auxiliaryMaterialArchiveBound ===
      "true"
  ) {
    return;
  }


  button.addEventListener(
    "click",
    () => {
      handleAuxiliaryMaterialArchiveDownload();
    }
  );


  button.dataset
    .auxiliaryMaterialArchiveBound =
    "true";


  /*
    앞 단계에서 임시 disabled 처리했던 것을 해제
  */
  button.disabled =
    false;


  button.textContent =
    "엑셀 다운로드";


  button.title =
    "선택한 월의 D1 부재료 자료를 원본 양식으로 다운로드";
}


/* =========================================================
  부재료 보관 엑셀 다운로드 초기 실행
========================================================= */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialArchiveDownloadControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialArchiveDownloadControls();
}

/* =====================================================
  D1 부재료 저장자료 불러오기
===================================================== */

async function loadAuxiliaryMaterialHistory(
  options = {}
) {
  const elements =
    getAuxiliaryMaterialElements();

  const isSilent =
    options.silent ===
      true;

  const range =
    readAuxiliaryMaterialDateRange();

  const rangeKey =
    getAuxiliaryMaterialHistoryRangeKey(
      range
    );

  /*
    날짜를 빠르게 이동했을 때
    이전 요청의 응답이 최신 화면을 덮지 않도록 구분
  */
  const loadSequence =
    auxiliaryMaterialHistoryState
      .loadSequence +
    1;

  auxiliaryMaterialHistoryState
    .loadSequence =
    loadSequence;

  auxiliaryMaterialHistoryState
    .loadingRangeKey =
    rangeKey;

  if (
    elements.loadButton &&
    !isSilent
  ) {
    elements.loadButton.disabled =
      true;
  }

  if (
    !isSilent
  ) {
    setAuxiliaryMaterialStatus(
      (
        `${range.startDate} ~ ${range.endDate} ` +
        "저장자료를 불러오고 있습니다."
      ),
      "loading"
    );
  }

  try {
    const query =
      new URLSearchParams({
        action:
          "materials_history",

        startDate:
          range.startDate,

        endDate:
          range.endDate,

        _:
          String(
            Date.now()
          )
      });

    const headers =
      typeof getShiftLogAuthHeaders ===
        "function"
        ? getShiftLogAuthHeaders()
        : {
            Accept:
              "application/json"
          };

    const [
      response,
      linkedLimestoneUsage
    ] =
      await Promise.all([
        fetch(
          (
            "/api/ois-data-requests?" +
            query.toString()
          ),
          {
            method:
              "GET",

            headers,

            cache:
              "no-store"
          }
        ),

        loadAuxiliaryMaterialLinkedLimestoneUsage(
          range,
          headers
        )
      ]);

    const result =
      await readAuxiliaryMaterialJsonResponse(
        response
      );

    /*
      이미 더 새로운 날짜 요청이 시작됐다면
      이번 응답은 화면에 반영하지 않는다.
    */
    if (
      loadSequence !==
      auxiliaryMaterialHistoryState
        .loadSequence
    ) {
      return result;
    }

    auxiliaryMaterialHistoryState.items =
      mergeAuxiliaryMaterialLimestoneUsageHistory(
        result.items,
        linkedLimestoneUsage.items,
        {
          linkedResponseLoaded:
            linkedLimestoneUsage.loaded
        }
      );

    auxiliaryMaterialHistoryState.summary =
      result.summary &&
      typeof result.summary ===
        "object"
        ? result.summary
        : {};

    /*
      정상적으로 불러온 날짜 범위 저장
      같은 범위로 메뉴에 재진입할 때 사용
    */
    auxiliaryMaterialHistoryState
      .loadedRangeKey =
      rangeKey;

    renderAuxiliaryMaterialHistory();

    /*
      저장자료를 불러온 뒤
      최근 Slurry 밀도도 다시 표시
    */
    renderAuxiliaryMaterialFixedDensitySettings();

    if (
      !isSilent
    ) {
      setAuxiliaryMaterialStatus(
        (
          `${result.range?.startDate || range.startDate}` +
          " ~ " +
          `${result.range?.endDate || range.endDate}` +
          " · " +
          `${Number(
            result.summary
              ?.savedDateCount ||
            0
          )}일 저장`
        ),
        "complete"
      );
    }

    return result;

  } catch (
    error
  ) {
    const message =
      error instanceof
        Error
        ? error.message
        : "부재료 저장자료를 불러오지 못했습니다.";

    if (
      !isSilent
    ) {
      setAuxiliaryMaterialStatus(
        message,
        "error"
      );

      if (
        typeof showToast ===
          "function"
      ) {
        showToast(
          message
        );
      }
    }

    throw error;

  } finally {
    if (
      loadSequence ===
        auxiliaryMaterialHistoryState
          .loadSequence &&
      auxiliaryMaterialHistoryState
        .loadingRangeKey ===
          rangeKey
    ) {
      auxiliaryMaterialHistoryState
        .loadingRangeKey =
        "";
    }

    if (
      elements.loadButton &&
      !isSilent
    ) {
      elements.loadButton.disabled =
        false;
    }
  }
}

/* =====================================================
  부재료 저장자료 조회 이벤트 연결
===================================================== */

function initializeAuxiliaryMaterialHistoryControls() {
  const elements =
    getAuxiliaryMaterialElements();

  if (
    !elements.view ||
    !elements.loadButton
  ) {
    return;
  }

  if (
    elements
      .loadButton
      .dataset
      .auxiliaryMaterialHistoryBound ===
        "true"
  ) {
    return;
  }

  const today =
    formatAuxiliaryMaterialIsoDate(
      new Date()
    );

  if (
    elements.startDateInput
  ) {
    elements.startDateInput.max =
      today;
  }

  if (
    elements.endDateInput
  ) {
    elements.endDateInput.max =
      today;
  }

  let savedHistoryLoadTimer =
    null;

  function loadAuxiliaryMaterialHistoryIfNeeded() {
    let range;

    try {
      range =
        readAuxiliaryMaterialDateRange();

    } catch (
      error
    ) {
      setAuxiliaryMaterialStatus(
        error instanceof Error
          ? error.message
          : "부재료 조회 월을 확인해 주세요.",
        "error"
      );

      return;
    }

    const rangeKey =
      getAuxiliaryMaterialHistoryRangeKey(
        range
      );

    /*
      같은 월이 이미 로드된 경우:
      서버 요청 없이 메모리 자료만 다시 표시
    */
    if (
      auxiliaryMaterialHistoryState
        .loadedRangeKey ===
        rangeKey
    ) {
      renderAuxiliaryMaterialHistory();

      renderAuxiliaryMaterialFixedDensitySettings();

      return;
    }

    /*
      같은 월을 현재 불러오는 중인 경우:
      중복 요청하지 않음
    */
    if (
      auxiliaryMaterialHistoryState
        .loadingRangeKey ===
        rangeKey
    ) {
      return;
    }

    /*
      저장된 D1 자료만 불러온다.
      OIS 신규 조회는 실행하지 않는다.
    */
    loadAuxiliaryMaterialHistory()
      .catch(
        () => {
          /*
            오류 표시는 조회 함수가 담당한다.
          */
        }
      );
  }

  function scheduleAuxiliaryMaterialHistoryLoad() {
    if (
      savedHistoryLoadTimer
    ) {
      window.clearTimeout(
        savedHistoryLoadTimer
      );
    }

    /*
      월 화살표를 빠르게 여러 번 누르면
      마지막으로 선택한 월만 불러온다.
    */
    savedHistoryLoadTimer =
      window.setTimeout(
        () => {
          savedHistoryLoadTimer =
            null;

          loadAuxiliaryMaterialHistoryIfNeeded();
        },
        160
      );
  }

  /*
    PC 저장자료 보기:
    사용자가 누를 때마다 최신 자료 조회
  */
  elements.loadButton.addEventListener(
    "click",
    () => {
      loadAuxiliaryMaterialHistory()
        .catch(
          () => {
            /*
              오류 표시는 조회 함수가 담당한다.
            */
          }
        );
    }
  );

  /*
    부재료 메뉴를 열면
    선택된 월의 저장자료만 조건부 복원
  */
  elements.tab
    ?.addEventListener(
      "click",
      loadAuxiliaryMaterialHistoryIfNeeded
    );

  /*
    조회 월 변경 후 저장자료 조건부 복원
  */
  elements.monthInput
    ?.addEventListener(
      "change",
      scheduleAuxiliaryMaterialHistoryLoad
    );

  elements.previousMonthButton
    ?.addEventListener(
      "click",
      scheduleAuxiliaryMaterialHistoryLoad
    );

  elements.nextMonthButton
    ?.addEventListener(
      "click",
      scheduleAuxiliaryMaterialHistoryLoad
    );

  elements
    .loadButton
    .dataset
    .auxiliaryMaterialHistoryBound =
      "true";
}

/* =====================================================
  초기 실행
===================================================== */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialHistoryControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialHistoryControls();
}

/* =========================================================
  기존 부재료 엑셀 A:R 업로드

  - 월별 시트명: 2026.08 형식
  - A: 날짜
  - B:I: 1호기
  - J:Q: 2호기
  - R: 비고
  - 2026-08-09까지만 저장
  - 한 요청당 최대 40일
========================================================= */

const AUXILIARY_MATERIAL_EXCEL_IMPORT_END_DATE =
  "2026-08-09";

const AUXILIARY_MATERIAL_EXCEL_IMPORT_BATCH_SIZE =
  40;


const auxiliaryMaterialExcelImportState = {
  isRunning:
    false
};


/* =====================================================
  엑셀 업로드 버튼 상태
===================================================== */

function setAuxiliaryMaterialExcelImportButtonState(
  isRunning
) {
  const elements =
    getAuxiliaryMaterialElements();


  auxiliaryMaterialExcelImportState.isRunning =
    isRunning ===
      true;


  if (
    elements.excelImportButton
  ) {
    elements.excelImportButton.disabled =
      auxiliaryMaterialExcelImportState
        .isRunning;


    /*
      PC 상단 컴팩트 버튼 이름 유지

      대기:
      엑셀 등록

      처리 중:
      엑셀 저장 중...
    */
    elements.excelImportButton.textContent =
      auxiliaryMaterialExcelImportState
        .isRunning
        ? "엑셀 저장 중..."
        : "엑셀 등록";
  }


  if (
    elements.excelFileInput
  ) {
    elements.excelFileInput.disabled =
      auxiliaryMaterialExcelImportState
        .isRunning;
  }
}


/* =====================================================
  월별 시트명 확인

  허용 예:
  - 2026.08
  - 2026-08
===================================================== */

function parseAuxiliaryMaterialExcelSheetPeriod(
  sheetName
) {
  const match =
    String(
      sheetName ||
      ""
    )
      .trim()
      .match(
        /^(\d{4})[.\-_/](\d{1,2})$/
      );


  if (
    !match
  ) {
    return null;
  }


  const year =
    Number(
      match[1]
    );


  const month =
    Number(
      match[2]
    );


  if (
    !Number.isInteger(
      year
    ) ||
    month <
      1 ||
    month >
      12
  ) {
    return null;
  }


  return {
    year,
    month,

    monthKey:
      `${year}-` +
      `${padAuxiliaryMaterialDateNumber(
        month
      )}`
  };
}


/* =====================================================
  엑셀 날짜 → YYYY-MM-DD
===================================================== */

function createAuxiliaryMaterialExcelIsoDate(
  year,
  month,
  day
) {
  const isoDate =
    `${Number(
      year
    )}-` +
    `${padAuxiliaryMaterialDateNumber(
      month
    )}-` +
    `${padAuxiliaryMaterialDateNumber(
      day
    )}`;


  return isValidAuxiliaryMaterialIsoDate(
    isoDate
  )
    ? isoDate
    : "";
}


/* =====================================================
  엑셀 A열 날짜 읽기
===================================================== */

function readAuxiliaryMaterialExcelDateCell(
  worksheet,
  rowNumber
) {
  const cellAddress =
    XLSX.utils.encode_cell({
      r:
        rowNumber -
        1,

      c:
        0
    });


  const cell =
    worksheet[
      cellAddress
    ];


  if (
    !cell ||
    cell.t ===
      "e"
  ) {
    return "";
  }


  const value =
    cell.v;


  /*
    SheetJS가 날짜 객체로 읽은 경우
  */
  if (
    value instanceof
      Date &&
    !Number.isNaN(
      value.getTime()
    )
  ) {
    return createAuxiliaryMaterialExcelIsoDate(
      value.getFullYear(),
      value.getMonth() +
        1,
      value.getDate()
    );
  }


  /*
    Excel 날짜 일련번호인 경우
  */
  if (
    typeof value ===
      "number" &&
    Number.isFinite(
      value
    )
  ) {
    const parsedDate =
      XLSX.SSF
        ?.parse_date_code
        ? XLSX.SSF.parse_date_code(
            value
          )
        : null;


    if (
      parsedDate
    ) {
      return createAuxiliaryMaterialExcelIsoDate(
        parsedDate.y,
        parsedDate.m,
        parsedDate.d
      );
    }
  }


  /*
    문자 날짜인 경우
  */
  const text =
    String(
      value ??
      ""
    ).trim();


  const match =
    text.match(
      /^(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})/
    );


  if (
    !match
  ) {
    return "";
  }


  return createAuxiliaryMaterialExcelIsoDate(
    Number(
      match[1]
    ),
    Number(
      match[2]
    ),
    Number(
      match[3]
    )
  );
}


/* =====================================================
  엑셀 숫자 셀 읽기

  수식 자체가 아니라
  엑셀에 저장된 계산 결과값을 읽는다.
===================================================== */

function readAuxiliaryMaterialExcelNumberCell(
  worksheet,
  rowNumber,
  columnIndex,
  sheetName
) {
  const cellAddress =
    XLSX.utils.encode_cell({
      r:
        rowNumber -
        1,

      c:
        columnIndex
    });


  const cell =
    worksheet[
      cellAddress
    ];


  if (
    !cell ||
    cell.v ===
      null ||
    cell.v ===
      undefined
  ) {
    return null;
  }


  if (
    cell.t ===
      "e"
  ) {
    throw new Error(
      `${sheetName} 시트 ${cellAddress} 셀에 엑셀 오류값이 있습니다.`
    );
  }


  const normalizedValue =
    typeof cell.v ===
      "string"
      ? cell.v
          .trim()
          .replace(
            /,/g,
            ""
          )
      : cell.v;


  if (
    normalizedValue ===
      "" ||
    normalizedValue ===
      "-" ||
    normalizedValue ===
      "—"
  ) {
    return null;
  }


  const numericValue =
    Number(
      normalizedValue
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    throw new Error(
      `${sheetName} 시트 ${cellAddress} 셀의 계산 결과가 숫자가 아닙니다.`
    );
  }


  return numericValue;
}


/* =====================================================
  엑셀 비고 셀 읽기
===================================================== */

function readAuxiliaryMaterialExcelTextCell(
  worksheet,
  rowNumber,
  columnIndex,
  sheetName
) {
  const cellAddress =
    XLSX.utils.encode_cell({
      r:
        rowNumber -
        1,

      c:
        columnIndex
    });


  const cell =
    worksheet[
      cellAddress
    ];


  if (
    !cell ||
    cell.v ===
      null ||
    cell.v ===
      undefined
  ) {
    return "";
  }


  if (
    cell.t ===
      "e"
  ) {
    throw new Error(
      `${sheetName} 시트 ${cellAddress} 셀에 엑셀 오류값이 있습니다.`
    );
  }


  const text =
    String(
      cell.v
    ).trim();


  if (
    text.length >
      1000
  ) {
    throw new Error(
      `${sheetName} 시트 ${cellAddress} 비고는 1,000자 이하로 입력해 주세요.`
    );
  }


  return text;
}


/* =====================================================
  기존 A:R 양식 확인
===================================================== */

function isAuxiliaryMaterialExcelSheetLayout(
  worksheet
) {
  function readHeader(
    cellAddress
  ) {
    return String(
      worksheet[
        cellAddress
      ]?.v ??
      ""
    )
      .replace(
        /\s+/g,
        ""
      )
      .toLowerCase();
  }


  return (
    readHeader(
      "A2"
    ) ===
      "일자" &&

    readHeader(
      "B2"
    ).includes(
      "1호기"
    ) &&

    readHeader(
      "J2"
    ).includes(
      "2호기"
    ) &&

    readHeader(
      "B3"
    ).includes(
      "sox"
    ) &&

    readHeader(
      "J3"
    ).includes(
      "sox"
    )
  );
}


/* =====================================================
  엑셀 한 날짜를 서버 전송 형식으로 변환
===================================================== */

function createAuxiliaryMaterialExcelItem(
  worksheet,
  sheetName,
  rowNumber,
  recordDate
) {
  const readNumber =
    columnIndex =>
      readAuxiliaryMaterialExcelNumberCell(
        worksheet,
        rowNumber,
        columnIndex,
        sheetName
      );


  return {
    recordDate,
    sheetName,


    /*
      B:I
    */
    unitOne: {
      soxPpm:
        readNumber(
          1
        ),

      limestoneUsageTpd:
        readNumber(
          2
        ),

      limestoneReceiptTon:
        readNumber(
          3
        ),

      limeSlurryFlowM3h:
        readNumber(
          4
        ),

      limeSlurryDensityKgm3:
        readNumber(
          5
        ),

      limePowderTpd:
        readNumber(
          6
        ),

      noxPpm:
        readNumber(
          7
        ),

      ammoniaM3d:
        readNumber(
          8
        )
    },


    /*
      J:Q
    */
    unitTwo: {
      soxPpm:
        readNumber(
          9
        ),

      limestoneUsageTpd:
        readNumber(
          10
        ),

      limestoneReceiptTon:
        readNumber(
          11
        ),

      limeSlurryFlowM3h:
        readNumber(
          12
        ),

      limeSlurryDensityKgm3:
        readNumber(
          13
        ),

      limePowderTpd:
        readNumber(
          14
        ),

      noxPpm:
        readNumber(
          15
        ),

      ammoniaM3d:
        readNumber(
          16
        )
    },


    /*
      R
    */
    remarks:
      readAuxiliaryMaterialExcelTextCell(
        worksheet,
        rowNumber,
        17,
        sheetName
      )
  };
}


/* =====================================================
  월별 시트 전체 해석

  각 시트에 다음 달 1일 행이 포함될 수 있으므로
  시트명과 같은 연월만 가져온다.
===================================================== */

function parseAuxiliaryMaterialExcelWorkbook(
  workbook
) {
  if (
    !workbook ||
    !Array.isArray(
      workbook.SheetNames
    )
  ) {
    throw new Error(
      "엑셀 시트 목록을 확인할 수 없습니다."
    );
  }


  const itemsByDate =
    new Map();


  const excludedDates =
    new Set();


  let sourceSheetCount =
    0;


  workbook.SheetNames.forEach(
    sheetName => {
      const period =
        parseAuxiliaryMaterialExcelSheetPeriod(
          sheetName
        );


      /*
        Sheet2 등 월별 시트가 아닌 시트는 제외
      */
      if (
        !period
      ) {
        return;
      }


      const worksheet =
        workbook.Sheets?.[
          sheetName
        ];


      if (
        !worksheet
      ) {
        return;
      }


      if (
        !isAuxiliaryMaterialExcelSheetLayout(
          worksheet
        )
      ) {
        throw new Error(
          `${sheetName} 시트의 A:R 열 구성이 기존 부재료 양식과 다릅니다.`
        );
      }


      sourceSheetCount +=
        1;


      /*
        실제 표는 위쪽에 있으므로
        최초 100행까지만 확인한다.
      */
      for (
        let rowNumber =
          1;
        rowNumber <=
          100;
        rowNumber +=
          1
      ) {
        const recordDate =
          readAuxiliaryMaterialExcelDateCell(
            worksheet,
            rowNumber
          );


        if (
          !recordDate ||
          recordDate.slice(
            0,
            7
          ) !==
            period.monthKey
        ) {
          continue;
        }


        /*
          2026-08-10 이후는 OIS 자료 보호
        */
        if (
          recordDate >
            AUXILIARY_MATERIAL_EXCEL_IMPORT_END_DATE
        ) {
          excludedDates.add(
            recordDate
          );

          continue;
        }


        if (
          itemsByDate.has(
            recordDate
          )
        ) {
          throw new Error(
            `${recordDate} 자료가 엑셀에 두 번 포함되어 있습니다.`
          );
        }


        itemsByDate.set(
          recordDate,

          createAuxiliaryMaterialExcelItem(
            worksheet,
            sheetName,
            rowNumber,
            recordDate
          )
        );
      }
    }
  );


  if (
    sourceSheetCount <
      1
  ) {
    throw new Error(
      "2026.08 형식의 월별 부재료 시트를 찾을 수 없습니다."
    );
  }


  const items =
    Array.from(
      itemsByDate.values()
    ).sort(
      (
        left,
        right
      ) =>
        left.recordDate.localeCompare(
          right.recordDate
        )
    );


  if (
    items.length <
      1
  ) {
    throw new Error(
      "2026-08-09까지 저장할 부재료 자료가 없습니다."
    );
  }


  return {
    items,
    sourceSheetCount,

    excludedDates:
      Array.from(
        excludedDates
      ).sort()
  };
}


/* =====================================================
  엑셀 한 묶음 서버 저장
===================================================== */

async function postAuxiliaryMaterialExcelBatch(
  fileName,
  items
) {
  const headers =
    typeof getShiftLogAuthHeaders ===
      "function"
      ? getShiftLogAuthHeaders({
          "Content-Type":
            "application/json"
        })
      : {
          Accept:
            "application/json",

          "Content-Type":
            "application/json"
        };


  const response =
    await fetch(
      "/api/ois-data-requests",
      {
        method:
          "POST",

        headers,

        cache:
          "no-store",

        body:
          JSON.stringify({
            action:
              "import_auxiliary_material_excel",

            fileName,

            items
          })
      }
    );


  return await readAuxiliaryMaterialJsonResponse(
    response
  );
}


/* =====================================================
  최대 40일씩 순차 저장
===================================================== */

async function saveAuxiliaryMaterialExcelItems(
  fileName,
  items
) {
  const batchCount =
    Math.ceil(
      items.length /
      AUXILIARY_MATERIAL_EXCEL_IMPORT_BATCH_SIZE
    );


  const totals = {
    savedDateCount:
      0,

    savedRecordCount:
      0,

    newRecordCount:
      0,

    replacedRecordCount:
      0
  };


  for (
    let batchIndex =
      0;
    batchIndex <
      batchCount;
    batchIndex +=
      1
  ) {
    const startIndex =
      batchIndex *
      AUXILIARY_MATERIAL_EXCEL_IMPORT_BATCH_SIZE;


    const batchItems =
      items.slice(
        startIndex,

        startIndex +
          AUXILIARY_MATERIAL_EXCEL_IMPORT_BATCH_SIZE
      );


    setAuxiliaryMaterialStatus(
      (
        `엑셀 저장 중 · ${batchIndex + 1}/${batchCount} · ` +
        `${startIndex + batchItems.length}/${items.length}일`
      ),
      "loading"
    );


    let result;


    try {
      result =
        await postAuxiliaryMaterialExcelBatch(
          fileName,
          batchItems
        );

    } catch (
      error
    ) {
      const message =
        error instanceof
          Error
          ? error.message
          : "엑셀 자료 저장에 실패했습니다.";


      throw new Error(
        startIndex >
          0
          ? (
              `${startIndex}일 저장 후 중단되었습니다. ` +
              message
            )
          : message
      );
    }


    totals.savedDateCount +=
      Number(
        result.summary
          ?.savedDateCount ||
        0
      );


    totals.savedRecordCount +=
      Number(
        result.summary
          ?.savedRecordCount ||
        0
      );


    totals.newRecordCount +=
      Number(
        result.summary
          ?.newRecordCount ||
        0
      );


    totals.replacedRecordCount +=
      Number(
        result.summary
          ?.replacedRecordCount ||
        0
      );
  }


  return totals;
}


/* =====================================================
  엑셀 파일 선택 처리
===================================================== */

async function handleAuxiliaryMaterialExcelFileSelection(
  event
) {
  const file =
    event.target.files?.[
      0
    ];


  if (
    !file ||
    auxiliaryMaterialExcelImportState
      .isRunning
  ) {
    return;
  }


  const elements =
    getAuxiliaryMaterialElements();


  if (
    elements.excelFileName
  ) {
    elements.excelFileName.textContent =
      file.name;
  }


  setAuxiliaryMaterialExcelImportButtonState(
    true
  );


  try {
    if (
      !/\.(xlsx|xls)$/i.test(
        file.name
      )
    ) {
      throw new Error(
        "기존 부재료 엑셀 파일(.xlsx 또는 .xls)을 선택해 주세요."
      );
    }


    if (
      typeof XLSX ===
        "undefined"
    ) {
      throw new Error(
        "엑셀 라이브러리를 불러오지 못했습니다."
      );
    }


    setAuxiliaryMaterialStatus(
      "기존 부재료 엑셀 파일을 확인하고 있습니다.",
      "loading"
    );


    /*
      sheetRows 100:
      실제 A:R 표만 읽어 큰 엑셀도 빠르게 처리한다.
    */
    const workbook =
      XLSX.read(
        await file.arrayBuffer(),
        {
          type:
            "array",

          cellDates:
            true,

          sheetRows:
            100
        }
      );


    const parsed =
      parseAuxiliaryMaterialExcelWorkbook(
        workbook
      );


    const firstDate =
      parsed.items[
        0
      ].recordDate;


    const lastDate =
      parsed.items[
        parsed.items.length -
        1
      ].recordDate;


    const batchCount =
      Math.ceil(
        parsed.items.length /
        AUXILIARY_MATERIAL_EXCEL_IMPORT_BATCH_SIZE
      );


    const shouldSave =
      window.confirm(
        [
          (
            `기존 부재료 엑셀 ${parsed.items.length}일 ` +
            "자료를 저장하시겠습니까?"
          ),

          "",

          `기간: ${firstDate} ~ ${lastDate}`,

          `월별 시트: ${parsed.sourceSheetCount}개`,

          (
            `저장 요청: ${batchCount}회 ` +
            "(한 번에 최대 40일)"
          ),

          "",

          "2026-08-10 이후 자료는 저장하지 않습니다.",

          "같은 날짜의 기존 자료는 엑셀 값으로 교체됩니다."
        ].join(
          "\n"
        )
      );


    if (
      !shouldSave
    ) {
      setAuxiliaryMaterialStatus(
        "부재료 엑셀 자료 등록을 취소했습니다."
      );

      return;
    }


    const totals =
      await saveAuxiliaryMaterialExcelItems(
        file.name,
        parsed.items
      );


    /*
      저장한 전체 기간을 바로 표에 표시
    */
    if (
      elements.startDateInput
    ) {
      elements.startDateInput.value =
        firstDate;
    }


    if (
      elements.endDateInput
    ) {
      elements.endDateInput.value =
        lastDate;
    }


    if (
      elements.monthInput
    ) {
      elements.monthInput.value =
        lastDate.slice(
          0,
          7
        );
    }


    await loadAuxiliaryMaterialHistory({
      silent:
        true
    });


    const message =
      (
        `${totals.savedDateCount}일 저장 완료 · ` +
        `신규 ${totals.newRecordCount}건 · ` +
        `교체 ${totals.replacedRecordCount}건`
      );


    setAuxiliaryMaterialStatus(
      message,
      "complete"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }

  } catch (
    error
  ) {
    const message =
      error instanceof
        Error
        ? error.message
        : "부재료 엑셀 파일을 처리하지 못했습니다.";


    console.error(
      "부재료 엑셀 업로드 오류:",
      error
    );


    setAuxiliaryMaterialStatus(
      message,
      "error"
    );


    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }

  } finally {
    setAuxiliaryMaterialExcelImportButtonState(
      false
    );


    /*
      같은 파일을 다시 선택할 수 있도록 초기화
    */
    event.target.value =
      "";
  }
}

/* =========================================================
  부재료 PC 상단 엑셀 등록 버튼 배치

  PC:
  저장 자료 보기 | OIS 조회·D1 저장 | 엑셀 등록

  모바일:
  기존 모니터링 전용 화면 유지
========================================================= */

function prepareAuxiliaryMaterialPcCompactControls() {
  /*
    모바일은 기존 모니터링 전용 화면 유지
  */
  if (
    typeof isAuxiliaryMaterialMobileMonitorMode ===
      "function" &&
    isAuxiliaryMaterialMobileMonitorMode()
  ) {
    return;
  }

  const elements =
    getAuxiliaryMaterialElements();

  const view =
    elements?.view;

  const loadButton =
    elements?.loadButton;

  const queryButton =
    elements?.queryButton;

  const excelButton =
    elements?.excelImportButton;

  const status =
    elements?.status;

  const forceRefreshInput =
    elements?.forceRefreshInput;

  const forceRefreshLabel =
    forceRefreshInput?.closest(
      ".auxiliary-material-force-refresh"
    );

  const startDateLabel =
    elements?.startDateInput
      ?.closest(
        "label"
      );

  const endDateLabel =
    elements?.endDateInput
      ?.closest(
        "label"
      );

  const periodFields =
    queryButton?.closest(
      ".auxiliary-material-period-fields"
    );

  const queryCard =
    periodFields?.closest(
      ".auxiliary-material-query-card"
    );

  const monthNavigation =
    queryCard?.querySelector(
      ".auxiliary-material-month-navigation"
    );

  const densityPanel =
    view?.querySelector(
      ".auxiliary-material-density-setting"
    );

  const excelImportPanel =
    view?.querySelector(
      ".auxiliary-material-excel-import"
    );

  if (
    !view ||
    !loadButton ||
    !queryButton ||
    !excelButton ||
    !startDateLabel ||
    !endDateLabel ||
    !periodFields ||
    !queryCard ||
    !monthNavigation ||
    !densityPanel
  ) {
    return;
  }

  /*
    제목 아래 설명 제거
  */
  const headingDescription =
    view.querySelector(
      ".auxiliary-material-heading > div > p"
    );

  if (
    headingDescription
  ) {
    headingDescription.hidden =
      true;

    headingDescription.style.setProperty(
      "display",
      "none",
      "important"
    );
  }

  /*
    저장된 날짜 강제 재조회 기능 비활성화
  */
  if (
    forceRefreshInput
  ) {
    forceRefreshInput.checked =
      false;

    forceRefreshInput.disabled =
      true;

    forceRefreshInput.setAttribute(
      "aria-disabled",
      "true"
    );
  }

  if (
    forceRefreshLabel
  ) {
    forceRefreshLabel.hidden =
      true;

    forceRefreshLabel.style.setProperty(
      "display",
      "none",
      "important"
    );
  }

  /*
    엑셀 등록 버튼
  */
  excelButton.classList.add(
    "auxiliary-material-excel-inline-button"
  );

  excelButton.textContent =
    "엑셀 등록";

  /*
    엑셀 다운로드 버튼
  */
  let downloadButton =
    document.getElementById(
      "downloadAuxiliaryMaterialExcelButton"
    );

  if (
    !downloadButton
  ) {
    downloadButton =
      document.createElement(
        "button"
      );

    downloadButton.type =
      "button";

    downloadButton.id =
      "downloadAuxiliaryMaterialExcelButton";

    downloadButton.className =
      "auxiliary-material-excel-download-button";

    downloadButton.textContent =
      "엑셀 다운로드";

    downloadButton.disabled =
      true;

    downloadButton.title =
      "다운로드 기능 준비 중";
  }

  downloadButton.classList.add(
    "auxiliary-material-excel-download-button"
  );

  /*
    조회 범위와 자료 작업을 묶는 PC 전용 그룹
  */
  let queryGroup =
    periodFields.querySelector(
      ".auxiliary-material-pc-query-group"
    );

  if (
    !queryGroup
  ) {
    queryGroup =
      document.createElement(
        "div"
      );

    queryGroup.className =
      "auxiliary-material-pc-query-group";

    queryGroup.setAttribute(
      "aria-label",
      "조회 범위 및 자료 작업"
    );
  }

  let rangeControls =
    queryGroup.querySelector(
      ".auxiliary-material-pc-range-controls"
    );

  if (
    !rangeControls
  ) {
    rangeControls =
      document.createElement(
        "div"
      );

    rangeControls.className =
      "auxiliary-material-pc-range-controls";

    rangeControls.setAttribute(
      "aria-label",
      "조회 범위"
    );
  }

  /*
    기간지정 체크박스가 이미 생성돼 있으면
    기준일과 시작일 사이에 다시 배치
  */
  const periodModeLabel =
    document.getElementById(
      "auxiliaryMaterialPeriodModeLabel"
    );

  rangeControls.append(
    monthNavigation
  );

  if (
    periodModeLabel
  ) {
    rangeControls.append(
      periodModeLabel
    );
  }

  rangeControls.append(
    startDateLabel,
    endDateLabel
  );

  let actionControls =
    queryGroup.querySelector(
      ".auxiliary-material-pc-action-controls"
    );

  if (
    !actionControls
  ) {
    actionControls =
      document.createElement(
        "div"
      );

    actionControls.className =
      "auxiliary-material-pc-action-controls";

    actionControls.setAttribute(
      "aria-label",
      "자료 작업"
    );
  }

  /*
    Slurry 밀도 고정값을
    엑셀 다운로드 바로 오른쪽에 배치
  */
  densityPanel.classList.remove(
    "auxiliary-material-density-setting--inline"
  );

  densityPanel.classList.add(
    "auxiliary-material-density-setting--grouped"
  );

  densityPanel.setAttribute(
    "aria-label",
    "Slurry 밀도 고정값"
  );

  const densityTitle =
    densityPanel.querySelector(
      ".auxiliary-material-density-setting__description > strong"
    );

  if (
    densityTitle
  ) {
    densityTitle.textContent =
      "Slurry 밀도 고정값";
  }

  /*
    실제 DOM 순서:
    저장자료 → OIS → 엑셀 등록 → 엑셀 다운로드
    → Slurry 고정값 → 상태 안내
  */
  actionControls.append(
    loadButton,
    queryButton,
    excelButton,
    downloadButton,
    densityPanel
  );

  queryGroup.append(
    rangeControls,
    actionControls
  );

  periodFields.append(
    queryGroup
  );

  queryCard.classList.add(
    "auxiliary-material-query-card--grouped"
  );

  periodFields.classList.add(
    "auxiliary-material-period-fields--grouped"
  );

  view.classList.remove(
    "is-pc-compact-controls"
  );

  view.classList.add(
    "is-pc-grouped-controls"
  );

  /*
    저장 상태와 기존 엑셀 등록 안내를
    고정값 저장 버튼 오른쪽에 배치한다.
  */
  let statusRow =
    queryCard.querySelector(
      ".auxiliary-material-pc-status-row"
    );

  if (
    !statusRow
  ) {
    statusRow =
      document.createElement(
        "div"
      );

    statusRow.className =
      "auxiliary-material-pc-status-row";

    statusRow.setAttribute(
      "aria-label",
      "저장 상태 및 기존 엑셀 자료 등록"
    );
  }

  if (
    status
  ) {
    statusRow.append(
      status
    );
  }

  if (
    excelImportPanel
  ) {
    excelImportPanel.classList.add(
      "auxiliary-material-excel-import--compact"
    );

    statusRow.append(
      excelImportPanel
    );
  }

  if (
    statusRow.childElementCount >
      0
  ) {
    actionControls.append(
      statusRow
    );
  }
}

/* =====================================================
  엑셀 업로드 이벤트 연결
===================================================== */

function initializeAuxiliaryMaterialExcelImportControls() {
  const elements =
    getAuxiliaryMaterialElements();
    prepareAuxiliaryMaterialPcCompactControls();


  if (
    !elements.view ||
    !elements.excelImportButton ||
    !elements.excelFileInput
  ) {
    return;
  }


  if (
    elements
      .excelImportButton
      .dataset
      .auxiliaryMaterialExcelImportBound ===
      "true"
  ) {
    return;
  }


  elements.excelImportButton.addEventListener(
    "click",
    () => {
      if (
        auxiliaryMaterialExcelImportState
          .isRunning
      ) {
        return;
      }


      elements.excelFileInput.value =
        "";


      elements.excelFileInput.click();
    }
  );


  elements.excelFileInput.addEventListener(
    "change",
    handleAuxiliaryMaterialExcelFileSelection
  );


  elements
    .excelImportButton
    .dataset
    .auxiliaryMaterialExcelImportBound =
    "true";
}


/* =====================================================
  초기 실행
===================================================== */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialExcelImportControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialExcelImportControls();
}

/* =====================================================
  부재료 표 크게 보기 전환

  - 화면 크게 보기
  - Esc 키로 크게 보기 종료
  - 전환 전 스크롤 위치 유지
===================================================== */

const auxiliaryMaterialTableViewState = {
  isExpanded:
    false
};


function getAuxiliaryMaterialTableViewElements() {
  const view =
    document.getElementById(
      "efficiencyAuxiliaryMaterialsView"
    );


  const card =
    document.getElementById(
      "auxiliaryMaterialTableCard"
    );


  return {
    view,

    card,

    tableWrap:
      card?.querySelector(
        ".auxiliary-material-table-wrap"
      ) ||
      null,

    expandedButton:
      document.getElementById(
        "toggleAuxiliaryMaterialExpandedButton"
      )
  };
}

/* =====================================================
  표 스크롤 위치 복원
===================================================== */

function restoreAuxiliaryMaterialTableScroll(
  tableWrap,
  scrollLeft,
  scrollTop
) {
  if (
    !tableWrap
  ) {
    return;
  }


  window.requestAnimationFrame(
    () => {
      tableWrap.scrollLeft =
        scrollLeft;

      tableWrap.scrollTop =
        scrollTop;
    }
  );
}

/* =====================================================
  크게 보기 버튼 문구
===================================================== */

function updateAuxiliaryMaterialExpandedButton(
  button,
  isExpanded
) {
  if (
    !button
  ) {
    return;
  }


  const icon =
    document.createElement(
      "span"
    );


  icon.setAttribute(
    "aria-hidden",
    "true"
  );


  icon.textContent =
    isExpanded
      ? "×"
      : "⛶";


  button.replaceChildren(
    icon,

    document.createTextNode(
      isExpanded
        ? " 축소하기"
        : " 크게 보기"
    )
  );


  button.setAttribute(
    "aria-pressed",
    String(
      isExpanded
    )
  );


  button.title =
    isExpanded
      ? "원래 화면 크기로 돌아가기"
      : "부재료 표를 화면 전체로 보기";
}

/* =====================================================
  크게 보기 전환
===================================================== */

function setAuxiliaryMaterialExpandedView(
  isExpanded,
  options = {}
) {
  const {
    card,
    tableWrap,
    expandedButton
  } =
    getAuxiliaryMaterialTableViewElements();


  if (
    !card ||
    !expandedButton
  ) {
    return;
  }


  const nextState =
    Boolean(
      isExpanded
    );


  /*
    수치 수정 중 화면을 전환하면
    입력 중인 값이 사라질 수 있으므로 막는다.
  */
  if (
    auxiliaryMaterialValueEditState
      .isEditing &&
    nextState !==
      auxiliaryMaterialTableViewState
        .isExpanded
  ) {
    showToast(
      "수치 수정을 저장하거나 취소한 뒤 크게 보기를 전환해 주세요."
    );

    return;
  }


  const scrollLeft =
    tableWrap?.scrollLeft ||
    0;

  const scrollTop =
    tableWrap?.scrollTop ||
    0;


  auxiliaryMaterialTableViewState
    .isExpanded =
    nextState;


  card.classList.toggle(
    "is-expanded-view",
    nextState
  );


  document.body.classList.toggle(
    "is-auxiliary-material-expanded",
    nextState
  );


  updateAuxiliaryMaterialExpandedButton(
    expandedButton,
    nextState
  );


  /*
    기본 화면:
    1호기 표와 2호기 표를 위아래로 표시

    크게 보기:
    기존 1·2호기 통합표 표시
  */
  renderAuxiliaryMaterialHistory();


  restoreAuxiliaryMaterialTableScroll(
    tableWrap,
    scrollLeft,
    scrollTop
  );


  if (
    !nextState &&
    options.focusButton ===
      true
  ) {
    window.requestAnimationFrame(
      () => {
        expandedButton.focus({
          preventScroll:
            true
        });
      }
    );
  }
}


/* =====================================================
  크게 보기 상태에서 Esc 처리

  다른 모달의 Esc 동작보다 먼저 처리한다.
===================================================== */

function handleAuxiliaryMaterialExpandedEscape(
  event
) {
  if (
    event.key !==
      "Escape" ||
    !auxiliaryMaterialTableViewState
      .isExpanded
  ) {
    return;
  }


  event.preventDefault();

  event.stopImmediatePropagation();


  setAuxiliaryMaterialExpandedView(
    false,
    {
      focusButton:
        true
    }
  );
}

/* =====================================================
  부재료 표 크게 보기 버튼 초기화
===================================================== */

function initializeAuxiliaryMaterialTableViewControls() {
  const {
    view,
    card,
    expandedButton
  } =
    getAuxiliaryMaterialTableViewElements();


  if (
    !view ||
    !card ||
    !expandedButton
  ) {
    return;
  }


  if (
    card.dataset
      .auxiliaryMaterialViewBound ===
    "true"
  ) {
    return;
  }


  /*
    처음 열 때는 기본 크기로 시작한다.
  */

  setAuxiliaryMaterialExpandedView(
    false
  );


  /*
    크게 보기·축소하기 전환
  */

  expandedButton.addEventListener(
    "click",
    () => {
      setAuxiliaryMaterialExpandedView(
        !auxiliaryMaterialTableViewState
          .isExpanded
      );
    }
  );


  /*
    크게 보기 상태에서 Esc로 종료
  */

  document.addEventListener(
    "keydown",
    handleAuxiliaryMaterialExpandedEscape,
    true
  );


  card.dataset
    .auxiliaryMaterialViewBound =
    "true";
}

/* =====================================================
  부재료 표 보기 버튼 초기 실행
===================================================== */

if (
  document.readyState ===
    "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialTableViewControls,
    {
      once:
        true
    }
  );

} else {
  initializeAuxiliaryMaterialTableViewControls();
}

/* =========================================================
  효율팀 - 부재료 OIS 조회 · D1 저장

  - create_materials_batch 요청
  - 날짜별 요청 상태를 2초마다 확인
  - 완료된 날짜의 D1 자료를 표에 즉시 반영
  - 최대 90회 진행 상태 확인
========================================================= */

const auxiliaryMaterialOisQueryState = {
  timer: null,
  pollCount: 0,
  pollCursor: 0,
  maxPollCount: 90,
  startDate: "",
  endDate: "",
  expectedDayCount: 0,
  requestItems: [],
  isRunning: false
};


function setAuxiliaryMaterialOisQueryButtonState(isRunning) {
  const { queryButton } =
    getAuxiliaryMaterialElements();

  if (!queryButton) return;

  queryButton.disabled = isRunning;
  queryButton.textContent = isRunning
    ? "OIS 조회 · D1 저장 중..."
    : "OIS 조회 · D1 저장";
}


function stopAuxiliaryMaterialOisPolling() {
  if (auxiliaryMaterialOisQueryState.timer) {
    window.clearTimeout(
      auxiliaryMaterialOisQueryState.timer
    );

    auxiliaryMaterialOisQueryState.timer = null;
  }

  auxiliaryMaterialOisQueryState.isRunning = false;

  setAuxiliaryMaterialOisQueryButtonState(false);
}


async function readAuxiliaryMaterialOisJsonResponse(response) {
  const result =
    await response
      .json()
      .catch(() => ({}));

  if (
    !response.ok ||
    result.ok === false
  ) {
    throw new Error(
      result.message ||
      result.error ||
      (
        "부재료 OIS 요청을 처리하지 못했습니다. " +
        `(HTTP ${response.status})`
      )
    );
  }

  return result;
}


function normalizeAuxiliaryMaterialOisRequestItem(item) {
  const disposition =
    String(
      item?.disposition ||
      ""
    )
      .trim()
      .toLowerCase();

  const status =
    disposition === "saved"
      ? "complete"
      : String(
          item?.status ||
          "pending"
        )
          .trim()
          .toLowerCase();

  return {
    ...item,

    id:
      String(
        item?.id ||
        ""
      ).trim(),

    targetDate:
      String(
        item?.targetDate ||
        item?.target_date ||
        ""
      ).trim(),

    disposition,
    status
  };
}


function getAuxiliaryMaterialOisProgressCounts() {
  const counts = {
    total:
      Math.max(
        0,
        Number(
          auxiliaryMaterialOisQueryState
            .expectedDayCount
        ) ||
        auxiliaryMaterialOisQueryState
          .requestItems
          .length
      ),

    complete: 0,
    processing: 0,
    pending: 0,
    failed: 0,
    unknown: 0
  };

  auxiliaryMaterialOisQueryState
    .requestItems
    .forEach(item => {
      if (
        Object.prototype
          .hasOwnProperty
          .call(
            counts,
            item.status
          )
      ) {
        counts[item.status] += 1;

      } else {
        counts.unknown += 1;
      }
    });

  const countedTotal =
    counts.complete +
    counts.processing +
    counts.pending +
    counts.failed +
    counts.unknown;

  if (
    countedTotal <
    counts.total
  ) {
    counts.unknown +=
      counts.total -
      countedTotal;
  }

  counts.finished =
    counts.complete +
    counts.failed;

  counts.remaining =
    Math.max(
      0,
      counts.total -
      counts.finished
    );

  return counts;
}


async function getAuxiliaryMaterialOisRequestStatus(
  requestId
) {
  const query =
    new URLSearchParams({
      id:
        requestId,

      _:
        String(
          Date.now()
        )
    });

  const response =
    await fetch(
      (
        "/api/ois-data-requests?" +
        query.toString()
      ),
      {
        method:
          "GET",

        headers:
          typeof getShiftLogAuthHeaders ===
            "function"
            ? getShiftLogAuthHeaders()
            : {
                Accept:
                  "application/json"
              },

        cache:
          "no-store"
      }
    );

  return await readAuxiliaryMaterialOisJsonResponse(
    response
  );
}


async function refreshAuxiliaryMaterialOisStatusSlice() {
  const pendingItems =
    auxiliaryMaterialOisQueryState
      .requestItems
      .filter(item => {
        return (
          Boolean(item.id) &&
          [
            "pending",
            "processing"
          ].includes(
            item.status
          )
        );
      });

  if (
    pendingItems.length <
    1
  ) {
    return;
  }

  const startIndex =
    auxiliaryMaterialOisQueryState
      .pollCursor %
    pendingItems.length;

  const selectedItems = [];

  for (
    let offset = 0;
    offset <
      Math.min(
        12,
        pendingItems.length
      );
    offset += 1
  ) {
    selectedItems.push(
      pendingItems[
        (
          startIndex +
          offset
        ) %
        pendingItems.length
      ]
    );
  }

  auxiliaryMaterialOisQueryState.pollCursor =
    (
      startIndex +
      selectedItems.length
    ) %
    Math.max(
      pendingItems.length,
      1
    );

  const results =
    await Promise.allSettled(
      selectedItems.map(item =>
        getAuxiliaryMaterialOisRequestStatus(
          item.id
        )
      )
    );

  results.forEach(
    (
      result,
      resultIndex
    ) => {
      if (
        result.status !== "fulfilled" ||
        !result.value?.item
      ) {
        return;
      }

      const selectedItem =
        selectedItems[
          resultIndex
        ];

      const refreshedItem =
        normalizeAuxiliaryMaterialOisRequestItem({
          ...selectedItem,
          ...result.value.item,

          disposition:
            selectedItem.disposition
        });

      const stateIndex =
        auxiliaryMaterialOisQueryState
          .requestItems
          .findIndex(
            item =>
              item.id ===
              selectedItem.id
          );

      if (
        stateIndex >= 0
      ) {
        auxiliaryMaterialOisQueryState
          .requestItems[
            stateIndex
          ] =
          refreshedItem;
      }
    }
  );
}


function isAuxiliaryMaterialOisRangeStillSelected() {
  try {
    const range =
      readAuxiliaryMaterialDateRange();

    return (
      range.startDate ===
        auxiliaryMaterialOisQueryState
          .startDate &&
      range.endDate ===
        auxiliaryMaterialOisQueryState
          .endDate
    );

  } catch {
    return false;
  }
}


function scheduleAuxiliaryMaterialOisPolling() {
  /*
    부재료 OIS 진행 상태는
    자동으로 반복 확인하지 않는다.
  */
  stopAuxiliaryMaterialOisPolling();
}


async function pollAuxiliaryMaterialOisProgress() {
  /*
    저장자료 확인은 사용자가
    보기 버튼을 눌렀을 때만 실행한다.
  */
  stopAuxiliaryMaterialOisPolling();
}

async function createAuxiliaryMaterialOisQuery() {
  try {
    const range =
      readAuxiliaryMaterialDateRange();

    if (
      range.dayCount > 62
    ) {
      throw new Error(
        "부재료 OIS 조회 기간은 한 번에 62일 이하로 선택해 주세요."
      );
    }

    /*
      이전 실행에서 남아 있을 수 있는
      자동 확인 타이머를 먼저 제거한다.
    */
    stopAuxiliaryMaterialOisPolling();

    Object.assign(
      auxiliaryMaterialOisQueryState,
      {
        pollCount: 0,
        pollCursor: 0,

        startDate:
          range.startDate,

        endDate:
          range.endDate,

        expectedDayCount:
          range.dayCount,

        requestItems: [],

        isRunning:
          true
      }
    );

    setAuxiliaryMaterialOisQueryButtonState(
      true
    );

    setAuxiliaryMaterialStatus(
      (
        `${range.startDate} ~ ${range.endDate} ` +
        "저장 여부를 확인하고 있습니다."
      ),
      "loading"
    );

    const response =
      await fetch(
        "/api/ois-data-requests",
        {
          method:
            "POST",

          headers:
            typeof getShiftLogAuthHeaders ===
              "function"
              ? getShiftLogAuthHeaders({
                  "Content-Type":
                    "application/json"
                })
              : {
                  Accept:
                    "application/json",

                  "Content-Type":
                    "application/json"
                },

          cache:
            "no-store",

          body:
            JSON.stringify({
              action:
                "create_materials_batch",

              startDate:
                range.startDate,

              endDate:
                range.endDate,

              /*
                저장 완료 날짜는
                강제로 다시 조회하지 않는다.
              */
              forceRefresh:
                false
            })
        }
      );

    const result =
      await readAuxiliaryMaterialOisJsonResponse(
        response
      );

    const createdCount =
      Math.max(
        0,
        Number(
          result.createdCount
        ) || 0
      );

    const reusedCount =
      Math.max(
        0,
        Number(
          result.reusedCount
        ) || 0
      );

    const savedCount =
      Math.max(
        0,
        Number(
          result.savedCount
        ) || 0
      );

    auxiliaryMaterialOisQueryState
      .expectedDayCount =
      Number(
        result.range
          ?.dayCount ||
        range.dayCount
      );

    auxiliaryMaterialOisQueryState
      .requestItems =
      (
        Array.isArray(
          result.items
        )
          ? result.items
          : []
      ).map(
        normalizeAuxiliaryMaterialOisRequestItem
      );

    /*
      등록 응답까지만 확인한다.
      이후 상태 폴링과 저장자료 GET은 하지 않는다.
    */
    stopAuxiliaryMaterialOisPolling();

    if (
      createdCount < 1 &&
      reusedCount < 1
    ) {
      setAuxiliaryMaterialStatus(
        (
          `선택 범위 ${savedCount}일은 ` +
          "모두 저장자료를 사용합니다. " +
          "새 OIS 요청은 없습니다."
        ),
        "complete"
      );

      return result;
    }

    const isPeriodMode =
      getAuxiliaryMaterialElements()
        .periodModeInput
        ?.checked === true;

    const viewButtonText =
      isPeriodMode
        ? "기간 저장자료 보기"
        : "월 저장자료 보기";

    setAuxiliaryMaterialStatus(
      (
        `저장자료 ${savedCount}일 제외 · ` +
        `신규 OIS ${createdCount}일 · ` +
        `이미 진행 중 ${reusedCount}일. ` +
        "자동 진행 확인은 하지 않습니다. " +
        `완료 후 '${viewButtonText}'를 눌러 확인하세요.`
      ),
      "idle"
    );

    if (
      typeof showToast ===
        "function"
    ) {
      if (
        createdCount > 0
      ) {
        showToast(
          `부재료 OIS ${createdCount}일을 등록했습니다.`
        );

      } else if (
        reusedCount > 0
      ) {
        showToast(
          `이미 진행 중인 OIS 요청 ${reusedCount}일을 사용합니다.`
        );
      }
    }

    return result;

  } catch (error) {
    stopAuxiliaryMaterialOisPolling();

    const message =
      error instanceof Error
        ? error.message
        : "부재료 OIS 조회를 등록하지 못했습니다.";

    setAuxiliaryMaterialStatus(
      message,
      "error"
    );

    if (
      typeof showToast ===
        "function"
    ) {
      showToast(
        message
      );
    }

    return null;
  }
}

function initializeAuxiliaryMaterialOisQueryControls() {
  const elements =
    getAuxiliaryMaterialElements();

  if (
    !elements.view ||
    !elements.queryButton
  ) {
    return;
  }

  if (
    elements
      .queryButton
      .dataset
      .auxiliaryMaterialOisBound ===
    "true"
  ) {
    return;
  }

  elements.queryButton.addEventListener(
    "click",
    createAuxiliaryMaterialOisQuery
  );

  elements
    .queryButton
    .dataset
    .auxiliaryMaterialOisBound =
    "true";
}


if (
  document.readyState ===
  "loading"
) {
  document.addEventListener(
    "DOMContentLoaded",
    initializeAuxiliaryMaterialOisQueryControls,
    {
      once: true
    }
  );

} else {
  initializeAuxiliaryMaterialOisQueryControls();
}

