  function openArmRollBoxMobileAlertDetail() {
    const modal =
      ensureArmRollBoxMobileAlertUi();


    const sourceText =
      String(
        document.getElementById(
          "armRollBoxMainAlertText"
        )?.textContent ||
        ""
      ).trim();


    const sourceReference =
      String(
        document.getElementById(
          "armRollBoxMainAlertReference"
        )?.textContent ||
        ""
      ).trim();


    const sourceCount =
      String(
        document.getElementById(
          "armRollBoxMainAlertCount"
        )?.textContent ||
        ""
      ).trim();


    const summary =
      document.getElementById(
        "armRollBoxMobileAlertSummary"
      );


    const message =
      document.getElementById(
        "armRollBoxMobileAlertMessage"
      );


    const reference =
      document.getElementById(
        "armRollBoxMobileAlertReference"
      );


    if (
      summary
    ) {
      summary.textContent =
        sourceCount
          ? `확인 필요 ${sourceCount}`
          : "확인이 필요한 항목이 있습니다.";
    }


    if (
      message
    ) {
      message.textContent =
        sourceText ||
        "ARM ROLL BOX 상태를 확인해 주세요.";
    }


    if (
      reference
    ) {
      reference.textContent =
        sourceReference;


      reference.hidden =
        !sourceReference;
    }


    modal.hidden =
      false;


    modal.setAttribute(
      "aria-hidden",
      "false"
    );


    document.body.classList.add(
      "arm-roll-box-mobile-alert-open"
    );
  }


