  /* =====================================================
    문자열
  ====================================================== */

  function normalizeText(
    value
  ) {
    return String(
      value ??
      ""
    ).trim();
  }


  /* =====================================================
    숫자 읽기

    지원:
    1234.56
    1,234.56
    1,234.56 t
    84.558 %
  ====================================================== */

  function parseNumber(
    value
  ) {
    const normalizedValue =
      normalizeText(
        value
      )
        .replaceAll(
          ",",
          ""
        );


    if (
      !normalizedValue ||
      normalizedValue ===
        "-"
    ) {
      return null;
    }


    const match =
      normalizedValue.match(
        /-?\d+(?:\.\d+)?/
      );


    if (
      !match
    ) {
      return null;
    }


    const numericValue =
      Number(
        match[0]
      );


    return Number.isFinite(
      numericValue
    )
      ? numericValue
      : null;
  }


  /* =====================================================
    일반 숫자 표시

    수처리:
    소수점 3자리
  ====================================================== */

function formatNumber(
  value,
  digits = 2
) {
  const numericValue =
    Number(
      value
    );


  if (
    !Number.isFinite(
      numericValue
    )
  ) {
    return "-";
  }


  const maximumDigits =
    Math.min(
      2,
      Math.max(
        0,
        Number(
          digits
        ) || 0
      )
    );


  return numericValue.toLocaleString(
    "ko-KR",
    {
      minimumFractionDigits:
        0,

      maximumFractionDigits:
        maximumDigits
    }
  );
}


  /* =====================================================
    석회석 숫자 표시

    기존 석회석 계산 화면과 동일:
    소수점 둘째 자리 아래 절삭
  ====================================================== */

  function formatLimestoneNumber(
    value
  ) {
    const numericValue =
      Number(
        value
      );


    if (
      !Number.isFinite(
        numericValue
      )
    ) {
      return "-";
    }


    const truncatedValue =
      Math.trunc(
        numericValue *
        100
      ) /
      100;


    return truncatedValue.toLocaleString(
      "ko-KR",
      {
        minimumFractionDigits:
          2,

        maximumFractionDigits:
          2
      }
    );
  }


  /* =====================================================
    텍스트 적용
  ====================================================== */

  function setText(
    element,
    value
  ) {
    if (
      !element
    ) {
      return;
    }


    const nextValue =
      String(
        value ??
        "-"
      );


    if (
      element.textContent !==
      nextValue
    ) {
      element.textContent =
        nextValue;
    }
  }


  /* =====================================================
    상태 배지
  ====================================================== */

  function setBadge(
    element,
    status,
    label
  ) {
    if (
      !element
    ) {
      return;
    }


    element.classList.remove(
      "is-loading",
      "is-complete",
      "is-error"
    );


    if (
      status ===
        "loading"
    ) {
      element.classList.add(
        "is-loading"
      );

    } else if (
      status ===
        "complete"
    ) {
      element.classList.add(
        "is-complete"
      );

    } else if (
      status ===
        "error"
    ) {
      element.classList.add(
        "is-error"
      );
    }


    setText(
      element,
      label
    );
  }


/* =====================================================
  오전회의 자동자료 기준일

  우선순위:
  1. 공용 날짜 이동 버튼의 기준일
  2. 현재 석회석 계산 날짜
  3. 현재 수처리 요청 날짜
  4. 완료된 수처리 저장값
  5. 교대파트 기준일

  중요:
  이미 조회된 과거 수처리 날짜가
  새 공용 날짜보다 먼저 선택되지 않도록 한다.
===================================================== */

function getExpectedPreviousDate() {
  const state =
    getState();


  const commonPanel =
    document.getElementById(
      "efficiencyMorningMeetingWaterPanel"
    );


  /* ===================================================
    1. 공용 자료 기준일

    [전날] [오늘] [다음날]에서 설정한 날짜
  ==================================================== */

  const commonBaseDate =
    normalizeText(
      commonPanel?.dataset
        .morningMeetingAutoBaseDate
    );


  if (
    /^\d{4}-\d{2}-\d{2}$/.test(
      commonBaseDate
    )
  ) {
    return commonBaseDate;
  }


  /* ===================================================
    2. 현재 석회석 계산 날짜
  ==================================================== */

  const limestoneDate =
    normalizeText(
      document.getElementById(
        "limestoneUsageDate"
      )?.value
    );


  if (
    /^\d{4}-\d{2}-\d{2}$/.test(
      limestoneDate
    )
  ) {
    return limestoneDate;
  }


  /* ===================================================
    3. 현재 수처리 요청 날짜

    완료된 과거 state 값보다 먼저 확인한다.
  ==================================================== */

  const waterTargetDate =
    normalizeText(
      commonPanel?.dataset
        .waterTargetDate
    );


  if (
    /^\d{4}-\d{2}-\d{2}$/.test(
      waterTargetDate
    )
  ) {
    return waterTargetDate;
  }


  /* ===================================================
    4. 완료된 수처리 결과
  ==================================================== */


  const water =
    state.waterTreatment &&
    typeof state.waterTreatment ===
      "object"
      ? state.waterTreatment
      : null;


  const savedWaterDate =
    normalizeText(
      water?.sourceDate ||
      water?.targetDate ||
      ""
    );


  if (
    /^\d{4}-\d{2}-\d{2}$/.test(
      savedWaterDate
    )
  ) {
    return savedWaterDate;
  }

  /* ===================================================
    5. 교대파트 기준일
  ==================================================== */

  return normalizeText(
    state.shiftPart?.reportDate ||
    state.shiftPart?.loadedDate ||
    ""
  );
}


  /* =====================================================
    수처리 데이터
  ====================================================== */

  function getWaterData() {
    const state =
      getState();


    const elements =
      getElements();


    const water =
      state.waterTreatment &&
      typeof state.waterTreatment ===
        "object"
        ? state.waterTreatment
        : null;


    const rawStatus =
      normalizeText(
        elements.waterSourcePanel
          ?.dataset
          .waterStatus
      ).toLowerCase();


    if (
      !water
    ) {
      return {
        status:
          rawStatus ===
            "loading"
            ? "loading"
            : rawStatus ===
                "error"
              ? "error"
              : "idle",

        date:
          normalizeText(
            elements.waterSourcePanel
              ?.dataset
              .waterTargetDate
          )
      };
    }


    const rawWaterInflow =
      parseNumber(
        water.rawWaterInflow
      );


    const demiProduction =
      parseNumber(
        water.demiProduction
      );


    const pureWaterUsage =
      parseNumber(
        water.pureWaterUsage
      );


    const rawWaterTankAmount =
      parseNumber(
        water.rawWaterTankAmount
      );


    const rawWaterTankRate =
      parseNumber(
        water.rawWaterTankRate
      );


    const filteredWaterTankAmount =
      parseNumber(
        water.filteredWaterTankAmount
      );


    const filteredWaterTankRate =
      parseNumber(
        water.filteredWaterTankRate
      );


    const demiWaterTankAmount =
      parseNumber(
        water.demiWaterTankAmount
      );


    const demiWaterTankRate =
      parseNumber(
        water.demiWaterTankRate
      );


    const requiredValues = [
      rawWaterInflow,
      demiProduction,
      pureWaterUsage,
      rawWaterTankAmount,
      rawWaterTankRate,
      filteredWaterTankAmount,
      filteredWaterTankRate,
      demiWaterTankAmount,
      demiWaterTankRate
    ];


    const isComplete =
      requiredValues.every(
        value => {
          return value !==
            null;
        }
      );


    let status =
      "idle";


    if (
      rawStatus ===
        "error"
    ) {
      status =
        "error";

    } else if (
      rawStatus ===
        "loading"
    ) {
      status =
        "loading";

    } else if (
      isComplete
    ) {
      status =
        "complete";
    }


    return {
      status,

      date:
        normalizeText(
          water.sourceDate ||
          water.targetDate ||
          elements.waterSourcePanel
            ?.dataset
            .waterTargetDate
        ),

      rawWaterInflow,

      demiProduction,

      pureWaterUsage,

      rawWaterTankAmount,

      rawWaterTankRate,

      filteredWaterTankAmount,

      filteredWaterTankRate,

      demiWaterTankAmount,

      demiWaterTankRate
    };
  }


/* =====================================================
    석회석 데이터

    기존 계산 화면에서 직접 읽는다.
====================================================== */

function getLimestoneData() {
  const elements =
    getElements();


  const date =
    normalizeText(
      elements
        .limestoneSourceDate
        ?.value
    );


  const unitOneStart =
    parseNumber(
      elements
        .limestoneUnitOneStart
        ?.value
    );


  const unitOneReceipt =
    parseNumber(
      elements
        .limestoneUnitOneReceipt
        ?.textContent
    );


  const unitOneEnd =
    parseNumber(
      elements
        .limestoneUnitOneEnd
        ?.value
    );


  const unitOneUsage =
    parseNumber(
      elements
        .limestoneUnitOneUsage
        ?.textContent
    );


  const unitTwoStart =
    parseNumber(
      elements
        .limestoneUnitTwoStart
        ?.value
    );


  const unitTwoReceipt =
    parseNumber(
      elements
        .limestoneUnitTwoReceipt
        ?.textContent
    );


  const unitTwoEnd =
    parseNumber(
      elements
        .limestoneUnitTwoEnd
        ?.value
    );


  const unitTwoUsage =
    parseNumber(
      elements
        .limestoneUnitTwoUsage
        ?.textContent
    );


  const rawStatus =
    normalizeText(
      elements
        .limestoneSourceView
        ?.dataset
        .limestoneUsageStatus
    ).toLowerCase();


  /*
    D1 저장값을 복원하고 있는 상태

    실제 OIS 조회 중인 loading과 구분한다.
  */
  const isRestoringSaved =
    rawStatus ===
      "restoring";


  const requiredValues = [
    unitOneStart,
    unitOneReceipt,
    unitOneEnd,
    unitOneUsage,
    unitTwoStart,
    unitTwoReceipt,
    unitTwoEnd,
    unitTwoUsage
  ];


  const hasCompleteValues =
    requiredValues.every(
      value => {
        return value !==
          null;
      }
    );


  const expectedDate =
    getExpectedPreviousDate();


  const hasDateMismatch =
    Boolean(
      expectedDate &&
      date &&
      expectedDate !==
        date
    );


  let status =
    "idle";


  if (
    rawStatus ===
      "error" ||
    hasDateMismatch
  ) {
    status =
      "error";

  } else if (
    rawStatus ===
      "loading" ||
    isRestoringSaved
  ) {
    /*
      자동수치 전체 상태에서는
      저장값 복원도 진행 중으로 처리한다.
    */
    status =
      "loading";

  } else if (
    hasCompleteValues
  ) {
    status =
      "complete";
  }


  return {
    status,

    isRestoringSaved,

    hasDateMismatch,

    expectedDate,

    date,

    unitOneStart,

    unitOneReceipt,

    unitOneEnd,

    unitOneUsage,

    unitTwoStart,

    unitTwoReceipt,

    unitTwoEnd,

    unitTwoUsage
  };
}

/* =====================================================
    Gear Wheel / Pinion 데이터
====================================================== */

  function getGearPinionData() {
    const state =
      getState();


    const elements =
      getElements();


    const gearPinion =
      state.gearPinion &&
      typeof state.gearPinion ===
        "object"
        ? state.gearPinion
        : null;


    const rawStatus =
      normalizeText(
        elements.waterSourcePanel
          ?.dataset
          .gearPinionStatus
      ).toLowerCase();


    if (
      !gearPinion
    ) {
      return {
        status:
          rawStatus ===
            "loading"
            ? "loading"
            : rawStatus ===
                "error"
              ? "error"
              : "idle",

        date:
          normalizeText(
            elements.waterSourcePanel
              ?.dataset
              .gearPinionTargetDate
          )
      };
    }


    const gearWheel =
      parseNumber(
        gearPinion.gearWheel
      );


    const pinion =
      parseNumber(
        gearPinion.pinion
      );


    const isComplete =
      gearWheel !==
        null &&
      pinion !==
        null;


    let status =
      "idle";


    if (
      rawStatus ===
        "error"
    ) {
      status =
        "error";

    } else if (
      rawStatus ===
        "loading"
    ) {
      status =
        "loading";

    } else if (
      isComplete
    ) {
      status =
        "complete";
    }


    return {
      status,

      date:
        normalizeText(
          gearPinion.targetDate ||
          gearPinion.sourceDate ||
          elements.waterSourcePanel
            ?.dataset
            .gearPinionTargetDate
        ),

      gearWheel,

      pinion
    };
  }

  /* =====================================================
  BO1 · BO2 보일러 온도 상태

  총 12개:
  - 1호기 FBHE L / R
  - 1호기 Wall A / B / C / D
  - 2호기 FBHE L / R
  - 2호기 Wall A / B / C / D

  사용자가 직접 수정한 값도
  state.boilerTemperatures에 저장되어 있으므로
  동일하게 검사한다.
===================================================== */

function getBoilerData() {
  const state =
    getState();


  const boilerTemperatures =
    state.boilerTemperatures &&
    typeof state.boilerTemperatures ===
      "object"
      ? state.boilerTemperatures
      : null;


  if (
    !boilerTemperatures
  ) {
    return {
      status:
        "idle",

      date:
        "",

      complete:
        false,

      missing:
        []
    };
  }


  const unitOne =
    boilerTemperatures.unitOne;


  const unitTwo =
    boilerTemperatures.unitTwo;


  const requiredValues = [
    unitOne?.fbheLeft,
    unitOne?.fbheRight,

    unitOne?.wallScrew?.A,
    unitOne?.wallScrew?.B,
    unitOne?.wallScrew?.C,
    unitOne?.wallScrew?.D,

    unitTwo?.fbheLeft,
    unitTwo?.fbheRight,

    unitTwo?.wallScrew?.A,
    unitTwo?.wallScrew?.B,
    unitTwo?.wallScrew?.C,
    unitTwo?.wallScrew?.D
  ];


  const complete =
    requiredValues.length ===
      12 &&
    requiredValues.every(
      value => {
        return parseNumber(
          value
        ) !==
          null;
      }
    );


  const missing =
    Array.isArray(
      boilerTemperatures.missing
    )
      ? boilerTemperatures
          .missing
      : [];


  return {
    status:
      complete
        ? "complete"
        : "error",

    date:
      normalizeText(
        boilerTemperatures.reportDate
      ),

    complete,

    missing,

    userEdited:
      boilerTemperatures.userEdited ===
      true
  };
}

  /* =====================================================
    수처리 미리보기 출력
  ====================================================== */

  function renderWaterPreview(
    data
  ) {
    const elements =
      getElements();


    setText(
      elements.waterDate,
      data.date ||
      "-"
    );


    if (
      data.status ===
        "complete"
    ) {
      setBadge(
        elements.waterStatus,
        "complete",
        "조회 완료"
      );

    } else if (
      data.status ===
        "loading"
    ) {
      setBadge(
        elements.waterStatus,
        "loading",
        "조회 중"
      );

    } else if (
      data.status ===
        "error"
    ) {
      setBadge(
        elements.waterStatus,
        "error",
        "조회 실패"
      );

    } else {
      setBadge(
        elements.waterStatus,
        "idle",
        "조회 대기"
      );
    }


    setText(
      elements.waterRawInflow,

      data.rawWaterInflow ===
        null ||
      data.rawWaterInflow ===
        undefined
        ? "-"
        : formatNumber(
            data.rawWaterInflow
          )
    );


    const hasDemiFlow =
      data.demiProduction !==
        null &&
      data.demiProduction !==
        undefined &&
      data.pureWaterUsage !==
        null &&
      data.pureWaterUsage !==
        undefined;


    setText(
      elements.waterDemiFlow,

      hasDemiFlow
        ? `${formatNumber(
            data.demiProduction
          )} / ${formatNumber(
            data.pureWaterUsage
          )}`
        : "- / -"
    );


    const hasRawTank =
      data.rawWaterTankAmount !==
        null &&
      data.rawWaterTankAmount !==
        undefined &&
      data.rawWaterTankRate !==
        null &&
      data.rawWaterTankRate !==
        undefined;


    setText(
      elements.waterRawTank,

      hasRawTank
        ? `${formatNumber(
            data.rawWaterTankAmount
          )} / ${formatNumber(
            data.rawWaterTankRate
          )}%`
        : "- / -%"
    );


    const hasFilteredTank =
      data.filteredWaterTankAmount !==
        null &&
      data.filteredWaterTankAmount !==
        undefined &&
      data.filteredWaterTankRate !==
        null &&
      data.filteredWaterTankRate !==
        undefined;


    setText(
      elements.waterFilteredTank,

      hasFilteredTank
        ? `${formatNumber(
            data.filteredWaterTankAmount
          )} / ${formatNumber(
            data.filteredWaterTankRate
          )}%`
        : "- / -%"
    );


    const hasDemiTank =
      data.demiWaterTankAmount !==
        null &&
      data.demiWaterTankAmount !==
        undefined &&
      data.demiWaterTankRate !==
        null &&
      data.demiWaterTankRate !==
        undefined;


    setText(
      elements.waterDemiTank,

      hasDemiTank
        ? `${formatNumber(
            data.demiWaterTankAmount
          )} / ${formatNumber(
            data.demiWaterTankRate
          )}%`
        : "- / -%"
    );
  }


/* =====================================================
    석회석 미리보기 출력
====================================================== */

function renderLimestonePreview(
  data
) {
  const elements =
    getElements();


  setText(
    elements.limestoneDate,
    data.date ||
    "-"
  );


  if (
    data.hasDateMismatch
  ) {
    setBadge(
      elements.limestoneStatus,
      "error",
      "날짜 확인"
    );

  } else if (
    data.status ===
      "complete"
  ) {
    setBadge(
      elements.limestoneStatus,
      "complete",
      "계산 완료"
    );

  } else if (
    data.status ===
      "loading"
  ) {
    setBadge(
      elements.limestoneStatus,
      "loading",

      data.isRestoringSaved
        ? "저장값 불러오는 중"
        : "조회 중"
    );

  } else if (
    data.status ===
      "error"
  ) {
    setBadge(
      elements.limestoneStatus,
      "error",
      "조회 실패"
    );

  } else {
    setBadge(
      elements.limestoneStatus,
      "idle",
      "계산 대기"
    );
  }


  const hasUnitOneStock =
    data.unitOneStart !==
      null &&
    data.unitOneEnd !==
      null;


  setText(
    elements.limestoneUnitOneStock,

    hasUnitOneStock
      ? `${formatLimestoneNumber(
          data.unitOneStart
        )} → ${formatLimestoneNumber(
          data.unitOneEnd
        )}`
      : "- → -"
  );


  const hasUnitTwoStock =
    data.unitTwoStart !==
      null &&
    data.unitTwoEnd !==
      null;


  setText(
    elements.limestoneUnitTwoStock,

    hasUnitTwoStock
      ? `${formatLimestoneNumber(
          data.unitTwoStart
        )} → ${formatLimestoneNumber(
          data.unitTwoEnd
        )}`
      : "- → -"
  );


  const unitOneReceiptText =
    data.unitOneReceipt !==
      null
      ? `${formatLimestoneNumber(
          data.unitOneReceipt
        )} t`
      : "-";


  const unitTwoReceiptText =
    data.unitTwoReceipt !==
      null
      ? `${formatLimestoneNumber(
          data.unitTwoReceipt
        )} t`
      : "-";


  const hasReceiptColumns =
    elements.limestoneReceiptUnitOne &&
    elements.limestoneReceiptUnitTwo;


  if (
    hasReceiptColumns
  ) {
    setText(
      elements.limestoneReceiptUnitOne,
      unitOneReceiptText
    );


    setText(
      elements.limestoneReceiptUnitTwo,
      unitTwoReceiptText
    );

  } else {
    setText(
      elements.limestoneReceipt,
      `${unitOneReceiptText} / ${unitTwoReceiptText}`
    );
  }


  const unitOneUsageText =
    data.unitOneUsage !==
      null
      ? `${formatLimestoneNumber(
          data.unitOneUsage
        )} t`
      : "-";


  const unitTwoUsageText =
    data.unitTwoUsage !==
      null
      ? `${formatLimestoneNumber(
          data.unitTwoUsage
        )} t`
      : "-";


  const hasUsageColumns =
    elements.limestoneUsageUnitOne &&
    elements.limestoneUsageUnitTwo;


  if (
    hasUsageColumns
  ) {
    setText(
      elements.limestoneUsageUnitOne,
      unitOneUsageText
    );


    setText(
      elements.limestoneUsageUnitTwo,
      unitTwoUsageText
    );

  } else {
    setText(
      elements.limestoneUsage,
      `${unitOneUsageText} / ${unitTwoUsageText}`
    );
  }
}

