    `;
  }

  let card =
    byId(
      "efficiencyMorningMeetingAutoSmpCard"
    );

  if (
    card &&
    card.dataset
      .smpLayoutVersion !==
      LAYOUT_VERSION
  ) {
    card.remove();

    card =
      null;
  }

  if (
    card
  ) {
    return card;
  }

  card =
    document.createElement(
      "article"
    );

  card.id =
    "efficiencyMorningMeetingAutoSmpCard";

  card.className =
    "efficiency-morning-meeting-auto-card is-smp-price";

  card.dataset.smpLayoutVersion =
    LAYOUT_VERSION;

  card.innerHTML = `
